/* Richer replacements for shorter texts across the app, written to the rules in CLAUDE.md.
   Each entry replaces the text at a path in AstroDeep; "*" means every item at that level. */
(function () {
  const D = window.AstroDeep;
  if (!D) return;
  function apply(path, data) {
    let root = D;
    if (path.startsWith("@content.")) { root = window.AstroContent; path = path.slice(9); }
    if (!root) return;
    const parts = path.split(".");
    const star = parts.indexOf("*");
    if (star < 0) {
      let o = root;
      for (const p of parts) o = o && o[p];
      if (o) for (const k of Object.keys(data)) o[k] = data[k];
      return;
    }
    let base = root;
    for (const p of parts.slice(0, star)) base = base && base[p];
    const field = parts.slice(star + 1);
    if (!base) return;
    for (const k of Object.keys(data)) {
      let o = base[k];
      for (const p of field.slice(0, -1)) o = o && o[p];
      if (o) o[field[field.length - 1]] = data[k];
    }
  }
  const R = [
    ["asteroids.ceres.houses", {
      "1": "You are the one people drift towards at a party when they need to talk, and strangers tell you things in queues. Care is written into how you arrive: a softness in the face, a habit of checking everyone has a drink before you pour your own. Your body keeps honest accounts, so a skipped lunch or a short night shows on you within hours, in your skin, your temper, your shoulders. Tending yourself with proper meals, clothes that feel good and enough sleep is where your capacity to tend others starts. Trouble comes when being needed turns into who you are, and a quiet evening with nobody to look after leaves you strangely unsure of yourself. You are loved for more than your usefulness, and believing it is part of your life's work.",
      "2": "For you, feeling cared for has a material texture: a full fridge, a paid bill, a savings account that grows a little each month. You show love in things people can hold, paying for dinner, sending a parcel, slipping a friend money when they are short. A stretch of scarcity earlier in life, or a sudden loss of security, shaped what you value and how carefully you guard it. You have green fingers in the widest sense, patient enough to grow savings, plants and skills season by season. The ache underneath is a belief that you have to earn your place by providing. Receiving a gift when you have nothing to give back feels uncomfortable, and accepting it anyway is part of how you heal.",
      "3": "A long phone call with the right person can feed you better than a meal, and you know the difference between chatter and being properly heard. You look after people with words: the explanation that makes sense to a struggling friend, the message checking they got home safely. Siblings, neighbours or early school years were where you first learned whether talking brought comfort or fell on deaf ears. Somewhere in you sits an old hunger to be listened to without interruption. When that hunger goes unfed, you over-explain or keep talking to fill the quiet. Your inner voice matters as much as the one you use aloud, and the kindness you offer others belongs in your own head too.",
      "4": "Home is where you do your deepest caring, and you notice at once when a house has no warmth in it. You are the one who keeps the family recipes, hosts the Sunday lunch and knows whose birthday is coming. The bond with a parent, often your mother, shaped you profoundly, whether through closeness, a painful loss or a childhood in which you ended up parenting them. Moving house, a family rift or a sold childhood home shakes you more than others understand. Your roots and ancestry carry emotional weight, and you feel them in your body. Your deepest work is building a security inside yourself that survives the bricks and mortar changing.",
      "5": "Children light up around you, and you feel oddly at home on the floor building a den or judging a painting contest. Your creative work has the quality of something raised rather than made: you nurse a project through its awkward early stages and feel protective of it once it is out in the world. Play is a form of self-care for you, and a week without any fun leaves you depleted. Loss has touched this area, through a child, a romance or a creative dream that did not survive, and it taught you to love without owning. The hard part is letting what you have nurtured go its own way. You are also allowed to play purely for yourself, with nobody to supervise.",
      "6": "Your wellbeing is built or broken in the ordinary hours: what you eat at your desk, whether you walk at lunchtime, when you finally go to bed. You care for people practically, taking the shift nobody wants, bringing soup to a colleague with a cold, noticing the office plant is dying. Nursing, nutrition, healing work or looking after animals come naturally to you. You feel most loved when someone lightens your daily load without being asked. The pitfall is running yourself down in the name of being useful and only resting once your body forces you to. Self-care built into the week, rather than kept for emergencies, changes everything about how well you feel.",
      "7": "In your closest relationships, the question of who looks after whom is never far away. You fall for people who need tending, or for people who tend you, and the balance tips back and forth over the years. A partner quickly feels like family to you, with all the loyalty and old patterns that implies. A breakup or loss in partnership goes very deep, and you come out of it changed. You are learning the line between caring for someone and managing their life, a line you cross more often than you realise when you are anxious. The bonds that suit you are ones in which both people feed each other and either could leave, yet chooses to stay.",
      "8": "Loss arrived early in your story of care, through a separation, a death or a parent who was there and then suddenly not. Since then you have known that love and grief sit close together. Intimacy and shared money stir fears of being swallowed whole or left behind, and you watch for both. Friends call you when someone is dying, when a marriage ends, when the ground gives way, because you do not flinch from the dark. You know how to sit beside a person at the worst moment of their life. What heals you is trusting the cycle you have seen so many times: what goes under returns, altered, and often stronger than before.",
      "9": "A teacher, a book or a journey abroad fed you at a moment when home could not, and you have never forgotten it. You nourish people by widening their world, recommending the novel, the course, the city they have to see. Unfamiliar kitchens and foreign streets feel strangely like home, and you come back from travelling replenished in a way a holiday alone cannot explain. At some point you lost a faith, a country or a belief system that had held you, and that grief reshaped what you believe now. You feel protective of the ideas that sustain you. Keeping them open to challenge is what stops them hardening into dogma.",
      "10": "Care is part of your public face, and colleagues or clients see you as the steady, protective one. You are drawn to work that feeds, teaches, heals or shelters, or you bring that quality to whatever job you do, remembering names and noticing who is struggling. A parent's example of care, or its painful absence, drives your ambitions more than you admit. You need your contribution noticed, and being overlooked at work leaves you feeling starved rather than merely annoyed. The imbalance to watch is looking after an entire team while your own fridge is empty and your friendships wait. Your private hunger deserves the same attention you give your professional role.",
      "11": "Your friends are your chosen family, and you are usually the one who organises the birthday collection and checks in when someone goes quiet in the group chat. You gravitate to causes that feed people, shelter the vulnerable or make a community kinder. In teams, you drift into the caring role without being asked. Losses come through friendships that fade or groups that fall apart, and those endings hurt more than you let on. You find it much easier to hold the circle together than to be held by it. Letting a friend turn up for you, bring the meal, make the call, is where nourishment reaches you.",
      "12": "Much of your caring happens out of sight: sitting with a relative in hospital, volunteering where nobody thanks you, making sacrifices you never mention. Your own need to be looked after is so well hidden that you sometimes miss it yourself, noticing only when you are exhausted and tearful for no clear reason. Early care came with absence, illness or grief that nobody named at the time. Sleep, dreams, solitude and quiet spiritual practice refill you better than company does. Accepting help makes you feel guilty, as though you have taken something you were not owed. Bringing your needs into the light, and letting someone meet them, is the tender work of this placement."
    }],
    ["asteroids.pallas.houses", {
      "1": "People clock you as clever within minutes, and you often find yourself solving a stranger's problem before they have finished describing it. Your intelligence sits on the surface, in quick eyes and a ready answer, and it doubles as armour. Being admired for your mind is pleasant, yet you also long to be approached gently, as someone with feelings rather than a resource. When you are unsure, you hide it behind competence, which leaves you lonely in rooms full of people who assume you have it handled. Saying \"I don't know yet\" out loud feels exposing, and people respect you just as much afterwards. The feeling person behind the fast perception is the one worth letting others meet.",
      "2": "You can look at a hobby, a skill or a half-empty shop and see how it could pay. Money is a puzzle you enjoy, and you design income streams, budgets and small businesses with flair. Crafts that turn know-how into something tangible, from carpentry to coding, suit your hands and your head. You spot value where others see junk, and a simple idea in your care becomes a steady living. The snag is that your self-worth is wired to competence, so a spell of not earning or not achieving feels like a personal failure. You are worth more than your usefulness, and your finances improve once you stop trying to prove it.",
      "3": "Your mind spots patterns in conversation, in messages, in the way an argument is built, and you often see the conclusion three sentences early. Explaining, writing, debating and teaching come naturally, and you can make a complicated idea click for someone in a single line. Siblings or early schooling were where your intelligence was first noticed, praised or tested, and you still carry some of that competitive edge. Everyday problems, from travel plans to broken appliances, rarely defeat you. The flip side is impatience: people feel slow or unheard when you finish their sentences for them. When you hold back your answer and ask one more question, you often catch the detail your pattern missed.",
      "4": "You were the child who noticed what the adults were not saying, and you still see the patterns your family has agreed not to name. A parent, often your father, shaped how you think, prizing reason, achievement or the ability to hold your own at the dinner table. At home you are the organiser and protector, the one who handles the paperwork, plans the move and sorts the family crisis. Your sharpest insights come from understanding where you came from. The cost is a household that runs brilliantly and feels a little cool. Making room for tenderness alongside wisdom turns your home from a well-run operation into a refuge.",
      "5": "Your creative work has a clever architecture to it, whether that is a well-plotted story, an elegant garden layout or a perfectly judged dinner party. Chess, strategy games, cryptic crosswords and design projects are where your mind relaxes and plays. In romance you are drawn to people who admire your intelligence, and flirting often takes the form of sparring. With children you make an inspiring teacher, turning homework into a game. The catch is that you think your way through pleasure, analysing the film instead of enjoying it, optimising the holiday until it becomes a project. Your deepest creativity arrives when you make something for no reason at all.",
      "6": "You walk into a muddled workplace and instantly see how the system should run. Colleagues bring you the problems nobody else can crack: the broken spreadsheet, the diagnosis that does not add up, the process everyone hates. Healing arts, analysis and technical roles suit your talent for finding the fault and fixing it. You approach your own health like a detective, tracking sleep, testing diets, reading the research. Nitpicking and overwork are the cost, where nothing is ever quite efficient enough and rest feels like wasted time. Routines that include pleasure and idleness as well as productivity keep your remarkable mind from grinding itself down.",
      "7": "In relationships you are often the planner and the strategist, the one who reads the situation and knows what to say. You attract sharp partners, and the chemistry frequently begins with a good argument. Mediation, law, consulting and advisory work suit you, because you see both sides of a dispute with unusual clarity. A recurring pattern of intellectual rivalry runs through your love life, or of being valued for your brain more than your heart. You sometimes choose partners you can outthink, which feels safe and turns out to be lonely. Letting someone see you confused, hurt or wrong is how your relationships become places of closeness rather than clever negotiation.",
      "8": "You see what lies beneath a situation: the motive behind the kind offer, the power play in the meeting, the money trail nobody else followed. In a crisis you are often the calmest person in the room, working out the next three moves. Psychology, research, finance, therapy and investigation draw you because you want to know how things work. Understanding everything is also your defence, a way of never being caught off guard. That strategy protects you and keeps intimacy at arm's length, since a lover who is fully understood can never quite surprise you. Healing comes when you let yourself be moved instead of only understanding, and feel something before you have analysed it.",
      "9": "You grasp whole worldviews at once, seeing how a philosophy, a legal system or a religion hangs together. Teaching, publishing, law and advocacy suit your mind, and you argue for justice on a scale far beyond your own street. A long flight, a lecture or a foreign city stirs your intelligence like nothing else. You care about principles and will fight for people you have never met. Intellectual pride is your blind spot, and once you have mapped a subject you stop listening to those who see it differently. Staying a student even while you teach keeps your wisdom fresh, and your sense of justice generous rather than righteous.",
      "10": "At work you are known for clear thinking, and people come to you for strategy, expert advice or a plan that holds together. You rise through competence rather than charm, and your reputation rests on getting difficult things right. A father figure or early mentor shaped your ambitions, and a mentor who treated you as capable, rather than merely useful, changed the direction of your working life. You look impressive in a meeting and sometimes feel lonely on the train home. Professional armour fits you so well that you forget to take it off. Your working life flourishes when the strategist is also allowed to be a person with doubts and needs.",
      "11": "Put you in a committee, a campaign or a group chat full of good intentions and no plan, and within a week there is a spreadsheet. You see how a community could work better and you help to organise it. Activism, technology, science and collaborative projects draw you, and friends value your insight when they are stuck. You are the person who turns a group's big ideals into a workable timetable. The difficulty is that you can end up loving the cause more than the people in it, attending every meeting and missing the birthday drinks. Your friendships deepen when you show up for the individual as faithfully as for the mission.",
      "12": "Your intelligence works quietly, often below the surface, arriving as a hunch in the shower or a solution in a dream. You rarely get credit for your insights, partly because you share them sideways and partly because others take them as their own. Healing work, spiritual study, research and strategy behind the scenes all suit you. If your mind was not valued early on, you learned to doubt it, and you still second-guess conclusions that turn out to be right. Journalling, meditation or walking alone reveal answers your busy mind could not reach. Trusting the wisdom that arrives in silence is the turning point for you."
    }],
    ["asteroids.juno.houses", {
      "1": "Partnership is part of how you see yourself, and people often pick you out as the committed type long before you have said a word about it. Whether or not you married young, you take every relationship as seriously as a vow. Loyalty shows in your face and your manner. You notice unfairness in other people's couples at once and are quick to say so. The danger is dissolving into the role of partner until your own name feels secondary. Your best relationships are with people who love your independence as much as your loyalty, and commitment then expands who you are rather than replacing it.",
      "2": "You judge a partner's love partly by how they treat your money, your belongings and your time. Shared resources bond you, and they are also where your fiercest rows take place. A partner whose values match yours feels essential, and a careless spender or someone who borrows without asking erodes your trust quickly. You talk about money early in a relationship, and that honesty saves you a great deal of hurt later. The trap is relying on a partner for security you could build yourself. Keeping your own financial and emotional footing makes the security between you something shared, not something one of you depends on.",
      "3": "For you, a relationship lives or dies in conversation. A partner who texts back, remembers what you said on Tuesday and wants to hear about your day earns your loyalty. Silence, stonewalling or a phone left unanswered feels like a breach of trust. You meet partners through study, writing, local life or friends of friends, and siblings shaped your early sense of what commitment looks like. Late-night talks that run until the birds start singing are some of the happiest memories of your love life. The risk is that endless talking replaces feeling, and you analyse a relationship rather than living it. Commitment flourishes for you when words carry warmth as well as honesty.",
      "4": "You want commitment that looks like a home: a shared kitchen, a front door you both have keys to, a family table. Your parents' marriage, and the rules you absorbed about who does what, shape how you commit more than you realise. You are drawn to partners who remind you of a parent, for better or worse, until you start choosing consciously. A partner quickly becomes family to you, and family obligations press on the relationship in turn. Friction comes when inherited expectations fill the house and nobody has asked what either of you needs. Building a home that reflects both of you, rather than the one you grew up in, is where your partnerships mature.",
      "5": "You want a partnership that stays romantic years in, with date nights, surprises and a partner who still flirts with you across the room. Creativity and play are part of the bond, and children, or a shared creative project, often become central to it. You seek someone who admires what you make and how you shine. Jealousy flares sharply around attention, and a partner's admiration for someone else stings more than you show. When romance fades into routine, you are tempted to decide the love has gone. Commitment deepens for you through keeping playfulness alive on ordinary Wednesdays, not only on anniversaries.",
      "6": "Love for you is proved in the daily details: who makes the tea, who remembers the bins, who notices you are tired. You meet partners through work, or end up sharing a working partnership, and practical help matters enormously to you. A fair division of chores is part of equality in your eyes, and you keep a quiet tally when it slides. Small courtesies, or their absence, reveal more to you than grand gestures ever could. The shadow is a relationship that turns into a list of tasks with no tenderness left in it. The bond thrives when pleasure gets as much space in the diary as shared responsibilities.",
      "7": "Committed partnership is one of the central stories of your life, and you long for someone who is a true equal. You take relationships seriously, including business partnerships, and treat promises as binding. Fairness and loyalty matter enormously, and you notice immediately when the balance tips. Partners teach you a great deal, sometimes through love and sometimes through conflict that forces you to grow. Clear agreements and spoken expectations protect both people, whether in marriage or a joint venture. The pitfall is looking for completion in someone else, and your relationships are healthiest when you arrive as a whole person, not half of a pair waiting to be finished.",
      "8": "You want a bond that goes all the way down, with intense emotional and sexual connection and nothing held back. Joint finances, shared property or inheritance often play a major part in your partnerships. You are capable of profound loyalty, the kind that stays through illness, debt and scandal. Jealousy and control are the dark side of that depth, and checking a phone or reading between the lines can feel like protecting yourself. Loss, bankruptcy or a major upheaval tests your commitments and, in the end, strengthens them. Trust built on honesty rather than surveillance is what makes the depth you crave feel safe.",
      "9": "You need a partner who shares your beliefs or your hunger for adventure, someone to plan the next trip with and argue about big questions over dinner. You meet partners abroad or through study, or fall for someone from another culture entirely. Growth together is essential, and a relationship that stops expanding starts to feel like a cage. Weddings abroad, legal matters or a shared spiritual practice mark important chapters in your love life. The mistake is expecting a partner to supply your sense of meaning. Honest disagreement about beliefs strengthens the bond, and it thrives when you both keep exploring, together and separately.",
      "10": "Your partnerships are visible, and people know you as a couple at work, in the community or even in public life. You work alongside a partner, or choose someone who supports your ambitions and brings a certain standing. Underneath runs a strong feeling that your partner reflects on you, which adds pressure to choose well. You need to be proud of the person beside you. The difficulty is a relationship that looks excellent from outside and feels thin at the kitchen table, or two careers competing for the same oxygen. Choosing for private happiness first and status second gives you a partnership that stands up to public view.",
      "11": "You want a partner who is also your best friend, someone you would choose to spend time with even without the romance. Many of your partners arrive through groups, shared causes or a wider circle of friends. Independence matters, and unconventional arrangements such as separate homes or flexible timetables suit you well. A partner who feels threatened by your friendships or your causes will not last long. The risk is a comfortable companionship that never quite risks emotional commitment. Growth comes when friendship deepens into something that can hold vulnerability as well as shared ideals.",
      "12": "Partnership has a hidden or spiritual edge in your life. You keep relationships private, idealise partners, or feel a fated pull towards one person that you cannot fully explain. Themes of secrecy, loss or caring for an unwell partner recur. You give devotion generously, and at times give yourself away with it, fading until your own needs vanish from the relationship. You also see partners through a haze of longing, falling for who they could become. Therapy, spiritual practice or honest journalling help you see the person in front of you clearly. Bringing your relationship needs into the open keeps devotion from turning into self-erasure."
    }],
    ["asteroids.vesta.houses", {
      "1": "People sense a flame in you before they know what you are devoted to, and your presence reads as serious, self-contained and intense. You come across as more private than you are, because so much of your energy is turned inward. Time alone is how you stay centred, and a day without it leaves you scattered. When you are aligned with your purpose, you become magnetic, and people trust your steadiness without quite knowing why. The difficulty is that your self-containment keeps others at a distance they cannot cross, and they read focus as coolness. Letting a few people inside the circle warms your flame rather than dimming it.",
      "2": "You treat money and possessions with careful stewardship, and you know what everything you own is for. Your values feel sacred to you, and you will not trade them for a better salary. You are skilled at working with little, turning modest resources into something lasting through patience, like the savings pot that grows unnoticed for a decade. Simplicity brings you more peace than accumulation ever could. The trap is devoting so much energy to security that rest, friendship and play get pushed to the margins. Your sense of safety deepens when your wealth serves your life rather than the other way round.",
      "3": "You can read, study or write with extraordinary concentration, losing a whole afternoon to a subject that grips you. A particular field, language or craft of words becomes a devotion, and a daily writing or reading habit steadies you more than anything else. Siblings and your local neighbourhood carry significance. Short walks and quiet journeys clear your mind and send you back to your desk refreshed. The danger is living so far inside your head that you forget to speak, and your knowledge stays locked in notebooks. Sharing what you learn, in a conversation, a class or a letter, turns private focus into something that feeds other people too.",
      "4": "Home is your temple, and you need a sanctuary where you can close the door and be undisturbed. A particular room, a corner with a candle or a morning ritual at the kitchen table keeps you connected to what matters. You carry a family flame, a craft, a recipe or a tradition handed down, and you guard it faithfully. Working from home suits you better than most. Your home can harden into a fortress, where retreat crowds out warmth and visitors feel they are intruding. Your sanctuary is at its best when it has room at the table for people as well as for silence.",
      "5": "You pour yourself into one creative passion for years, and that single-minded commitment is where your mastery comes from. Painting, music, writing or a sport can feel like a calling rather than a hobby. Romance tends to be either serious or kept deliberately separate from your creative life. With children, you are a devoted parent or mentor who takes their gifts seriously and turns up to every recital. The risk is turning play into duty, practising so hard that the joy drains out of it. Your flame burns brightest when you remember why you started, and let yourself create for delight as well as excellence.",
      "6": "You find something sacred in simple tasks done with full attention: chopping vegetables, filing records, tending seedlings on the windowsill. Daily ritual and craft give your life meaning, and you work with remarkable focus once you settle in. Choosing work that matters to you makes all the difference to your energy. You are the colleague who does things properly, however long it takes. The shadow is burnout and a life that has become all duty, with your body calling a halt. Treating rest as sacred as work, and guarding it just as fiercely, is what keeps your devotion sustainable.",
      "7": "You give yourself wholeheartedly to a partner, or share a calling with them, and yet you need space inside the relationship. Separate rooms, separate interests or regular time apart strengthen your closeness rather than threaten it. You are drawn to partners who have their own strong sense of purpose and respect yours without competing. Tension arises between commitment and solitude, and partners sometimes read your withdrawal as rejection. You can go quiet for days while you tend your own fire. Your relationships flourish when a partner honours both your flame and your wish to be close, and you explain the difference plainly.",
      "8": "Intimacy feels sacred to you, and you share your inner life with only a few people who have earned deep trust. Sexuality carries a spiritual weight, and you would rather go without than settle for a shallow connection. Healing, research or work with shared resources and other people's money draws your concentrated attention. Periods of celibacy or intense privacy can be chosen rather than imposed, and they renew you. Withdrawing from intimacy altogether is the danger, guarding the flame so closely that no one gets near it. When you do open up, the connection is profound and lasting, and it transforms you both.",
      "9": "You follow a spiritual path, a philosophy or a field of study with the devotion others reserve for a religion. Long periods of study, pilgrimage or time abroad feel like a vocation in themselves. You make a devoted teacher, passing on what you know with great seriousness. Your beliefs are firmly held, and you can quote the texts that shaped you from memory. Rigid conviction is the hazard, where certainty replaces the wonder that first set you going. Sharing your questions as well as your answers keeps your devotion curious and your inner flame bright.",
      "10": "Your career is a calling, and you are known for dedication, expertise and uncompromising standards. You are the specialist people seek out, the one still refining the work after everyone else has gone home. Your public role carries something sacred for you, and you take its responsibilities personally. That devotion wins respect and builds a reputation over the years. Workaholism is the price, with missed dinners, cancelled holidays and loved ones who feel second to the job. Letting colleagues and family share in your purpose makes the path less lonely, and remembering you are more than your vocation keeps the flame from consuming you.",
      "11": "You dedicate yourself to a cause or a community, and you work best alongside people who share your ideals. You are the committed member who keeps a group going through lean times, long after others have drifted away. Even among friends you need solitude, stepping out of the gathering to recharge before returning. Communities whose values match your own get your very best, without resentment. The challenge is serving the collective so faithfully that close personal bonds are neglected, and the friend who needs you one to one gets less of you than the committee does. Tending both keeps your flame steady.",
      "12": "Your devotion is mostly private, a lamp burning in a back room that few people ever see. You need a great deal of solitude and are drawn to retreat, meditation, healing or work in hospitals and quiet institutions. Research, writing and anything requiring long concentration away from the public eye suit you well. Regular periods of withdrawal restore you, and too much company leaves you drained and oddly lost. Keeping your gifts so hidden that no one benefits from them is the real cost. Bringing some of that inner flame out into the world, even in small ways, lets the light you tend reach other people."
    }],
    ["asteroids.ceres.signs", {
      "aries": "When you were small, you probably learned that the fastest way to feel better was to get up and sort it yourself. That habit stayed. You care for people by backing them and lending them your nerve, sitting beside a friend while she sends the email she has been dreading. Fuss makes you itch: a partner hovering with soup and sympathy can leave you oddly irritable, whereas someone who says 'go on, you can do this' makes you feel held. Your self-reliance is a strength, and it also hides an old hurt about having to be your own parent too early. Letting someone look after you when you are ill, without apologising or getting up too soon, heals something the pushing never reaches.",
      "taurus": "For you, love arrives through the body: a proper meal, clean sheets, a hand on your back, the same café on a Saturday morning. You are the friend whose kitchen people drift into, and guests stay later than they planned because your home feels good. Routine is how you know you are safe, which is why a sudden move, a job change or a partner rearranging the furniture can shake you more than it seems it should. Loss has a way of finding you through money, belongings or your own physical health, and each time it teaches that security lives deeper than possessions. Trouble starts when comfort turns into a fortress and you hold on to things long past their season. Your body knows what it needs when you slow down enough to listen.",
      "gemini": "Nothing feeds you quite like a long conversation with someone who is interested. You feel cared for when a person remembers what you told them last week and asks how it went, and you show care the same way: the article forwarded at midnight, the voice note that runs to six minutes, the patient explanation of how the boiler works. Being left on read or met with silence can feel like hunger. Much of what you know about care was learned among siblings, classmates or neighbours, in the chatter of early life. Talking helps you process almost everything, yet sometimes the talking outruns the feeling underneath it. Some griefs want to sit in your chest for a while before they get a name, and letting them sit nourishes you more than any explanation.",
      "cancer": "You notice the tired face across the room before anyone else does, and you are already putting the kettle on. Care is your native language, and home, family and belonging sit at the centre of how safe you feel in the world. Your bond with your mother or main caregiver has shaped you deeply, sometimes as a source of strength and sometimes as a wound you keep tending. Because you attach so completely, loss lands hard, and you often keep a door open long after someone has walked through it. People feel held around you in a way they rarely feel elsewhere. The harder part is letting the ones you love grow up and away, and giving yourself the same tenderness you pour so freely into everyone else.",
      "leo": "You light up when someone is delighted by you, and you give that delight back generously. Children, shy colleagues and friends on the edge of a bold decision flourish around you, because you make them feel like the main character. Your care comes with applause, birthday banners and the kind of praise people remember years later. If love at home felt tied to being clever, funny or impressive, you probably still work hard to earn it, performing even when you are exhausted. A loss can bruise your pride as much as your heart, and you hide the hurt behind a bright face. Creative play restores you, and so does the slow discovery that you are loved on a grey Tuesday when you have done nothing special at all.",
      "virgo": "Care, for you, is a verb: you fix the leaking tap, batch cook for a friend with a newborn, notice the mole someone should get checked. Sympathy alone can feel thin, and you feel looked after when someone turns up with a practical answer. Your stomach and your routines are closely tied to your mood, so a stressful week shows up at the dinner table first. There is steady devotion in the small tasks you do without being asked. The difficulty is that your careful eye turns critical, towards a partner's habits and even more towards your own body. Being imperfect never made you unworthy of looking after, and help lands differently once you stop feeling you must earn it.",
      "libra": "You feel nourished when a relationship is even, when the effort goes both ways and you are met as an equal. Pretty rooms, good manners and a peaceful dinner table feed you in a way that is hard to explain to people who do not need them. Your instinct is to smooth things over: you are the one who changes the subject when an argument brews at a family gathering. Some of your deepest losses have come through breakups or a sense of being treated unfairly, and they shape how carefully you love afterwards. Keeping the peace can mean giving more than you receive, then quietly resenting it for months. Real care sometimes sounds like disagreement, and the bond that feeds you has space for your honest needs as well as your grace.",
      "scorpio": "The old story of a mother searching the underworld for her lost daughter runs close to your own experience of love. You care fiercely and loyally, and the people you trust are the ones who stayed while you were at your lowest, without flinching or changing the subject. Early life probably taught you about secrets, losses or power struggles around who got looked after. Fear of losing someone can tighten your care into control, checking and watching and holding on too hard. At the same time, you are the person friends call from the hospital corridor at 3am, because you know how to sit with grief. What is wholly yours tends to return in some changed form, and loosening your grip turns out to be a form of love too.",
      "sagittarius": "You feel most cared for by someone who says yes to the trip, hands you the book that changed their life and stays up late talking about what any of it means. Space to roam is not a luxury for you but the way you breathe. Your own way of nurturing is to widen people's worlds, dragging a friend to a new city or convincing a nervous colleague that they are ready for the bigger role. Being fenced in or lectured feels like the opposite of love. Care often reached you through a teacher, a faith or a journey more than through home itself. Restlessness sometimes covers a need you would rather not feel, and staying put for someone you love can be its own adventure.",
      "capricorn": "You are the one who books the removal van, remembers the insurance renewal and covers the bill. Providing is how you love, and being dependable is a point of pride. Many people with this placement grew up quickly, taking on duties that left little room for being a child, so being looked after now feels faintly unfamiliar, even awkward. Nothing touches you more than someone who notices your effort, or who takes charge for once so you can sit down. The trap is equating love with work, until softness feels like wasted time. Rest needs no justification, and the people close to you love you for who you are, not only for what you hold together.",
      "aquarius": "Being allowed to be as odd as you are is what nourishment feels like to you. Chosen family, old friends and a group that shares your cause often feed you more reliably than blood ties. You care by accepting people whole, defending a friend's right to live differently and never demanding they fit a template. Care in your early years often felt distant, unusual or conditional on keeping your feelings tidy, so you go cool and analytical when emotions run high. A friend cries and you offer a clear-eyed perspective when what they wanted was a hug. Closeness does not have to cost you your freedom, and warmth offered alongside understanding is what makes your care land.",
      "pisces": "You sense sorrow in a room before anyone speaks, and your first instinct is to soothe it, even at your own expense. Quiet company, music, a long bath, a walk by the sea or an afternoon alone to dissolve are what restore you. Early care was probably inconsistent, idealised or tangled up with someone else's sadness, and you learned to feel for others before you learned to feel for yourself. Your acceptance is close to unconditional, which is a rare gift in a guarded world. The shadow is martyrdom, or care that props up a painful pattern instead of healing it. Gentle boundaries keep your own well from running dry, so the love you give can go on flowing for years."
    }],
    ["asteroids.pallas.signs", {
      "aries": "Your mind works best with the clock running. Put you in a crisis meeting or beside a flat tyre on a dark road and you see the quickest way through while others are still describing the problem. You are a natural champion, the one who speaks up for the colleague being talked over or writes the complaint letter that gets a refund. That speed is thrilling, and it wins a lot of fights. Not everything needs to be a fight, though, and a partner's gentle disagreement is not an attack on your intelligence. Your first instinct is often brilliant, and letting it cool for an hour before checking it with a calmer second look turns brilliance into wisdom.",
      "taurus": "Your intelligence lives in your hands and senses. You see patterns in money, materials, soil, bodies and recipes, and your best ideas end up as something solid: a garden that works, a business with steady margins, a chair still standing in fifty years. Clever shortcuts leave you cold, because you trust methods that have proven themselves over time. Healing through touch, food or bodywork often comes naturally. Once you have settled on a plan, though, you can hold it long after the facts have shifted, digging in because changing course feels like losing ground. Your steady instincts are usually right about the destination, and the blueprint improves every time you let fresh evidence redraw part of it.",
      "gemini": "You are the person who connects the dots at the party: this friend should meet that one, this article explains that problem. Ideas, people and information arrange themselves into links for you, and you can explain something complicated in one clear sentence. Writing, teaching, debate, languages and networking all put your strategic gift to work. You often solve problems out loud, gathering five opinions before lunch and weaving them into a plan by teatime. Brilliance scattered across twenty open tabs rarely becomes anything, however, and cleverness can be a handy way to skip a feeling. Following one question deeply enough, for long enough, turns your quick wit into understanding.",
      "cancer": "You read the emotional weather of a family, a team or a friendship with uncanny accuracy, often knowing what the group needs before anyone has said a word. Your strategies are protective: you plan the seating so the feuding cousins never share a table, and you sense which colleague is about to quit. Somewhere in your history there was probably a split between being clever and being caring, as if the household valued one and overlooked the other. Nurturing and healing work can suit your mind beautifully. You are at your sharpest when you stop treating your feelings as fog. Emotion, for you, is data, and trusting it is where your real intelligence begins.",
      "leo": "Presentation is part of your genius. You know how to frame an idea so the room leans in, whether that is a pitch, a wedding speech or the way you arrange a shop window. Your strategic mind works best in service of a vision you believe in with your whole heart. There is often an early story of trying to impress a father or authority figure by being bright and dazzling, and a trace of that hunger for approval remains. When your insight goes uncredited, it stings more than you let on. The richest use of your creative intelligence is lifting other people into the light alongside you, which turns out to make you shine even more.",
      "virgo": "You spot the typo on page forty, the spreadsheet cell pulling the wrong figure, the tiny change to a routine that would save everyone twenty minutes. Your intelligence is precise and quietly relentless, always hunting for the improvement. Health, craft, editing and technical work are natural homes for it, and you often heal through sheer careful attention. The same sharp eye turns inwards, though, and you can lie awake replaying the one mistake in an otherwise excellent day. Perfectionism delays good work indefinitely. A solid answer delivered on Tuesday usually helps far more than a flawless one that never leaves your desk.",
      "libra": "You see the balance point in almost any situation, the solution that lets three people with different demands all walk away satisfied. Friends bring you their disputes because you can hold both sides fairly, and your eye for proportion makes rooms, outfits and arguments look right. Law, mediation, design and partnership work suit this kind of mind. The risk is weighing every option so carefully that the decision never arrives, or keeping the peace when justice needs a stand. You often know what is fair long before you say it aloud. Your wisdom matures the day you say it anyway, even if it disturbs the lovely calm you worked so hard to build.",
      "scorpio": "You clock hidden motives within minutes of meeting someone: who holds the real power, who is lying, what the smile is covering. Research, investigation, psychology and crisis work all suit a mind that is unafraid of what sits beneath the surface. You learned early to protect yourself with intelligence, keeping your cards close and revealing only what serves you. That skill keeps you safe, and it also tempts you to use what you see to win or control. People sense your penetrating gaze and either trust you completely or keep their distance. Your insight becomes a gift when you use it to help someone understand their own depths rather than to guard yourself against them.",
      "sagittarius": "You see where things are heading long before anyone else in the room. Philosophies, belief systems and cultural shifts make sense to you quickly, and you can sum up a whole movement in a single sweeping line over dinner. Teaching, publishing, law, travel and activism call to that big picture mind, and you speak up for truth and freedom without much prompting. Broad strokes skip the details, however, and conviction can slide into preaching when someone disagrees. You are wisest when your vision stays anchored in facts. Genuine curiosity about views that differ from yours keeps your mind as wide as the horizons you love.",
      "capricorn": "You understand how institutions work: who signs off, which rules bend, how to build something still standing in twenty years. Planning, management and structural design come to you so naturally that others hand you the hard project without a second thought. When the stakes are high, you are the quiet strategist in the corner who already has the fallback plan. A strong inherited sense of duty and achievement drives much of this. The shadow is becoming so focused on competence that warmth starts to look like inefficiency. Your authority is most powerful when it includes empathy, and the structures you build last longest when they leave room for ordinary human needs.",
      "aquarius": "Your ideas often arrive before the world is ready for them, and you get used to watching people catch up a few years later. You see patterns across whole systems, networks and societies, which draws you towards technology, science, social reform and group strategy. Justice on a collective scale matters intensely to you. Insight comes in sudden flashes, reorganising everything you thought you knew in the space of a shower. The risk is detachment, treating people as data points in a model rather than as individuals with bruised feelings. Your brilliance is at its best when it serves the actual humans in your life as well as the abstract ideal.",
      "pisces": "You know things without being able to say how you know them. Patterns reach you through images, dreams, music and a feeling in your body, and your best insights often arrive whole, as if dropped from somewhere else. Healing, the arts and spiritual work make natural use of this kind of intelligence. Explaining your reasoning to a sceptical boss or partner can be maddening, because the reasoning happened below words. At times you doubt your own perceptions, or let them drift into pleasant fantasy. Checking an intuition against what happens, then trusting the ones that keep proving true, gives your gift a spine."
    }],
    ["asteroids.juno.signs", {
      "aries": "You need a partner who can keep up with you and push back when it matters. A relationship that feels dull or passive loses you, however kind the person is. You are drawn to bold, active people, and a good row followed by an honest making up can leave you feeling closer, not further apart. Being a peer matters: you want to lead sometimes, follow sometimes and never feel managed. Competition creeps into the bond easily, both of you trying to win the argument about whose turn it was to book the table. Commitment deepens when you trust that being a team adds to your independence, and when a ten minute walk before replying saves the evening.",
      "taurus": "Commitment, for you, is something built slowly and meant to last. You need a partner who turns up when they said they would, who reaches for your hand on the sofa and who wants to put down roots. Money, a comfortable home and shared routines like Sunday lunch feel like part of the vow, even if nobody wrote them down. Once you have chosen someone, you stay, often through storms that would send others packing. The difficulty is possessiveness, a quiet sense that a partner belongs to you. Your relationships flourish when security includes room for change, and when loyalty is something you choose again each year rather than a habit you cling to.",
      "gemini": "Your partner has to be your favourite person to talk to. Shared jokes, a steady stream of messages through the working day and curiosity about the same odd things keep your commitment alive long after the first spark. You need variety and a little freedom inside the relationship, and an unconventional arrangement can suit you better than the standard one. Boredom is the real threat, more than any rival. Keeping your options half open is a way to avoid depth, and part of you knows when you are doing it. Partnership deepens when a late night conversation drifts somewhere vulnerable and you let it, trusting that one person can hold your interest if you both keep learning.",
      "cancer": "You want your partnership to feel like coming home. Emotional safety, tenderness and a shared sense of family matter more to you than grand gestures, and once you feel secure, your loyalty runs very deep. A partner who is protective and domestic, or who gladly receives your care, suits you well. You are the one who remembers their mother's birthday and keeps the photos in order. That deep attachment makes leaving hard, even when a bond has stopped serving you, and jealousy often grows out of an old fear of being abandoned. The more safety you build inside yourself, the more your commitment becomes a free choice rather than something fear holds in place.",
      "leo": "You want to be proud of your partnership, and you want your partner to be proud of you in public. Romance, warmth and a sense of occasion keep you devoted: anniversary dinners, a surprise weekend away, being introduced at a party with obvious delight. Loyalty matters enormously, and any hint of being overlooked or replaced wounds you to the core, often more than you show. In return you are generous, affectionate and fiercely protective. Pride can get in the way, and so can needing attention so constantly that your partner starts to feel like an audience. Your relationships glow when both of you get to shine, and when you applaud them as wholeheartedly as you hope to be applauded.",
      "virgo": "You show commitment in small daily acts: the coffee made how they like it, the appointment you remembered, the shelf put up. You need a partner who is dependable, considerate and willing to work on the relationship rather than coast. Shared routines and improving your life together are what bind you, and you are often drawn to capable, modest people who do not need a fuss. Your helpful eye can become a critical one, noting every towel left on the floor. Over time, a bond can start to feel more like duty than joy. Appreciation spoken aloud, as often as the suggestions, keeps the love as alive as the routine.",
      "libra": "Partnership sits near the centre of your life, and you do not feel entirely yourself without it. You need fairness, courtesy and a partner who treats you as an equal, from who does the washing up to whose career gets priority. A beautiful home and a shared social life matter to you more than you sometimes admit. Because you are so sensitive to imbalance, you feel betrayed when the scales tip, even slightly. Swallowing a complaint to keep dinner pleasant lets resentment build for months. Speaking up early about what feels unfair turns out to protect the harmony you love, because honesty is part of lasting balance.",
      "scorpio": "You want a bond so close it almost feels like merging. A partner has to be loyal, emotionally honest and unafraid of intensity, someone who can hear your darkest thoughts at 2am without flinching. Trust is everything to you, and betrayal can feel close to unforgivable. Jealousy, control and questions of shared power are likely to surface, sometimes painfully, over money, secrets or who knows what about whom. Yet partnership changes you profoundly, and you come out of the hardest chapters stronger and more yourself. Trust grows best without surveillance, and the bond breathes more easily when each of you keeps a little private space.",
      "sagittarius": "You need a partner who is also a travelling companion, literally and philosophically. Someone honest, adventurous and interested in the big questions keeps you engaged, particularly if they will book a spontaneous flight or argue about ethics until midnight. Shared beliefs, learning and exploration bind you together more than routine ever will. Feeling fenced in kills your love faster than anything else. Dodging the ordinary work of commitment, the bins and the bills, is a strong temptation, and so is expecting a partner to be your guru. Your relationships flourish when commitment itself becomes the adventure, and when the two of you keep growing in the same direction rather than apart.",
      "capricorn": "You take commitment seriously, and you do not give it lightly. You want a partner who is responsible, ambitious and ready to build a solid life together, and you are often drawn to someone older or more established. Long term plans, a mortgage and a shared five year view make you feel secure. Once committed, you are dependable to the bone, the partner who holds the family together in a crisis. The risk is a relationship that becomes more about duty or image than affection. Tenderness and play belong alongside the shared goals. Your devotion is proved over years, quietly, rather than declared in one grand moment.",
      "aquarius": "Friendship is the foundation of commitment for you. You want an equal, someone independent and a little unusual, and you are happy to write your own relationship rules rather than follow the standard script. Honesty matters far more to you than sentimentality, and you would rather hear an uncomfortable truth than a pretty lie. You need to know your partner would still choose you if nothing obliged them to. Keeping closeness at arm's length in the name of freedom is your habit when feelings get big, and you go quiet just when warmth is needed. Your relationships flourish when you let yourself be intimate while protecting the space you both need to stay yourselves.",
      "pisces": "You long for a partner who feels like a soulmate, someone who understands you without a word being said. Your devotion is tender, selfless and healing, and you offer compassion where others would give up. That same softness leaves you open to idealising a partner, rescuing them or staying out of pity long after love has faded. Boundaries blur easily, and you can lose track of where their sadness ends and yours begins. Partnership becomes a spiritual path for you when both people stay honest. Compassion paired with clear sight lets you love the actual person in front of you rather than the dream of them."
    }],
    ["asteroids.vesta.signs", {
      "aries": "Your focus is at its fiercest at the start of something new. You love the first week of a project, the empty page, the solo run at dawn when nobody else is awake, and working on your own terms brings out your deepest concentration. Courage is the flame you tend, and you feel called to break ground rather than follow a trail. Sexuality is direct and spontaneous, or channelled into sport and competition. A month of blazing followed by sudden burnout is a familiar pattern. Your devotion lasts when you pace yourself and keep returning to the same fire instead of rushing to light the next one.",
      "taurus": "Your devotion is steady, sensual and practical. You pour yourself into work that produces something you can touch: bread, a garden, a piece of music, a savings account built one month at a time. The body and the natural world feel sacred to you, and an hour with your hands in soil can put you right. Sexuality is slow, sensuous and closely tied to trust. Your patience is remarkable, though routines can harden into ruts you defend long after they stopped serving you. Pleasure is part of the devotion, not a reward withheld until the work is done, and your flame burns brighter once you let it be.",
      "gemini": "Your mind is the temple. You can lose an entire weekend to a subject that grips you, reading, writing, researching or teaching with an intensity others find surprising. A notebook, a library card or a long course of study can become a quiet form of worship. Sexuality often runs through wit and conversation, and a sharp exchange of ideas is its own kind of intimacy for you. Scatter is the problem: ten projects begun, one finished, and a creeping sense of never going deep. Choosing a single field or craft and staying with it far past the point of novelty is where your devotion catches fire.",
      "cancer": "Home is your sanctuary, and tending it feels close to sacred. You focus deeply on caring for the people you love, keeping family recipes alive, preserving traditions and making a place where everyone can rest. Inside that home you still need a private corner of your own, a room or a chair or an hour that belongs to nobody else. Sexuality is tender and closely tied to feeling emotionally safe. Too often you give so much to family that nothing is left for your own calling, the course you never took or the book you never wrote. Your flame burns best when you count yourself among the people you care for.",
      "leo": "When you create, you disappear into it completely. Art, performance, a costume sewn late into the night or a party planned down to the playlist: anything that lets your heart shine becomes a sacred act. You work with great intensity and warmth, and people feel the love you pour into what you make. Sexuality is expressive and playful, or it goes straight into the creative work itself. Tying your worth to how your creations are received is the trap, so that a lukewarm review feels like a verdict on you. Creating for the sheer joy of it keeps the flame pure, and applause becomes a pleasant bonus rather than the point.",
      "virgo": "Small, repeated acts done well feel like prayer to you. You focus deeply on perfecting a craft, refining a system or caring for others in practical ways, and your morning routine can have the quality of a ritual. Health, healing and order feel sacred, and a clean kitchen at the end of the day gives you a quiet peace. Sexuality is private and discerning, shared only where trust is secure. Overwork creeps in, along with a perfectionism that never lets anything be finished. Treating rest as part of the ritual rather than a break from it keeps your flame steady for the long haul.",
      "libra": "You devote yourself to relationships, beauty and fairness, sometimes to a partner, sometimes to the arts, sometimes to a cause. A tension runs through you between needing solitude and needing a companion, and you are happiest with someone who respects the door you occasionally close. You care about how things look and feel, from the flowers on the table to the tone of an apology. Sexuality is often refined and bound up with harmony. The danger is dissolving into a partner's life until your own practice goes cold. Tending your own flame while sharing your life keeps both the relationship and your sense of self alight.",
      "scorpio": "You focus with an intensity that can unnerve people. Research, healing, psychology or anything that uncovers what is hidden draws you in, and you will dig for months until you reach the bottom of it. Sexuality can feel powerfully sacred, a doorway to transformation, or be poured wholly into your work. You need privacy and firm control over who glimpses your inner life, and your deepest commitments often stay completely secret, which is part of their power. Obsession is the shadow side, along with secrecy that slides into mistrust. Your flame burns cleanly when that intensity is turned towards healing rather than control.",
      "sagittarius": "You are devoted to the search for meaning. Philosophy, spirituality, teaching, travel or a cause you believe in can absorb you for years, and you feel called to a lifelong quest for understanding. A pilgrimage, whether a walk across Spain or a slow inner journey, reignites your sense of purpose when life goes flat. Sexuality is adventurous or folded into a sense of mission. Fervour can harden into dogma, and restlessness can keep you from ever going deep. Your flame is steadiest when your beliefs keep growing and you stay a student even after people start calling you a teacher.",
      "capricorn": "Work, for you, often feels like a vocation. You pursue a career, a long term goal or a legacy with great discipline, and you are the person still showing up long after others have lost interest. That steadiness is its own form of devotion. Sexuality is reserved, or channelled into ambition and achievement. The shadow is workaholism: the office light on at nine, the holiday spent checking email, a loneliness you barely notice. Success becomes nourishing once you let people into the structure you are building, so that the life you have worked for includes the connection you need.",
      "aquarius": "You devote yourself to ideals, innovation and the collective good. Causes, communities, science and future facing projects absorb you, and you feel called to serve humanity in some concrete way. Long stretches of independent work suit you best, time to think without interruption and follow an idea wherever it leads. Sexuality is unconventional or detached from traditional expectations. Caring passionately about people in general while missing the friend who needed a phone call is the blind spot. Your flame warms when your ideals come home into your closest relationships, so that the people beside you feel the same devotion you give the world.",
      "pisces": "Your devotion is spiritual, compassionate and imaginative. Meditation, art, music, healing or service to those who suffer can hold your attention for hours, and solitude feels essential, not optional. You are acutely sensitive to atmosphere, so a cluttered room or a loud evening leaves you frayed, while music or water brings you back to yourself quickly. Sexuality is mystical, idealised or sublimated into spiritual practice. Escaping into devotion to avoid the washing up, the tax return and the ordinary mess of life is the temptation. Your flame burns best when spiritual focus is grounded in daily practice and clear, kind boundaries."
    }],
    ["bigThree.asc.*.love", {
      "aries": "Attraction hits you fast and you rarely hide it: you are the one who sends the first message, suggests the drink, turns up with the tickets already bought. A crush feels like a race you want to win, and the chase itself can light you up more than you like to admit. Partners spot your interest from day one, which is refreshing in a world full of mixed signals. Trouble arrives in the quieter second act, when the thrill settles and nothing needs conquering, and you catch yourself restless or picking a small fight just to feel the spark again. Someone who pushes back, teases you and keeps their own fire earns far more of your respect than someone who agrees. Beneath the bravado, you want to be chosen as fiercely as you choose.",
      "taurus": "Nobody rushes you into anything, least of all love. You notice someone for weeks before you let them know, and the early dates you like best are slow ones: a long lunch, a walk that becomes dinner, a hand resting on the small of a back. Attraction for you lives in the senses, in a voice, a scent, the way someone holds a glass. Partners often feel calmer after an evening with you and cannot quite say why. Once you have settled on someone, though, you hold on long after the relationship has stopped nourishing you, because leaving feels like tearing up roots. Possessiveness can creep in quietly, dressed as devotion. Your loyalty and your physical affection are the kind people remember for the rest of their lives.",
      "gemini": "Flirting, for you, is a conversation that refuses to end. You fall for someone over a two hour message thread, a shared joke nobody else gets, a book recommendation that turns into a debate. Early attraction feels electric because your mind is lit up, and you can be wonderfully funny and quick with someone new. People often mistake your easy chatter for lighter interest than you feel. Once the novelty fades, you notice the pull of other conversations and can drift without quite meaning to, which leaves partners confused about where they stand. You talk about feelings brilliantly and sometimes use the talking to avoid feeling them. A partner who keeps surprising you, and who lets you think aloud without judging, holds your heart far longer than you would guess.",
      "cancer": "You feel someone out long before you let them in. Early attraction for you is a careful dance: you remember their coffee order, ask about their mother, cook the second time you meet, all while keeping your own heart well hidden. Partners often feel cared for before they know anything real about you. That instinct to nurture draws people close, and it also lets you avoid the frightening part, which is being seen. A careless remark on the third date can close the door for good, and the other person never learns why. You are sentimental in ways that surprise people, keeping the ticket stub and the first text. Once you feel safe, you love with a devotion that makes a home out of any relationship.",
      "leo": "When you like someone, everyone can tell. You plan the memorable date, pick the good restaurant, dress for the occasion and make the other person feel like the only one in the room. Courtship brings out your generosity and your playfulness, and early romance with you feels like being lit by sunshine. You are drawn to people who admire you openly and also have their own spark, because a pale admirer bores you. Trouble comes when the applause fades into ordinary life: a partner who forgets to notice the effort can leave you quietly wounded and cooler than you realise. Pride makes it hard to say you feel neglected, so you perform happiness instead. Loved with warmth, you are among the most loyal partners in the zodiac.",
      "virgo": "Your affection shows up as noticing. You remember that they hate coriander, fix the wobbly shelf in their kitchen, send the article about the thing they mentioned once. Early attraction makes you shy and slightly formal, and a new partner often has to work out that the practical help is the love letter. You screen people carefully and can spot a red flag on the first date that friends miss for months. That same sharp eye turns on partners too, and small irritations about how they load the dishwasher leak out as criticism. Letting someone see you messy, unsure or unwell feels far harder than looking after them. With a patient, playful partner, you relax into a tenderness that is devoted.",
      "libra": "Charm is your native language in romance. You know the right thing to say, the flattering restaurant light, the small courtesy that makes someone feel adored, and early dates with you feel effortless. You are drawn to beauty, good manners and people who make you look good together. Partners often take a while to realise how much you have adjusted yourself to suit them, from the music you claim to like to the plans you agreed to. You find it far easier to be in a relationship than to be alone, and you sometimes stay too long in the wrong one to avoid the ugliness of ending it. Conflict with someone you love feels unbearable. The partner who asks for your real opinion, and wants it, is the one who wins you.",
      "scorpio": "Attraction for you is all or nothing, and you usually know within minutes which one it is. You watch a new person closely, asking questions that go deeper than the moment requires, while giving very little away yourself. People find this magnetic and a little unnerving. Small talk dates bore you, and you would rather spend three hours in a dark bar discussing everyone's secrets. Early on you run quiet tests, noticing whether someone keeps their word or tells the same story twice. One small lie can end things for you entirely, and jealousy rises faster than you want to admit. Earn your trust and your devotion is total, and the other person feels fully seen for the first time in years.",
      "sagittarius": "You fall for people who make life feel bigger. A spontaneous road trip, a late night argument about philosophy, a first date that ends in a different city: this is what romance means to you. Early attraction is joyous and full of laughter, and you are generous with enthusiasm and honest to the point of bluntness. You are drawn to people who are going somewhere, literally or otherwise. Things wobble when a partner wants you home on Tuesday nights and you feel the walls closing in. Jealous or clingy behaviour sends you straight out of the door, and you also say things with such cheerful candour that you do not notice the hurt they cause. With a partner who travels beside you, you are wonderfully loyal.",
      "capricorn": "Romance with you starts slowly and seriously. You rarely flirt in the obvious way; instead you show interest by turning up on time, remembering what was said and making plans for the future. New partners sometimes wonder whether you like them at all, and then discover you have already pictured how they would fit into your life in five years. You are drawn to competence, ambition and people who have their act together. The difficulty is that you keep your softer side locked away, and a partner can feel they are dating your composure rather than you. Work often wins the battle for your time. Behind the composure, your dry humour and deep loyalty make you an extraordinary long term partner.",
      "aquarius": "Friendship comes first for you, and many of your romances begin as years of easy companionship. You are drawn to the unusual person at the party, the one with strange opinions and an interesting life. Early attraction feels like meeting a mind you can talk to about anything, and you are refreshingly free of games and jealousy. Partners sometimes find you hard to read, because you discuss feelings as if they were ideas. When emotions get intense, you step back and go cool, which can feel like rejection to someone who wanted closeness. You need space, your own friends and room to be odd. Respect that, and you are surprisingly loyal and accepting of a partner's own eccentricities.",
      "pisces": "You fall in love with a person's potential as much as with the person in front of you. Early attraction feels like a film, full of meaningful coincidences, long gazes and songs that seem written for the two of you. You sense what a new partner feels almost before they do, and people open up to you on the first date in a way they never expected. The catch is that you see what you long to see, missing the warning signs friends point out, and you can shape yourself around a partner until you vanish. Rescuing someone can feel like romance to you. When the dream breaks, the heartbreak is total. Your tenderness, offered to someone kind and grounded, is a rare gift."
    }],
    ["bigThree.asc.*.work", {
      "aries": "In a new job you are usually the one who volunteers before the manager finishes the sentence. Colleagues clock you within a week as the person who gets things moving, and you are often handed the stalled project nobody else wanted to touch. You work in bursts: a blazing first push, a draft sent at midnight, a problem solved while others are still booking the meeting to discuss it. The long middle of a project, with its sign-offs and slow approvals, drains you faster than any deadline. Meetings that circle without a decision make your foot tap under the table, and people notice. Your real value shows in a crisis, when hesitation costs money and you act, which is why the teams you leave often realise too late how much momentum you supplied.",
      "taurus": "Around the office you read as unflappable, the person whose desk stays tidy while everyone else panics. You rarely promise quickly, and when you do give a date, everyone believes it. Your working style is steady and thorough: you would rather finish one thing properly than start five, and you redo work that someone else rushed. A new manager who changes the system every quarter wears you out more than a heavy workload ever could. Comfort matters to your output more than you let on, so the good chair, the decent coffee and the familiar route in are not luxuries to you. Pay and security weigh heavily in your choices, and you are shrewd about both. Over the years, your reliability becomes a kind of quiet authority.",
      "gemini": "Within your first week you know half the building, including who to ask for anything. Colleagues see you as the quick one, the person who picks up new software in an afternoon and can explain it to everyone else by Friday. Your working day runs on several tabs at once: a report half written, three chats open, a new idea jotted on a sticky note. You are brilliant at pitching, briefing and translating between departments that do not understand each other. Trouble shows at the finish line, where the dull final tenth of a task sits waiting while you chase something fresher. A job with the same tasks every day drains you surprisingly fast. Put you where information moves and you become indispensable.",
      "cancer": "You notice who has gone quiet at their desk and whose child has been poorly. Before long you become the unofficial heart of a team, the person new starters go to when they are lost. Your working style is loyal and protective: you look after your people, guard your projects and take criticism of your team almost personally. You read the mood of a meeting in seconds, which makes you excellent with clients and difficult to fool. A cold manager or a cutthroat office, however, can rattle you for weeks, and you carry work feelings home in a way others do not. You rarely leave a job lightly. Where loyalty runs both ways, you give years of steady, caring service.",
      "leo": "People assume you are in charge, sometimes before you are. You walk into a presentation and the room settles, and colleagues find themselves looking to you when a decision needs making. Your working style is wholehearted: you pour yourself into projects you believe in and lend your energy to the whole team. Credit matters to you more than you would admit, and seeing your idea presented by someone else stings for days. You are brilliant at pitching, hosting, launching and anything with an audience. Routine back office work without recognition dims you quickly, and you start coasting without realising why. Praise you in public and you give twice the effort in return, which smart managers learn fast.",
      "virgo": "Colleagues quickly learn that if something needs checking, it goes to you. You spot the typo in the contract, the error in the spreadsheet and the step missing from the process, often before anyone else has read the brief. Your working style is methodical and excellent, with notes, lists and a system that makes sense only to you. People trust you enormously, which is how you end up doing three people's jobs without a pay rise. Praise makes you uncomfortable, and you downplay work that deserves credit. Sloppy colleagues test your patience more than difficult ones. Your reputation for getting things right becomes your greatest asset, and managers lean on you more than they ever admit.",
      "libra": "Clients love you, and so do colleagues who would not normally get along. You are the one who can deliver bad news so politely that people thank you for it. Your working style is collaborative: you think best in conversation, bounce ideas off others and make sure everyone feels included in the meeting. Aesthetics matter to you at work too, from a well laid out slide to a tidy shared space. The sticking point comes when a decision falls to you alone, and you ask for one more opinion, then another, until the deadline decides for you. Refusing extra work from someone you like is also hard for you. Where fairness and teamwork are valued, you become the glue that holds the whole place together.",
      "scorpio": "Colleagues sense quickly that you know more than you say. You sit quietly in meetings, then ask the one question that exposes the flaw in the whole plan. Your working style is focused and private: you prefer to go deep on one problem, work alone and deliver something thorough rather than share half-finished drafts. People trust you with confidential matters because you never leak. You notice office politics instantly, including who holds power, and you do not forget who crossed you. Crises that send others into a spin make you calm and sharp. Your reserve can read as hostility to new managers, who sometimes feel you are sizing them up, which of course you are.",
      "sagittarius": "In any office you become the optimist in the room, the person who says yes, why not, when everyone else is listing risks. You are brilliant at the big idea, the inspiring pitch and the conference trip, and you often end up as the team's unofficial morale officer. Your working style is fast and broad: you see where a project could go in five years and lose patience with the paperwork needed to get it there. Deadlines slip because you said yes to three exciting things at once. Blunt feedback from you lands harder than you intend, particularly with sensitive colleagues. Micromanagement makes you miserable. Given freedom, travel or something to teach, you work with an energy that lifts everyone around you.",
      "capricorn": "People assume you are more senior than you are, often from your first day. You arrive prepared, speak when you have something to say and hold yourself with a quiet authority that managers notice. Your working style is disciplined and strategic: you plan the long route to a goal, build your reputation brick by brick and rarely cut corners. Colleagues trust you with the serious responsibilities, the budget, the difficult client, the audit. You are also the one still at your desk when the cleaners arrive, and holidays often come with a laptop. Frivolous workplaces or disorganised bosses test your patience badly. Across a career, your steadiness carries you further than flashier rivals, and the respect you earn lasts.",
      "aquarius": "It takes colleagues about a fortnight to notice that you question everything, from the filing system to the company mission. You see how a whole system works and how it could work better, and you are often the person proposing the new tool or the fairer process. Your working style is independent: you like freedom to work in your own way, at your own hours, with minimal supervision. Hierarchy for its own sake irritates you, and you struggle to hide it when a boss pulls rank. Teams value your fairness and your willingness to speak up for others. You work best around people who share a cause. The difficulty is that brilliant ideas die in committee when you will not play the politics needed to get them through.",
      "pisces": "People at work often find themselves telling you things they would never tell a manager. You read the mood of a room, notice who is struggling and help without fuss. Your working style is intuitive rather than linear: you solve problems through sudden insight, work in creative bursts and often cannot explain how you reached the answer. Rigid rules, harsh managers and cutthroat targets drain you quickly. You absorb the stress of a workplace like a sponge and carry it home, sometimes without realising it belongs to others. Deadlines blur when you are lost in a task you love. In caring, creative or healing roles, your gift for understanding people makes you irreplaceable to everyone you work beside."
    }],
    ["bigThree.asc.*.shadow", {
      "aries": "When you feel cornered, your first instinct is to charge. A curt email fires off before you have finished reading theirs, a door closes harder than you meant, a disagreement becomes a contest you must win. Then the rush drains away and you find yourself apologising for your tone while still privately certain you were right. Waiting feels like weakness to you, so you sometimes create a crisis to have something to push against. Your body keeps score too: the stubbed toe, the cut from rushing the chopping, the tension headache after a week of forcing things. Underneath all the heat sits a young, tender fear of being overlooked or powerless. The moment you are met with respect, most of the fight leaves you.",
      "taurus": "Pushed too hard, you go still: someone raises their voice and you stop moving, arms folded, conversation over, and no argument on earth will shift you until you decide. You know you are digging in, and part of you enjoys the solidity of it. Stress sends you towards comfort: the second helping, the online basket filled at midnight, the same show watched for the fourth time. Change that arrives without warning feels like a physical threat, and you will defend a bad arrangement because it is familiar. Resentment in you builds slowly and leaves slowly, sometimes years after the other person has forgotten. At the root is a fear of the ground going from under you. People who wait you out are often amazed by how gently you come round.",
      "gemini": "Anxiety in you comes out as noise. You talk faster, check your phone more, open another tab and fill the silence before anyone can see that you are rattled. A secret gets passed on because it was interesting, and you regret it the moment it leaves your mouth. Plans change at the last minute because a better option appeared, and friends start to wonder whether you will turn up. You can argue both sides of anything so fluently that nobody, including you, is quite sure what you believe. Sleep suffers first, with your mind still running conversations at two in the morning. Underneath is a fear of being pinned down, or of being fully understood and found wanting.",
      "cancer": "Hurt sends you sideways rather than straight at the problem. You go quiet, answer in single words, or do the kind thing with a slight edge that everyone can feel. A small slight at work replays for days while you build an entire case in your head that the other person never hears, and your care can tip into managing people: the extra phone calls, the worried questions, the help nobody asked for. Moods roll through you like weather, and you expect the people closest to you to read the forecast. Retreat feels safer than confrontation, so you disappear for a while and wait to see who notices. At the root is an old fear of being rejected for needing too much. Reassured and held, you come back out warmer than before.",
      "leo": "Wounded pride is your pressure point. A throwaway criticism in a meeting lands like a public humiliation, and you either go frosty or put on a bigger show to prove it did not hurt. You find yourself steering every conversation back to your story, then feeling faintly ashamed on the drive home. Admitting a mistake feels almost physically difficult, so you defend a position long after you have privately abandoned it. When you are tired, the performance continues anyway, because being seen struggling feels worse than exhaustion. The drama that sometimes erupts is a bid for reassurance, and beneath the confident smile lives a child who wants to know they matter. Real appreciation, given freely, dissolves your need to dominate faster than any argument could.",
      "virgo": "Stress turns your helpful eye into a harsh one. You lie awake replaying the email you sent, spot every flaw in a perfectly good piece of work, and hear criticism in a colleague's neutral comment. Worry finds a new home as soon as the last one is solved, often landing on your body: a twinge becomes a condition by midnight after too much searching online. You keep busy to avoid feeling, so the kitchen gets deep cleaned when the real problem is loneliness. Other people receive the critique you aim at yourself, and you sound sharper than you intend. At the core is a fear that one mistake will prove you were never good enough. Told plainly that you are enough, you exhale.",
      "libra": "Your darker side wears a pleasant smile. You say it is fine when it is not, agree in the meeting and then vent in the car park, and let resentment build quietly behind perfect manners. Choosing anything, from a restaurant to a life path, can freeze you, because every choice disappoints someone. You mirror whoever is in front of you so smoothly that you lose track of what you think. When pushed too far, the anger arrives cold and sudden, surprising everyone including you, and people come away calling you two faced when in truth you are terrified of being disliked. Beneath the grace lies a fear of being abandoned the moment you show your true preferences. Being liked for your honesty changes everything for you.",
      "scorpio": "Betrayal, or even the hint of it, turns you to stone. You go silent, file the offence away and start rearranging your life so that person can never hurt you again. You check phones, reread messages and look for the hidden meaning in a casual remark. Sometimes you strike first with a precise, cutting line that leaves the other person reeling, then feel both satisfied and ashamed. Letting go is hard, and old wounds can be carried for decades without anyone knowing. Control becomes a way of feeling safe: you need to know, to be in charge, to hold the upper hand, because underneath lies a terror of being exposed and powerless. With someone who stays through your intensity, the walls come down.",
      "sagittarius": "When life gets heavy, you reach for the exit. Another trip gets booked, a new course starts, a plan is made for next year, anything rather than sitting with what is going wrong now. Jokes appear at the moment someone needs you to be serious, and they feel brushed aside. You promise generously in a good mood and then find yourself unable to deliver, leaving a trail of disappointed friends. Certainty can harden into preaching, and you lecture people about the right way to live while ignoring your own mess. Tactless truths fly out of you like sparks, and at the root sits a fear of being trapped in a small life with no meaning. Once you find a purpose worth staying for, you steady beautifully.",
      "capricorn": "Pressure makes you colder and harder. You pull the drawbridge up, go into work mode and handle everything yourself, then feel quietly bitter that nobody helped. Pessimism creeps in, and you start expecting the worst of plans, people and your own future. You can judge others harshly for a weakness you will not forgive in yourself. Feelings are postponed until a convenient time that never quite comes, and loneliness hides behind a full diary. Status starts to matter more than joy, and beneath the control lies a fear of failing, of being seen as incompetent, of losing the respect you worked so hard to earn. Whoever sees the tired person under the armour, and stays anyway, gets to meet all of your warmth.",
      "aquarius": "Emotional heat makes you go glacial. You retreat into your head, talk about a painful situation as if it were a case study, and leave people feeling they are speaking to a closed door. Being told what to do brings out the contrarian in you, and you will argue the opposite just to prove you cannot be controlled. Your opinions harden into principles that nobody is allowed to question. Friends who need comfort get analysis instead, and you sense the distance but cannot bridge it. Rebellion without a cause can cost you jobs, relationships and allies, and at the core is a fear of being swallowed up or made ordinary. Around people who accept your strangeness, the chill melts into warmth.",
      "pisces": "When reality gets too loud, you drift away. The phone goes unanswered, the bills stay unopened, and the evening disappears into scrolling, a bottle of wine or a long daydream. You avoid saying no, so you say yes and then fail to show up. Small untruths slip out to keep the peace, and they tangle into a story you struggle to maintain. Other people's pain floods you, and you end up believing everyone else's version of events over your own. Feeling like the victim becomes a place to hide, and underneath it lies exhaustion from absorbing too much for too long. Your compassion, protected by firm boundaries, becomes a power in other people's lives."
    }],
    ["bigThree.moon.*.love", {
      "aries": "You fall for people quickly, and you usually know within the first few conversations. What you need emotionally is a partner who can take the full temperature of your reactions: the flash of annoyance when plans change, the burst of delight when they surprise you, the heat that passes within the hour. A row that is shouted, settled and followed by laughter over dinner feels healthier to you than a week of careful politeness. You show love by doing: turning up at their door, fixing the problem, defending them to anyone who criticises them. The hard part comes when a partner needs you to slow down and listen, because your instinct is to charge in and solve. Someone who stays steady through your fire, and lets you be tender without making a fuss about it, wins you for life.",
      "taurus": "In love you want something you can feel with your hands. A partner who remembers how you take your tea, who reaches for you on the sofa without being asked, who is still there on an ordinary Tuesday, reaches you far more than grand declarations. You give the same way: a warm meal waiting, the heating on before they get home, a gift chosen because they mentioned it once months ago. Trust grows slowly with you, and once it has grown it is very hard to shake. The trouble starts when a partner wants to move house, change jobs or rethink the relationship, and you hold on tighter instead of listening. Love stays alive for you when you let the person beside you keep changing and trust that the bond can bend with them.",
      "gemini": "You need to be able to talk to the person you love, about anything, at any hour. The relationship feels alive when there are running jokes, voice notes sent from the supermarket and long evenings spent arguing happily about a film. A partner who goes quiet for a day can set your mind racing through every possible explanation. You flirt with words, and wit is often the first thing that draws you in. Where you struggle is staying put when a conversation turns heavy, because you reach for a joke or a clever reframe just as your partner needs you to feel it with them. The person who can match your quickness and also sit beside you in silence is the one who makes that silence stop feeling like a threat.",
      "cancer": "In love you want a home, and the person you choose becomes part of it. You remember their mother's birthday, the song from your first date and how they like their eggs, and you read their mood from the way they close the front door. What you need back is proof that you are safe: a partner who texts when they are running late, who does not treat your feelings as too much, who comes back after an argument rather than going cold. Rejection lands in you like a physical blow, so you often test the water sideways before saying what you want. Love blossoms for you when you trust someone enough to show your soft centre first, without waiting to see whether they will reach it.",
      "leo": "Romance matters to you, openly and unashamedly. You want to be chosen, to see a partner's face light up when you walk in, to be introduced proudly to their friends. Your love is lavish: surprise dinners, heartfelt cards, fierce defence of them to anyone who dares criticise. A forgotten anniversary can hurt far more than you let on. You need a partner who plays, who still flirts with you years into the relationship and who notices when you have made an effort. The difficulty comes when pride stops you admitting that you feel insecure or unseen, so you perform happiness instead. You feel most loved when someone adores the tired, unglamorous you just as much as the dazzling one.",
      "virgo": "You love through small, practical acts. You fix the dripping tap, book the appointment they keep forgetting, notice they are low on vitamins and restock the cupboard. What you need is a partner who reads these gestures as the love letters they are, and who does not hear your helpful observations as criticism. Grand emotional speeches can make you squirm, and you trust a person who shows up on time far more than one who says beautiful things. Being cared for is harder for you than caring: when someone brings you soup in bed, part of you wants to get up and wash the pan. Your deepest intimacy comes when you let a partner see you messy, tired and unproductive, and discover that they stay.",
      "libra": "Partnership is where you feel most yourself. You need a relationship that feels balanced, courteous and shared: turns taken, efforts noticed, beautiful evenings planned together. You are remarkably attentive, often knowing what your partner wants for dinner before they do, and you shape your plans around theirs with ease. The catch is that you can agree to the restaurant, the holiday and the friends before you have worked out what you would prefer. Rudeness or coarseness in a partner puts you off quickly, however attractive they are. You need someone who welcomes your honest opinions, even the inconvenient ones, and who can disagree with you without the air turning cold. The best relationships for you are ones where both sets of wishes carry equal weight, yours included.",
      "scorpio": "Love for you is all or nothing. You need a bond with depth: late-night conversations where nothing is off limits, a partner who knows your history and has not flinched. Small talk and casual dating leave you cold, and you can sense within minutes whether someone is being real with you. Once you commit, your loyalty is fierce and you would go to war for the people you love. Trust is the crux. A vague answer about where they were, a phone turned face down on the table, and your mind builds a case before you have said a word. You feel safest with a partner who is transparent by nature, and closeness deepens each time you show a fear instead of quietly testing them.",
      "sagittarius": "You need a partner who feels like a fellow traveller. Love lights up for you on a last-minute weekend away, in a heated debate over a bottle of wine, or during a Sunday spent wandering a city neither of you knows. Honesty matters more to you than tact, and you trust a partner who tells you the truth even when it stings. Jealousy, heavy scrutiny or a sense of being fenced in make you want to book a flight. You laugh easily together and forgive quickly. The hard part arrives in the slow, ordinary stretches of a relationship, when nothing new is happening and you mistake contentment for stagnation. Staying close through those stretches turns out to be its own adventure, and a deeper one than you expected.",
      "capricorn": "You take love seriously, and you prove it in actions rather than words. You are the partner who remembers to renew the insurance, drives across the county when the car breaks down and plans for a shared future years ahead. Opening up emotionally takes time, and you watch carefully to see whether someone is committed before letting them in. Romantic speeches can make you uncomfortable, while a partner who keeps their word wins you completely. The difficulty is that you carry worries alone, so a partner often only learns you were struggling after the crisis has passed. What you need is someone patient enough to reach past your competence and gentle enough to make leaning on them feel safe.",
      "aquarius": "Friendship is the foundation of love for you. You fall for minds before bodies, and your best relationships feel like a partnership of two unusual people who happen to adore each other. You need plenty of space: separate interests, time with your own friends, evenings where you each do your own thing in the same room. Clinginess or jealousy makes you pull away almost instantly. You are loyal and accepting, rarely trying to change a partner, and you respect their oddities as much as your own. Trouble comes when a partner wants to hear how you feel, and you offer a thoughtful analysis instead. Letting feelings show while they are still raw, before you have worked them out, is what turns fondness into intimacy for you.",
      "pisces": "You love with your whole heart and very few defences. You sense a partner's mood from a single word in a message, and you often know what they need before they do. You long for a soulmate bond: shared music, private jokes, a feeling that you understand each other without speaking. Romance can glow so brightly in your imagination that you see who someone could be rather than who they are. You also give until you are empty, putting their needs first and shelving your own. The hardest lesson for you is spotting the difference between love and rescue. The right partner is kind and steady, and able to love you back as fully as you love them."
    }],
    ["bigThree.moon.*.work", {
      "aries": "At work your feelings run the show more than your job title suggests. A clear challenge and a deadline lift your mood, while a meeting that circles the same point for forty minutes sours it by lunchtime. You are the colleague who volunteers first when something breaks, and you often do your best thinking while already moving. Being told to wait for sign-off from three people feels almost physically uncomfortable. Irritation shows on your face before you have decided whether to say anything, and a sharp email sent in the heat of the moment is a familiar regret. Still, your enthusiasm is catching, and teams move faster once you are in the room. Give you a piece of work to own outright and a quick result to see, and your mood stays bright all week.",
      "taurus": "Your emotional state at work depends more on the setting than most people would guess. A comfortable chair, decent light, a proper lunch and a desk that feels like yours all keep you even. You pace yourself well and rarely burn out in a blaze, finishing what you start while others abandon half-built projects. Colleagues rely on your calm when a deadline looms, because panic does not take hold of you the way it does of them. The difficulty is sudden change: a new system announced on Monday for Wednesday, or a reshuffle that moves you to a different team, can leave you unsettled for weeks. Given time to build something solid, you become the quiet backbone of any team.",
      "gemini": "Work feeds your emotional wellbeing when your mind is busy and people are within reach. You feel brightest juggling a few projects, answering questions on the team chat and bouncing between conversations, and a day alone with a spreadsheet can flatten your mood by mid-afternoon. You often become the office's informal switchboard, the one who knows what every department is doing and can explain it plainly. Stress in you sounds like talking faster, drafting and redrafting the same message, or replaying a meeting in your head at 2am. Scattering is the real hazard: ten things started, three finished. Variety built into the day and someone to think aloud with keep you at your best.",
      "cancer": "At work you turn a team into a family. You remember who has a sick parent, bring in biscuits on a hard day, and become the person new starters go to when they feel lost. Loyalty runs both ways for you: you stay with a manager who cares for you long after a better offer arrives, and you remember for years a boss who humiliated you in a meeting. A cold, purely transactional culture wears you down in ways that are hard to name. Your mood colours your output more than you like to admit, so a good week at home often means a good week at your desk. You thrive where people are treated as human beings and your care is valued rather than taken for granted.",
      "leo": "Your emotional wellbeing at work rises and falls with recognition. A sincere thank you in front of the team keeps you glowing for days, while an idea of yours quietly credited to someone else can sour a whole month. You bring warmth that makes an office feel alive: the birthday card organised, the pep talk before a big pitch, the joke that breaks the tension. You work hardest for leaders who believe in you, and you wilt under ones who only ever point out what is wrong. Being made to follow a dull template feels faintly insulting. Visibility, trust and the freedom to put something of yourself into the work are what keep your heart in it.",
      "virgo": "Work can feel like a relief to you, because a clear task gives your feelings somewhere useful to go. You notice the figure that does not add up, the deadline everyone else has forgotten, the colleague who has gone quiet and needs a hand, and you deal with each one without fuss. Being useful calms you, which is why you say yes to one more job long after your list is full. Sloppy standards around you create a low hum of irritation that others rarely see. The hard part is the voice that grades your performance: one small mistake can overshadow a week of excellent work in your own mind. Sensible routines and someone who notices good work make all the difference to how you feel.",
      "libra": "At work you are the one who smooths the edges. You rephrase a blunt message so nobody takes offence, introduce people who ought to know each other and sense tension in a meeting before voices are raised. Clients and colleagues warm to you quickly. A pleasant, attractive workspace lifts your mood more than you would care to admit, and an openly aggressive boss leaves you shaken for days. Decisions made alone can stall, because you want to hear every view first, and sometimes the agreement you wait for never comes. Declaring a position of your own feels exposing, yet teams often need your fair judgement. Roles built around cooperation, negotiation, design or bringing people together suit your temperament beautifully.",
      "scorpio": "At work you read the room like a detective. You know who holds power, which alliances are shifting and what the manager is not saying, often long before any announcement. You work with intensity, becoming absorbed in a problem until you have got to the bottom of it, and surface-level tasks bore you. Colleagues trust you with confidences because you keep them. You keep your own cards close, and few people at work know what you feel. Betrayal in a workplace is something you rarely forgive: a colleague who takes credit or breaks a confidence is filed away for good. You thrive where there is depth, privacy and something important at stake.",
      "sagittarius": "Meaning is what keeps you emotionally engaged at work. You feel alive when you believe in the mission, when you are learning something new or explaining a big idea to a room full of people. Enthusiasm pours out of you, and your optimism often carries a team through a difficult quarter. Tedious admin and tight supervision drain you fast, and you can mentally check out long before you leave a job. You also speak your mind in meetings, which wins respect as often as it causes awkward silences. Promises can outrun reality, because in your excitement you commit to more than any calendar holds. A broad remit and the sense that the work reaches beyond the office walls keep your spirit fed.",
      "capricorn": "Work is often where you feel most emotionally steady. Clear goals, a sense of progress and being trusted with responsibility give you a quiet satisfaction nothing else quite matches. You are the colleague who stays calm when the deadline collapses and works out a plan while others panic. Respect matters more to you than popularity, and an incompetent manager tests your patience severely. The trouble is that achievement becomes your main way of feeling okay, so a bad week at work can feel like a verdict on your whole worth. Late evenings at the laptop are sometimes easier than a quiet night with your own feelings. Sensible structure and effort that is rewarded bring out the best in you.",
      "aquarius": "You feel emotionally at home at work when you are part of something bigger than yourself. A team with a shared cause, a project that could change how things are done, or a company that treats people fairly keeps you engaged. You are often the calm, level voice in a heated meeting, able to separate the facts from the drama. Arbitrary rules and office hierarchy irritate you, and you tend to question them openly. Colleagues value your fairness and your refusal to play favourites. The trouble is that you can seem distant, so people misread your cool head as indifference. Collaborative, forward-looking settings suit you, particularly ones that welcome your ideas and respect your independence.",
      "pisces": "At work you absorb the atmosphere like a sponge. You know within minutes of arriving whether the office is tense, and a colleague's bad day can leave you drained by the evening. Your intuition is an asset: you sense what a client needs, what a team is not saying, and where a creative idea wants to go. Harsh deadlines, loud open-plan offices and aggressive managers overwhelm you more than they do most people. You work best in bursts of inspiration rather than rigid routines. Saying no to extra work is hard, because you hate letting anyone down. Creative, healing and caring roles let your sensitivity count as the strength it is."
    }],
    ["bigThree.moon.*.shadow", {
      "aries": "Your shadow shows up as heat used as armour. When something hurts, you go on the offensive before you have even registered the hurt: the clipped reply, the slammed cupboard, the decision to leave the party early without explaining. Being needy feels unbearable to you, so anger becomes the quicker, safer feeling. You can also treat other people's slower emotions as an obstacle, pushing a friend to 'just decide' when they are still working out what they feel. Afterwards the fire is gone and you have moved on, while they are still sitting with the burn. None of this comes from coldness. It comes from a part of you that learned early that waiting for comfort was pointless, and that part softens when someone meets your flare with patience rather than a counterattack.",
      "taurus": "Under threat, you dig in. When life feels uncertain you slow right down and refuse to budge, even when moving would help. A letter goes unopened for a fortnight, a difficult conversation keeps being postponed, a relationship that stopped working years ago stays in place because leaving feels like losing ground. Comfort turns from nourishment into a refuge: the extra glass of wine, the takeaway ordered for the third night running, the weekend spent under a blanket. Resentment builds in you quietly, and when it surfaces it can be startlingly firm. Underneath lies a very old fear that if the ground shifts, nothing will hold you. What loosens it is discovering, again and again, that you are sturdier than your circumstances.",
      "gemini": "When feelings get too big, you get clever. You narrate your own heartbreak as an amusing story before you have felt it, or you explain a friend's grief back to them in neat, reasonable terms that leave them feeling unheard. Your mind runs on nervous energy under stress: phone in hand, fifteen tabs open, a podcast playing so you never quite meet the quiet. Commitments made in a bright mood can be dropped when the mood changes, and people close to you sometimes struggle to know which version of you they will get. None of this is shallowness. It is a quick, sensitive nervous system trying to stay one step ahead of feelings it fears will swamp it, and it slows when you trust that you will not drown.",
      "cancer": "When you are hurt, the feeling goes underground. Rather than saying you feel left out, you go quiet, give clipped answers and wait for someone to notice. Care can slide into control: the extra phone call to check where someone is, the favour done so that they will owe you, the gentle guilt when a grown child moves far away. You can hold on to old slights with remarkable precision, replaying a comment from years ago as if it were said this morning. Moods settle over you and colour everything until they pass. Beneath the shell sits a child who once feared being left, and who still needs to hear that the people you love are not going anywhere.",
      "leo": "Pride is the hiding place for your hurt. When you feel overlooked, you either turn the volume up, telling the story louder and making your feelings the centre of the evening, or retreat into a wounded, regal silence that everyone can feel. A small slight, a friend forgetting to comment on your news or a partner praising someone else, can land far harder than it should. Admitting jealousy or insecurity is almost unbearable, so it comes out sideways as sulking or grand gestures. Sometimes you quietly keep score of who celebrated you and who did not. Beneath all of it lies a tender fear of being ordinary, and it quietens when you feel loved for being here.",
      "virgo": "Anxiety is where your shadow lives. Under pressure your mind combs through everything that could go wrong, from the email you phrased badly to the odd twinge in your stomach, and you lie awake drafting better versions of the day. The criticism you turn on yourself is harsher than anything you would say to another person, though it leaks out as nitpicking: rearranging the dishwasher someone else loaded, correcting a detail nobody else cares about. Busyness becomes a refuge, because tidying a drawer feels safer than sitting with grief. Underneath runs a fear of not being good enough to deserve love. That fear eases when someone cares for you on a day you have achieved nothing at all.",
      "libra": "Niceness is your shadow's favourite disguise. You say 'honestly, I don't mind' when you mind very much, then feel resentful that nobody guessed. Anger rarely arrives directly: it slips out as a pointed silence, a delayed reply, a sweet remark with an edge. Choosing between two options can drag on for days because every choice seems to disappoint someone. Your sense of self can start to depend on how a partner or friend feels about you that day, and when they are cool you feel off balance. Underneath is a fear that conflict will cost you the relationship and leave you alone. Every time you say what you feel and the bond survives, a little of that fear loosens its grip.",
      "scorpio": "When you feel threatened, you either go silent or go for the jugular. Withdrawal can be total: a door closed, messages unanswered, a person you loved treated as if they no longer exist. Other times you find the one sentence that wounds most, and you know where it will land. Suspicion can make you check, probe and test people who have done nothing wrong. Old betrayals are replayed until they feel fresh, which keeps the pain alive long after the event. Control feels like safety, so you manage carefully what others know about you. All of it guards against feeling powerless, and the guard drops only for someone who proves your vulnerability is safe in their hands.",
      "sagittarius": "You have a talent for leaving before the feeling arrives. A painful week turns into a sudden trip, a new course, a packed social diary, anything that keeps you moving and looking ahead. When someone is hurting, you can rush to the silver lining or a philosophical lesson before they have finished telling you what happened. Bluntness is another edge: a truth delivered without warmth can wound, and you are often surprised afterwards that it did. Promises made in a burst of enthusiasm can slip. Sometimes your certainty turns preachy, as if your way of seeing things were the only sensible one. What drives it is a fear of being trapped in pain, and each time you stay put you learn that the way out runs through the feeling.",
      "capricorn": "Under strain you go into lockdown. You stop talking about what is wrong, become brisk and efficient, and treat your own needs as a luxury you cannot afford. People close to you find you abruptly cold, answering questions about how you feel with a list of what needs doing. You can also judge other people's emotions as indulgent, telling a friend to pull themselves together when they needed comfort. You prepare for the worst and call it being sensible. Loneliness follows, because you have sealed yourself off from the very help you need. Being helped by someone who asks nothing in return is what slowly melts it, because the real fear is of being a burden.",
      "aquarius": "Detachment is your emergency exit. When someone brings you strong emotion, you can step back into analysis, offering a reasoned view when they wanted warmth, or disappear into a project, a forum, a long walk alone. Friends sometimes feel that a door has closed. Under pressure you can also turn contrary, digging in on a point of principle to avoid being pulled into a feeling you did not choose. Your need for freedom can make ordinary requests for closeness feel like attempts to control you. Loved ones are left confused, sensing that you care but unable to reach you. What you are guarding against is being swallowed up, and discovering that closeness and freedom can live together changes everything.",
      "pisces": "When life gets harsh, you drift away from it. Decisions get postponed indefinitely, sleep stretches into the afternoon, and a glass of wine, a series or a daydream becomes the softest place to land. You can also slip into the role of martyr, giving and giving until resentment surfaces and then feeling guilty for resenting anyone. Boundaries blur, so other people's crises become yours and you lose track of what you need. Sometimes you wait to be rescued rather than acting on your own behalf. Beneath the fog lies a deep overwhelm at how much you feel, and it lifts when you find that you can protect your gentleness without losing it."
    }],
    ["bigThree.sun.*.love", {
      "aries": "You fall fast and you say so, often before the other person has worked out what is happening. Early dates with you have an edge of play: you race them to the top of the hill, tease them about their driving, pick the restaurant nobody has tried. Wanting someone feels simple to you, and you rarely hide it behind games or long silences. The trouble comes in the lulls, the Sunday evenings with nothing to chase, when the relationship feels flat and you start poking at it just to get a reaction. A partner who pushes back, who answers your challenge with one of their own, keeps you interested far longer than one who always agrees. Underneath the bravado sits a tender loyalty, and when someone you love is threatened you are the first to stand in front of them.",
      "taurus": "You court slowly, and you notice everything: the brand of coffee they buy, the jumper they wear when they are low, the song that makes them go quiet. Love for you lives in the body, in a hand on the back of the neck, a shared bath, a Sunday that stretches from breakfast into dinner without anyone checking the time. Having chosen someone, you choose them again daily with a steadiness that feels like shelter. The difficulty arrives when your partner starts changing faster than you are ready for, a new job, a new friend, a new haircut, and you feel the ground tilt. Jealousy in you rarely shouts; it sits heavy in your stomach and turns into long, watchful silences. People who have been loved by you remember it as the most solid thing in their lives.",
      "gemini": "You fall for minds first, and the first sign of it is usually a conversation that runs until the bar staff start stacking chairs. Flirting with you is a volley of jokes, references and sudden tangents, and the person who can keep up wins your attention fast. Your affection arrives as a steady stream of messages: a photo of a strange dog, a link you knew they would love, a voice note from the bus. You need a partner who is also good company on a dull Tuesday, because boredom in a relationship frightens you more than conflict. Heavy emotional talks make you restless, and you catch yourself cracking a joke just when the other person needed you to stay quiet. Once you feel fully known, your loyalty surprises people who mistook your lightness for a lack of depth.",
      "cancer": "You love like someone building a home, and your partner soon finds their favourite biscuits in the cupboard and a hot water bottle waiting on cold nights. Early on you keep a careful distance, watching how someone treats a waiter or talks about their family before you let the guard down. Once you are in, you are all in, and the relationship becomes part of your family, with in-laws, traditions and inside jokes gathered like heirlooms. Your hurt, when it comes, rarely announces itself; it shows up as a sharper tone, a closed door, a meal made in silence. Partners who learn to read those signals and come towards you, rather than wait, discover a depth of tenderness that few people ever offer. Being cared for in return, properly and without having to ask, is what you long for most.",
      "leo": "You love out loud. The surprise weekend away, the birthday cake you baked yourself with their name piped across the top, the toast at the wedding that has half the room in tears: romance for you is theatre, and you are happy to direct it. You want to be chosen openly, introduced proudly, and looked at across a crowded room as if nobody else were there. Indifference wounds you far more than an argument, and a partner scrolling their phone while you tell a story can sting for days. Your pride makes it hard to admit when you are hurt, so it comes out as coolness or a performance of not caring. With someone who adores you and says so, you become the most loyal, playful and generous of lovers, and your affection makes people feel like royalty.",
      "virgo": "Love from you looks like a bled radiator, a collected prescription, a lunch packed with the crusts cut off the way they like it. You notice what your partner needs before they do, and meeting that need is how you say what words make you shy about saying. Courtship with you is careful, and you take time to trust that someone will not find your quirks and anxieties too much. Your observations can land wrong: a remark about their posture or the way they fold the towels, meant as care, heard as criticism. You long to be appreciated for the thousand small things you do unseen, and when nobody thanks you, resentment gathers quietly. A partner who teases you gently out of your lists discovers a playful, earthy sensuality that surprises even you.",
      "libra": "You are in love with love itself, and you do it beautifully: the candlelit table, the thoughtful gift wrapped just so, the perfectly timed compliment. Partnership feels like your natural state, and being single for long leaves you feeling slightly out of tune. You read your partner closely, and you often know what they are feeling before they have found the words. That same attunement can bury your own wishes, and the things you never said pile up behind the smile. Crude jokes, bad manners or a public scene can cool your feelings faster than any real betrayal. A partner who wants to hear your true preferences, even the inconvenient ones, gets an equal instead of a mirror, and your talent for making another person feel cherished has solid ground beneath it.",
      "scorpio": "Love for you is all or nothing, and a lukewarm relationship feels worse than none at all. You want to know your partner completely: their first heartbreak, the thing they have never told anyone, what their face does when they are lying. Desire runs strong in you, and sex is often where you feel closest and most exposed at once. You rarely give yourself away quickly, preferring to watch and wait until you are sure, and some partners feel the probing before they feel the warmth. Once bonded, you are fiercely protective, the person who would drive across the country at two in the morning if they needed you. Jealousy is the thorn: a harmless text or an old photograph can set off a slow burn you struggle to put out.",
      "sagittarius": "You flirt like an explorer, curious about everything the other person has seen and believed. Dates with you turn into adventures: a spontaneous train to the coast, a festival in the rain, a debate about religion that goes on until sunrise. You love with generous, open-handed warmth and a laugh that makes people feel lucky to be near you. The trouble starts when the relationship begins to feel like a fence, and you find yourself planning solo trips or needing extra evenings out. Jealousy bores you, and possessive partners get a polite goodbye long before they realise anything was wrong. Given someone with their own horizons who does not cling, you discover that shared freedom is the richest kind of closeness.",
      "capricorn": "You approach love the way you approach anything important: carefully, and with the long game in mind. A partner of yours can wait months for a declaration, yet once it comes it is backed by a plan, a mortgage calculation and a quiet intention to stay for life. Affection shows up practically, in the car serviced before their long drive or the savings account you opened in both names. Vulnerability is harder, and you struggle to say how much someone means to you unless the moment is private and safe. Behind closed doors, though, there is an earthy, sensual side that surprises people who only know your public reserve. Partners who respect your ambition and never mock your caution meet someone devoted, steady and surprisingly romantic.",
      "aquarius": "You fall in love with someone's mind, their oddities and their opinions, long before you notice anything as ordinary as their smile. The relationships that last for you almost always begin as friendships, often ones that ran for years before either of you admitted more. Conventional romance, the roses and the anniversary dinners, leaves you faintly embarrassed, and you would rather build an unusual life together on your own terms. You need a partner with their own interests and friends, someone who does not panic when you disappear into a project for a weekend. Being told what a proper partner should do makes you bristle, and you rewrite any rulebook handed to you. Loved well, you are loyal, surprising and steady, a companion who treats the relationship as a meeting of equals.",
      "pisces": "You love as if you were reading a novel you never want to end. From the first date you can see the whole story: who they were as a child, who they could become, the life the two of you could build in a cottage by the sea. Your tenderness is real and unusual, and partners often say they have never felt so understood. A partner's bad day becomes your bad evening before a word is spoken, because their moods reach you through walls. Idealising someone is your weak spot, and it can take you a long time to accept that the person in front of you is not the one you imagined. With a partner who is kind, grounded and honest, your romantic heart feels safe enough to rest."
    }],
    ["bigThree.sun.*.work", {
      "aries": "Give you a deadline that looks impossible and something in you lights up. You are at your sharpest in the first hour of a crisis, when the plan has collapsed and someone has to make the call, and you usually make it before the meeting has finished discussing it. Roles with a scoreboard suit you: sales targets, emergency medicine, sport, trades where the job is done by nightfall, businesses you start from nothing. Hierarchies that make you wait three weeks for sign-off wear you down faster than hard work ever could. Colleagues come to rely on you to break a stalemate or deliver awkward news to a client. The cost shows in the quieter teammates who feel steamrolled by your pace, and in the resentment you feel when credit for your push goes to whoever tidied up afterwards.",
      "taurus": "Your best work has weight you can feel: a ledger that balances to the penny, a garden bed that yields in August, a chair that will outlast its maker. You are the colleague who reads the whole contract, keeps the old spreadsheet that everyone later needs, and refuses to cut the corner that would cost you in two years. Banking, cooking, building, design, land and luxury goods all reward your eye for quality and your patience with materials. Constant restructuring wears you out, and a manager who changes priorities every Monday earns your silent, lasting distrust. Money matters to you more openly than to many signs, and you are rarely embarrassed to ask what a job pays. Well rewarded and left to do things properly, your output is steady, excellent and remarkably free of drama.",
      "gemini": "You work best with three tabs open and a phone buzzing, and a job with one task all day feels like slow suffocation. Colleagues bring you the email they cannot word, the pitch that needs livening up, the client who has stopped listening to everyone else. Journalism, sales, marketing, broadcasting, social media, events and any role that sends you between people and ideas all play to your speed. You master a new system faster than the person training you and end up teaching it to the rest of the office. The weak spot is paperwork, those invoices and reports that sit half done while something shinier pulls you away. Your real value lies in being the connector, the person who knows who to ask and puts the right two people in the same room.",
      "cancer": "Any office you join slowly turns into a household: you know whose birthday is coming, who is going through a divorce, and where the good mugs are kept. Teams run warmer and more loyally around you, and people who feel lost in a big organisation drift towards your desk. Nursing, social work, catering, property, archives, heritage and family firms reward your instinct to protect and preserve. You work hardest for a boss you trust and a cause that feels personal, and you struggle in cut-throat cultures where colleagues are treated as disposable. A curt email from a manager can sit with you all weekend, rewritten in your head a dozen times. In a workplace that feels safe, you become its memory and its conscience, the one who remembers why things were done a certain way.",
      "leo": "Put you in front of a room and something switches on: your voice fills the space and people lean forward. You are drawn to work where your personal stamp shows, whether that is a stage, a classroom, a brand you built or a team you run with obvious pride. Directing, acting, events, marketing, children's work and running your own business let your natural presence earn its keep. Praise fuels you, and a boss who never says well done slowly drains your enthusiasm until you are doing the minimum. As a manager you are generous, fighting for your people's pay rises and celebrating their wins loudly. The friction comes when someone else gets credit for your idea, or when you are asked to be a grey cog in a machine that values conformity over flair.",
      "virgo": "Hand you a messy spreadsheet, a clumsy paragraph or a chaotic stockroom and you feel a quiet pleasure in setting it right. You are the one who catches the error in the budget before it goes to the board, and who has already written the checklist nobody else thought to make. Editing, accounting, nursing, pharmacy, data, quality control, nutrition and skilled trades all reward your precision. Vague briefs frustrate you, and so do colleagues who wave away details that you know will cause trouble in a month. Because you do not shout about your work, others take it for granted, and you find yourself doing two jobs for one salary. Over the years your reputation for getting things right becomes worth more than any title.",
      "libra": "You are the colleague who can walk into a tense meeting and leave it with everyone feeling heard. Clients trust you, difficult negotiations soften around you, and you have a knack for turning a complaint into a lasting client relationship. Law, design, fashion, diplomacy, recruitment, the arts and account management all suit your eye for proportion and your ease with people. Ugly surroundings and crude behaviour drain you faster than long hours, and you work noticeably better at a desk you have made pleasant. Rivalry and office politics make you uncomfortable, yet you usually understand them better than those playing hardest. Given a team of equals and a brief that asks for fairness and beauty together, your work is both elegant and quietly shrewd.",
      "scorpio": "You work best where the stakes are real and the surface is not the whole story. Give you a fraud to uncover, a patient in crisis, an archive nobody has opened in decades or a failing company to turn around, and your focus becomes almost frightening. Surgery, forensics, therapy, investment, detective work and anything involving other people's money or secrets draw you in. You keep your cards close and reveal your plans only when they are ready, which makes you a formidable negotiator. Office small talk and shallow team-building leave you cold, and being micromanaged feels like a violation. Colleagues learn that you are the one to trust with the confidential file, because what goes into your keeping never leaks.",
      "sagittarius": "You need work that feels like a bigger story, something with a mission, a horizon or at least a passport stamp. Publishing, tourism, international trade, law, broadcasting, outdoor work and academia all give your vision somewhere to land. In meetings you are the one who pitches the bold idea and fires the room up, sometimes before checking whether the budget exists. Micromanagement and endless procedures leave you visibly restless, and you push for remote days, travel or a sabbatical. Your cheerfulness keeps teams going through bad quarters, and people remember your pep talks years later. Deadlines slip when enthusiasm fades, so the jobs where you flourish are the ones that keep offering fresh ground to cover.",
      "capricorn": "You climb. Whether the ladder is corporate, academic or a small business you built from a single van, you tend to know where you stand on it and what the next rung requires. Management, finance, engineering, law, government, architecture and anything with a clear structure of rank reward your stamina and judgement. Bosses trust you with the difficult client and the budget nobody else can balance, and you rarely drop what is handed to you. You respect competence above charm and find it hard to hide your impatience with colleagues who coast. Retirement, a missed promotion or a failed venture can hit you harder than others expect, because so much of your sense of self lives at the office.",
      "aquarius": "Your best ideas arrive when you are allowed to ignore how things have always been done. You are the one who spots that the whole system could be automated, or that the charity is solving the wrong problem, and says so in the first week. Engineering, coding, campaigning, research, broadcasting and start-ups built around a big idea give your inventiveness room to breathe. Office rituals you see no reason for, the dress codes and pointless meetings, test your patience fast. You work well in networks and loose teams of equals, and badly under a boss who pulls rank. A job that serves something larger than profit earns remarkable loyalty from you, and your originality often leaves a lasting mark on the organisation.",
      "pisces": "You do your finest work when it touches something beyond the practical, whether that is a patient's fear, a piece of music or a photograph that stops people scrolling. Colleagues come to you with their troubles, and you often end up the unofficial counsellor of every team you join. Music, film, painting, nursing, therapy, charity work, pastoral care and work with animals all make use of your sensitivity. Harsh deadlines and aggressive bosses can leave you shaky for days, while a calm, kind workplace lets your talent flow. Admin is your nemesis, and you lose hours to an idea while the invoices drift. At your best you bring an intuitive intelligence that sees what the spreadsheets miss."
    }],
    ["bigThree.sun.*.shadow", {
      "aries": "When you feel cornered, your temper arrives before your thinking does. You snap at the slow driver, fire off the email you should have slept on, and slam the cupboard hard enough that everyone in the house knows. Ten minutes later you have moved on and are baffled that others are still hurt. Competition can curdle too: you turn a friendly game of tennis or a family debate into something you absolutely must win. Beneath the heat sits a raw fear of being ignored or made small, of your voice not counting. Once you notice how quickly the fire burns out, you also find you can apologise just as fast, and your apologies are wholehearted and clean.",
      "taurus": "When you feel threatened, you do not argue; you stop moving. Someone pushes you to hurry and you go very still, very polite and completely immovable, and nothing anyone says gets through. Comfort becomes a hiding place: the biscuit tin, the delivery of things you never needed, the evening lost to the sofa because getting up feels like too much. Grievances are stored rather than spoken, and a partner can be startled when you produce a slight from three years ago in perfect detail. Underneath the stillness is a fear that if you let go of anything, everything will slip. As that fear eases, your stubbornness turns back into what it was always meant to be: an unshakeable loyalty to what you know is good.",
      "gemini": "Under pressure your cleverness becomes a way of dodging. You talk fast, change the subject, tell a funny story about the problem instead of feeling it, and the people around you come away charmed but none the wiser. Small untruths slip out easily, a softened version here, a convenient excuse there, because saying the thing that smooths the moment feels harmless. Gossip can become a restless habit, passing on what you heard without quite deciding whether it was yours to share. You can end up with a dozen half-friendships and nobody who knows what you are like underneath. Behind it all sits a fear of being pinned down and found wanting, of being asked to be one thing and failing to be enough.",
      "cancer": "When you are hurt, you tend to go sideways rather than straight. Instead of saying you felt left out, you mention how nice it must have been, or you stop cooking the dish they love and wait for them to notice. Old wounds are kept in good condition, and one careless remark can open a file that dates back to school. Your care can also tighten into control: the constant checking in, the reluctance to let a grown child or partner make their own mistakes. On bad days your mood fills the house like weather, and everyone tiptoes without quite knowing why. Underneath is the dread of being left, of loving more than you are loved. Naming the hurt plainly loosens the crab's grip, and the tenderness underneath comes back.",
      "leo": "A bruised ego is the lever that tips you into your harder side. When you feel overlooked, you take over the conversation, raise the volume, or turn an ordinary disagreement into a grand drama with you as the injured hero. Admitting you were wrong feels almost physically painful, so you defend a bad decision long after everyone, including you, knows it was a mistake. There is also a quieter version: sulking in magnificent silence until someone comes to coax you back. You can give generously and then keep private count of whether the gratitude matched the gift. At the root lies a fear that without the light on you, you are nobody special. The moment you feel loved for who you are rather than what you perform, the drama falls away.",
      "virgo": "When anxiety takes over, you start tidying the world in place of feeling it. You reorganise the cupboard at eleven at night, redo someone else's work because theirs was not quite right, and correct a friend's story mid-sentence. A martyr streak creeps in too: you take on everyone's jobs, then sigh loudly enough that they know what it cost you. Health can become the focus of the worry, with every twinge researched and every meal judged. Others feel supervised rather than loved, even when your intentions are pure. Underneath lies the fear that if you stop managing the details, something will go badly wrong and it will be your fault. Once you let a thing be good enough, your warmth and humour come flooding back.",
      "libra": "Your harder side hides behind charm. You say the dinner was lovely when it was not, agree to the holiday you never wanted, and then wonder why you feel quietly furious on the beach. Anger comes out sideways: a cool tone, a late reply, a pointed compliment paid to someone else. You can also become vain about appearances, spending money you do not have to keep up a picture of the good life. When a relationship ends you tend to rush into the next, because being alone with your own company feels unbearably flat. Beneath all of it is a fear that if you show your real edges, people will stop liking you. One honest no brings enormous relief, and people respect you more for it.",
      "scorpio": "When you feel threatened, you go underground. You stop sharing, start watching, and gather information until you know more about the situation than anyone guesses. Your words can be surgical: a single sentence aimed precisely at the other person's softest spot, delivered calmly. Suspicion feeds on itself, and you check a partner's phone or set a friend a small loyalty test to see whether they fail it. Silence becomes a weapon too, and someone close to you can spend days in the freeze without being told what they did. At the core is a terror of being betrayed or seen too nakedly. Showing the wound instead of guarding it lets the people who love you finally meet the tender person underneath.",
      "sagittarius": "Your escape hatch is always within reach. A difficult conversation becomes a reason to book a flight, a hard month becomes an excuse to go out every night, and commitments get dropped with a cheerful apology. You can turn preachy, sure that your philosophy of life is the right one and puzzled that others do not see it. Exaggeration creeps into your stories until the fish was the size of a car and the job offer was nearly certain. Gambling of every kind tempts you: money, risk, the bet that something better waits just over the hill. Beneath the bravado lies a fear that ordinary life, with its bills and obligations, will slowly crush your spirit. Staying put through one dull patch and finding it bearable gives you back a surprising steadiness.",
      "capricorn": "When the pressure mounts, you armour up. Feelings get filed away as inefficient, and you meet grief or fear by working longer, sleeping less and telling everyone you are fine. You can become harshly judgemental, measuring friends and family by what they have achieved and letting disappointment show in a clipped tone. A cold certainty that things will go wrong settles in, and you call it realism. Status matters more than you like to admit, from the right postcode to the right school for the children. Beneath the control lies a fear of failure and of being exposed as not good enough. People who get past the armour find someone far warmer, funnier and more loyal than the stern exterior suggested.",
      "aquarius": "Under strain you retreat into a cool, clever distance. You explain your feelings instead of having them, and a partner in tears can find you calmly discussing the psychology of the situation. Contrariness takes over: if everyone agrees, you find the flaw in the consensus to prove you are nobody's sheep. You can become rigidly attached to your own principles, and oddly intolerant in the name of open-mindedness. Friends are held at a polite arm's length, known widely but not deeply. Beneath the detachment sits a fear of being swallowed by other people's needs, or of being told you do not belong. One person allowed to see your ordinary, messy heart is often enough to lift the loneliness behind your independence.",
      "pisces": "When the world feels too sharp, you slip away. It can be into a box set watched till three, a few more glasses than you planned, a daydream so vivid it replaces the day itself. Clear answers become hard to give, and you let people believe what they want rather than face the disappointment of a firm no. Martyrdom is a familiar costume: giving too much, then feeling quietly used and waiting for someone to notice. You drift through deadlines, promises and bills as though they belonged to someone else. Beneath it all lies a longing to be rescued from the hardness of ordinary life. Something solid, a routine, a craft, a friend who tells you the truth, lifts the fog remarkably quickly."
    }],
    ["@content.SIGNS.*.nn", {
      "aries": "Your North Node in Aries pulls you towards independence, and it asks for more nerve than you expect. The South Node in Libra is the comfort zone you are leaving: the reflex to check the room before you speak, to say \"whatever you prefer\" about the restaurant, the holiday, sometimes the whole shape of your life. You are brilliant at keeping the peace, and you know the quiet resentment that builds when everyone else's wishes have been honoured except your own. Growth arrives in small, blunt acts, like booking the class without asking anyone to come, or saying no before you have found a gracious way to phrase it. It feels selfish at first, even rude. Each time you trust your own instinct and move first, you discover that the relationships worth having survive your wanting things.",
      "taurus": "With the North Node in Taurus, you are growing towards a calmer, simpler life built on your own resources and your own sense of worth. The South Node in Scorpio is familiar ground: crisis, intensity, the late-night conversation that tears everything open, the shared finances and emotional entanglements you somehow always end up inside. You know how to survive a storm, and part of you trusts storms more than sunny weeks. Peace can feel suspiciously boring, so you go looking for the hidden problem in a perfectly good relationship. Your growth comes through the body and through patience: a savings account that grows slowly, a garden, a Sunday with nothing dramatic in it. Learning to enjoy what is solid, without testing it to destruction, is where this node leads you.",
      "gemini": "Your North Node in Gemini draws you towards curiosity, listening and the ordinary exchanges that make up a day. The South Node in Sagittarius is the comfort zone you are leaving: certainty, the big sweeping belief, the habit of delivering the answer before anyone has finished the question. You have strong convictions and a gift for the grand view, and you have probably watched a friend's face close while you explained what they ought to do. Growth looks smaller than you expect. It is the second question at dinner, the neighbour's story you properly hear, the article from a viewpoint you disagree with read to the end. Your truth stays yours, yet it becomes kinder and more accurate once it has been tested against real conversations. Being interested turns out to matter more than being right.",
      "cancer": "With the North Node in Cancer, your growth runs towards feeling, home and letting yourself be looked after. The South Node in Capricorn is the zone you know by heart: competence, control, the job title, the stiff upper lip. You are the one who organises the funeral while everyone else cries, and you are privately proud that nobody has to worry about you. That pride has a cost, because being indispensable is lonely, and achievement never quite fills the space where tenderness belongs. Growth feels exposing: admitting you are tired, staying home instead of staying late, phoning someone because you miss them rather than because something needs arranging. As you build a proper home, inside and out, success stops being a fortress and becomes something you share.",
      "leo": "Your North Node in Leo calls you out of the crowd and into the light as yourself. The South Node in Aquarius is the comfort zone you are leaving: detachment, the group, the cool observer who understands everyone and commits to nothing personal. You are at ease discussing ideas and causes, and strangely shy when someone asks what you love. You hang back in the photo, speak for \"we\" rather than \"I\", and keep your own creative work in a drawer. What moves you forward is risk that feels embarrassingly personal: singing at the party, putting your name on the project, admitting you want to be adored by the people who matter. Your heart is a better guide than your theories, and the warmth you show when you stop hiding draws people towards you rather than pushing them away.",
      "virgo": "With the North Node in Virgo, you are growing towards practical service, routine and clear boundaries. The South Node in Pisces is the comfort zone behind you: drifting, rescuing, dissolving into other people's moods or into a long bath of daydream when life gets hard. You feel everything, and you know what it is to lose a whole afternoon to vague sadness or to scrolling while the actual task waits. Compassion comes easily, yet without structure it leaks away or turns into martyrdom. Growth looks humble: a morning routine you keep, a to-do list you finish, saying \"I can help on Tuesday for an hour\" instead of offering everything. When your sensitivity is given a shape, it turns into help that people can hold in their hands.",
      "libra": "Your North Node in Libra points you towards partnership, cooperation and the art of considering someone else. The South Node in Aries is the zone you are leaving: self-reliance, speed, the impulse to do it alone because waiting for others feels unbearable. You are brave, direct and quick to act, and you know the aftermath of acting too quickly, the text sent in heat, the decision made before your partner had a say. Asking for input feels like weakness, and compromise like defeat. Growth arrives through the pause: hearing the other person out, choosing the restaurant together, letting a relationship change you. You discover who you are through the mirror of others, and your courage becomes more useful once it is aimed at fairness rather than at winning.",
      "scorpio": "With the North Node in Scorpio, your growth leads into depth, intimacy and change. The South Node in Taurus is your comfort zone: security, possessions, routine, the same job and the same sofa because they are reliable. You are steady and loyal, and you can hold on to a situation for years after it has stopped feeding you, because leaving feels expensive. Letting another person in, with shared money, shared secrets and shared risk, frightens you more than you admit. Growth comes when you allow something to end: the relationship that is only comfortable, the belief that stuff equals safety. Each time you let an old structure die and merge honestly with someone, you find a power in yourself that no amount of stability could have given you.",
      "sagittarius": "Your North Node in Sagittarius draws you towards faith, meaning and a truth you live by. The South Node in Gemini is the comfort zone you are leaving: chatter, research, forty open tabs and the nagging need to gather one more opinion before you decide. You are quick and clever, and you can argue any side, which is why you sometimes cannot find your own. Second-guessing wears you out, and you know the feeling of knowing a lot while trusting very little. Life opens up when you close the tabs and follow a hunch, take the long trip, sign up for the philosophy course, or say what you believe without footnotes. Your intuition turns out to be wiser than your information, and living by it gives your life a direction that facts never supplied.",
      "capricorn": "With the North Node in Capricorn, you are growing towards maturity, responsibility and a place in the wider world. The South Node in Cancer is the comfort zone you know: family, emotional safety, the familiar kitchen and the people who have always looked after you, or whom you have always looked after. You are caring and attuned to moods, and you know how easy it is to let feelings decide, to stay small because the outside world seems harsh. Setting a goal and sticking to it through discomfort feels unnatural, even cold. Growth arrives through commitment: applying for the role, making a five-year plan, being the one others turn to for a decision. Your warmth does not disappear as you step up; it becomes the quality that makes your authority humane.",
      "aquarius": "Your North Node in Aquarius leads you towards friendship, teamwork and a vision bigger than your own story. The South Node in Leo is the comfort zone you are leaving: applause, personal drama, the need to be the special one in the room. You have warmth and creative spark, and you know the sting when a group project succeeds without your name on it, or when a friend's news pulls the spotlight away. The pull towards being admired is strong and a little lonely. Growth comes through shared effort: the community garden, the collective, the friendship that asks nothing of your ego. Once your gifts are placed in service of something larger, you discover a freedom that applause never gave you, and the people around you feel like equals rather than an audience.",
      "pisces": "With the North Node in Pisces, your growth runs towards surrender, compassion and trust in something larger than your plans. The South Node in Virgo is the comfort zone behind you: perfectionism, worry, control, the spreadsheet for the holiday and the hours lying awake running through everything that could go wrong. You are skilled, useful and precise, and you know how exhausting it is to believe that if you stop managing, everything falls apart. Criticism, of yourself first, is your default setting. Freedom begins when you let go: the unplanned afternoon, the painting that is allowed to be messy, the prayer or meditation that achieves nothing measurable. Your imagination and your spirit need room to breathe, and life often arranges itself better than your list would have."
    }],
    ["@content.SIGNS.*.chiron", {
      "aries": "With Chiron in Aries, the old wound sits around your right to exist, want and take up space. Somewhere early you learned that anger was dangerous or that putting yourself first made you bad, and the result is a strange hesitation at the very moment you need to act. You apologise before asking a question, you let someone cut in the queue and fume all the way home. At other times the suppressed fire bursts out too hard, and you feel ashamed of it afterwards. Courage learned the slow way is what heals you. Because you know how it feels to shrink, you become the person who gives others permission to stand up, speak first and claim their place, and in doing so you finally claim your own.",
      "taurus": "Chiron in Taurus places your wound around worth, security and the body. You carry a quiet feeling that there is never quite enough: money, time, comfort, or your own value in someone else's eyes. You check the bank balance more often than you need to, feel uneasy when you own a lovely thing, or overwork to prove you deserve your place. The body can feel like something to manage rather than something to enjoy. This wound runs deep because it touches the ground you stand on. Healing arrives as you learn that your value is inherent, not earned, and live it in small ways: the good meal eaten slowly, the rest taken without guilt. From there you help others feel safe in their own skin.",
      "gemini": "With Chiron in Gemini, the wound sits around being heard and understood. Early on you learned that your ideas were silly, your questions annoying, or your way of speaking wrong, and part of you still rehearses sentences before saying them. You reread emails three times, go quiet in a lively debate, or talk too fast to get it all out before someone interrupts. Learning can feel loaded, as if one wrong answer would expose you. The pain here is sharp, because words are how you reach people. The healing gift is extraordinary: you become a translator, the person who explains the complicated thing gently, who notices the quiet one at the table and draws them out, because you remember how silence felt.",
      "cancer": "Chiron in Cancer places the old wound in family, belonging and being cared for. Something in your early home left you feeling unheld: a parent who was absent, overwhelmed or unable to show tenderness, or a household where you became the carer too soon. You know the ache of a holiday at someone else's family table, and the reflex to mother everyone while nobody thinks to ask how you are. Letting yourself be nurtured feels awkward, even suspicious. This wound shapes how you build every home. Your healing unfolds as you become the nurturer you once needed, and also allow yourself to receive: the friend who cooks for you, the partner who sits with your tears, until care flows both ways.",
      "leo": "With Chiron in Leo, the wound sits around being seen, celebrated and allowed to shine. Your joy was too loud for the household, your creativity was brushed aside, or attention went to a sibling while you learned to be the easy child. Now you downplay your achievements, deflect compliments with a joke, and feel oddly exposed on your birthday. Part of you longs for applause and part of you is ashamed of that longing. When you do take the stage, a voice whispers that you are showing off. What heals you is a generous heart for other people's light: you are the one who cheers loudest, who spots hidden talent and helps others shine without apology, and in that warmth your own playfulness returns.",
      "virgo": "Chiron in Virgo places your wound around never being good enough. A critical voice runs in the background, about your body, your work or your usefulness, and it rarely switches off. You redo the report at midnight, notice the one flaw in an otherwise lovely day, and feel strangely guilty when resting. Health and routine can become sources of anxiety rather than comfort, and you know how quickly helpfulness turns into proving your worth. The hurt is quiet, and others often mistake it for high standards. Healing lies in learning self-acceptance and then teaching it: you become the colleague, healer or friend who meets imperfection with patience, because you understand from the inside how cruel perfectionism can be.",
      "libra": "With Chiron in Libra, the old wound lives in relationship. You have known imbalance: loving more than you were loved, being left, or losing yourself so completely in a partner that you forgot your own preferences. You keep the peace at any price, over-give in friendships, and feel a jolt of panic when someone is displeased with you. Being alone can feel like proof that something is wrong with you, and fairness becomes a sore point you notice everywhere. This wound makes every partnership feel like a test. Out of it grows a rare understanding of what equal connection requires, and you help others find it, as the mediator, counsellor or friend who sees both sides without disappearing into either.",
      "scorpio": "Chiron in Scorpio places the wound in intimacy, trust and power. You met betrayal, loss or control early or deeply, and it taught you to watch closely and let very few people in. You test partners without meaning to, read hidden motives into ordinary texts, and keep a secret or two in reserve just in case. Vulnerability feels like handing someone a weapon. Yet you also know how to survive what breaks other people, and you do not flinch from grief, sex, money or death. The healing gift comes as you accompany others through their own dark nights: at the hospital bed, in the therapy room, on the late phone call, you are steady because you have already been there.",
      "sagittarius": "With Chiron in Sagittarius, the wound sits around belief, meaning and purpose. Faith was forced on you, broken, or never offered at all, and you have felt that hollow question of what any of it is for. You swing between searching intensely, through books, travel and teachers, and dismissing all of it as naive. Education or foreign places can carry an old hurt, a sense of being judged ignorant or of not belonging. You know how lonely it is to have no map. Your healing is a spacious wisdom earned through doubt: you help others find their own truth rather than borrowing yours, and your teaching is honest precisely because you never pretend a certainty you do not feel.",
      "capricorn": "Chiron in Capricorn places your wound around authority, achievement and the father or father figure. You grew up feeling that nothing was ever enough: the good grade met with a question about the missed marks, the success that earned no warmth. Now you push hard, distrust bosses, and feel either crushed or defiant whenever someone judges your work. Resting feels like failure and praise slides off you. Responsibility arrived too early, and you still carry more than your share. Your medicine is to become the authority you never had: wise, humane, firm without cruelty. As a manager, parent or mentor, you give others the recognition you once waited for, and some of it lands on you too.",
      "aquarius": "With Chiron in Aquarius, the wound sits around belonging. You have felt like the outsider, the odd one, the alien who landed in the wrong family or the wrong school. You know the moment of standing at the edge of a group, laughing a beat late, unsure whether to try harder or leave. Sometimes you make a virtue of being different so nobody can reject you first. Friendships can feel precarious even when they are solid. The healing gift is a talent for community: you build the space where misfits are welcome, the group chat, the club, the cause, and you make the newcomer feel at home, because nobody understands better than you what it costs never to quite fit.",
      "pisces": "Chiron in Pisces places your wound in the spiritual and existential realm. You carry a boundless sensitivity, a porous skin that absorbs other people's pain, and an old sense of loss or longing for something you cannot name. Crowds exhaust you, sad films undo you for days, and there are times you reach for escape, sleep, a drink or endless scrolling, just to switch the feeling off. Boundaries are hard because you feel what everyone feels. Your openness has no natural off switch, and that is its real cost. Healing comes through compassion, art and spiritual practice: in music, prayer, painting or care work you turn that permeability into something that soothes others, and discover the longing was a connection all along."
    }],
    ["@content.MOON_PHASES.*.desc", {
      "0": "Being born at the new moon gives you an instinctive, subjective and future-oriented nature. You act first and understand later, launching into a new job or a new city because it feels right, with very little sense of how it looks from outside. Other people's reactions often surprise you, since you were following an inner push. You are here to start something new and to project yourself into life, and you do it best without too much planning. The difficulty is that you can miss what others see plainly, and your enthusiasm outruns the practical detail. Still, you carry a fresh, seed-like energy that sets things in motion, and people around you feel more alive when you arrive with a new idea.",
      "1": "Being born in the crescent phase gives you a struggle-and-build energy. You push forward against the pull of the past, whether that is a family expectation, an old habit or a voice saying you should stay where you are. Every step you take feels earned, as if you are carving a path through thick undergrowth. You are the one who retrains at forty, moves away from the hometown, or keeps going after the first three rejections. Frustration comes easily, because the old ways drag at your ankles and progress feels slower than it should. What you build, you build with determination, and the effort gives it roots. By the end you have created something that is unmistakably yours.",
      "2": "Born at the first quarter, you have a crisis-in-action personality. You thrive when something is at stake: the deadline, the renovation that goes wrong, the team that needs rescuing. Calm stretches make you restless, and some part of you seeks out a challenge just to feel your strength. You clear away what no longer works and put up strong structures in its place, often faster than others are ready for. The shadow is a life that lurches from one battle to the next, with little time to enjoy what you have built. At your best you are decisive and brave, the person who turns a vague plan into walls, a roof and a door that opens.",
      "3": "Born in the gibbous phase, you are a refiner and an analyst, driven to perfect things and to find what they mean. You are rarely satisfied with a first draft; you tweak the presentation until the small hours, reread the contract, and ask why before you ask how. Growth for you is a process of adjustment, learning from each attempt and getting closer to something that feels right. You care about doing it properly and about doing it for a reason. Perfection keeps moving, though, and you can delay the finish while polishing forever. When you trust the work enough to release it, your careful preparation gives everything you touch a depth and quality others notice at once.",
      "4": "Born at the full moon, you are relationship-oriented and highly aware. You see yourself most clearly through other people: the partner who reflects you, the friend who says what you already half knew. Your life moves through illumination, the moment when a situation makes sense and you understand what you have been working towards. You feel pulled between opposites, independence and togetherness, head and heart, and you often live both in quick succession. Relationships bring your purpose to fulfilment, yet they also expose every inner contradiction, and the tension can leave you swinging between extremes. Your objectivity is the reward: you see what is happening between people, and your awareness brings clarity to everyone around you.",
      "5": "Born in the disseminating phase, you are a teacher and communicator at heart, someone who needs to share what has been learned. Experience does not feel complete until you have passed it on, so you explain the recipe, recommend the book, or turn a hard year into a talk or a long letter. You like ideas that have been tested in real life, and you have little patience for theory that never touches the ground. People come to you for perspective and you hand it out generously. The risk is preaching, or assuming that what worked for you will work for everyone. When you share rather than instruct, your voice spreads meaning far beyond your own circle.",
      "6": "Born at the last quarter, you have a crisis-in-consciousness personality. Your life keeps asking you to reorient your values: to see that an old belief, job or loyalty no longer fits, and to act on that inner shift even when the outer world has not caught up. You are the one who leaves the organisation you helped build, or changes your mind in public because you have outgrown a view. The change you lead is subtle, more a turn of direction than a revolution. You stand between past and future, and that position can feel lonely. Still, your honest reassessment of what matters gives others the courage to reconsider their own paths.",
      "7": "Born in the balsamic phase, you carry a prophetic, old-soul energy, and this is often considered a karmic birth. You feel like the last chapter of something and the first seed of what comes next at the same moment. You finish what others abandoned, tie up family stories, and sense changes long before they arrive, sometimes as a dream or an unexplained certainty. Solitude feeds you, and crowds leave you tired and slightly out of time. The difficulty is a feeling of not quite belonging to the present, of waiting for a world that has not yet appeared. Your purpose is to complete cycles and prepare the seeds of the future, and that quiet work shapes more than people realise."
    }],
    ["@content.RETRO_KARMIC", {
      "mercury": "Having Mercury retrograde in your birth chart turns your thinking inwards. You process everything internally first, so you are often the quiet one in the meeting who has the best idea three days later, in the shower or on a walk. Ideas mature slowly in you, but they mature deeply, and your conclusions are rarely borrowed. Karmically, you are revisiting how you speak truth: whether to say what you think or what is expected. You know the frustration of words arriving late, and of being misread as slow when you are thorough. Writing often suits you better than speech, since it gives your mind room to circle back. When you do speak, it carries the weight of reflection.",
      "venus": "With Venus retrograde in your birth chart, love and values are re-examined from the inside. You do not take the usual scripts about romance, beauty or money at face value; you test them against your own private sense of what is worth anything. Relationships often feel karmic, with an uncanny sense of recognition, or with old patterns repeating until you finally see them. You know the moment of standing in a lovely life and wondering whether you want it. Receiving affection can feel awkward, as if you must first earn it. Your standards of beauty and worth run old and deep, and once you trust them, your loves become more honest and more your own.",
      "mars": "Mars retrograde in your birth chart turns drive and anger inwards. Instead of snapping in the moment, you replay the argument for days, and frustration shows up as a sleepless night or sudden bursts of energy that come out of nowhere. Acting on desire feels complicated; you hesitate at the start, then work with fierce persistence once you commit. Karmically, you are relearning how to act on what you want without repeating past-life battles, the same fight, the same wounded pride. You know the sting of watching others grab what you were too slow to claim. Over time you develop a strategic, self-aware kind of courage, one that chooses its battles instead of being chosen by them.",
      "jupiter": "Jupiter retrograde in your birth chart makes your faith personal rather than borrowed. You were never going to accept a belief because a parent, teacher or tradition handed it to you; you needed to test it against your own experience first. You sit through the sermon or the lecture forming your own view, and luck often arrives through private insight rather than outer good fortune. Growth happens inwardly before it shows. There is a lingering sense that others were given confidence and meaning you had to build alone. That is also your strength: you grow by developing your own philosophy, and the wisdom you end up with is authentic, earned and hard to shake.",
      "saturn": "When Saturn is retrograde in your birth chart, you are your own harshest authority. Nobody could criticise you as thoroughly as you already do, and you set yourself rules and standards that outside figures never demanded. Karmic duties feel internal: a sense of owing something, of needing to prove you have learned a lesson from long ago. You know the late night going over a small mistake, or the refusal to rest until everything is flawless. Praise from others barely registers, because the real judge lives inside. The burden is heavy, and it can make you older than your years. Yet your mastery comes through self-discipline rather than outside approval, and that makes it yours alone.",
      "uranus": "Uranus retrograde in your birth chart makes your rebellion inner and quiet. You look conventional enough from the outside, with a normal job and ordinary clothes, while your mind runs on thoroughly unorthodox ideas. Freedom, for you, is found through inner awakening: sudden realisations that change how you see your life overnight, even if nobody else notices. You break patterns privately first, questioning a family rule or a social expectation long before you act on it. Your originality can stay hidden for years, and you feel restless in a life that no longer matches who you have become inside. When the inner shift reaches the surface, it changes things for good.",
      "neptune": "Neptune retrograde in your birth chart turns your spiritual sensitivity inwards. You live with strong inner visions: vivid dreams, flashes of intuition, a sense of something sacred behind ordinary life that you rarely talk about. Collective fantasies, the glossy advert or the charismatic leader, leave you cold or suspicious, because your radar for illusion is sharp. Still, you can deceive yourself more easily than others deceive you, clinging to a private ideal of a person or a future. There is a pressing need to discern what is true from what you wish were true. When you honour your inner world through art, prayer or solitude, your imagination becomes a reliable guide.",
      "pluto": "With Pluto retrograde in your birth chart, transformation happens deep inside, often unseen. You go through quiet endings and rebirths, a belief that dies, a fear that loses its grip, while from the outside your life looks unchanged. You are revisiting old themes of power and control from a past cycle, and you notice them keenly: who holds the power in a room, who is being manipulated, when you yourself are tempted to control. You know the heaviness of carrying intensity that has nowhere to go. Obsessions can circle for years before releasing. The reward is profound self-knowledge and a power over your own psyche that very few people ever reach.",
      "chiron": "Chiron retrograde in your birth chart means your old wound is worked through privately. You rarely talk about the hurt, and you would rather sit with it alone at night than have it discussed at dinner. Friends often have no idea how much you are carrying, which protects you and also isolates you. Healing is found by looking within, through reflection, journaling, therapy or long walks where a memory loosens its hold. Outside help matters less than your own slow understanding of what happened and why. Over time you become a quiet healer, someone whose empathy comes from knowledge earned in private rather than lessons learned from books."
    }],
    ["@content.HOUSE_NODE", {
      "1": "You introduce yourself at parties through someone else: whose partner you are, whose friend, whose colleague. With the North Node in your first house, life keeps steering you back to the plain fact of your own presence: your body, your look, your appetite, the way you walk into a room before anyone has vouched for you. The South Node in the seventh leaves you a gift for diplomacy, and you never lose it; it stops being the whole of you. A solo trip, a haircut chosen for nobody else, an argument you refuse to back down from, all feel frightening and then oddly exhilarating. Around the ages of 19, 37 and 56, events push you to stand on your own feet. Each time, the self you meet is sturdier than you expected.",
      "2": "Naming your own price is where this placement bites: the invoice you undercharge, the pay rise you never request, the moment you apologise for wanting something nice. With the North Node in the second house, your task is to know what you are worth in plain numbers and plain values. The eighth-house South Node gives you a sharp eye for hidden motives and other people's money, so you read the power dynamics in a room within seconds. That talent counts, yet it keeps your attention on everyone else's accounts instead of your own. Owning things you chose, trusting your body's appetites and earning by your own effort gradually build a self-respect nobody can remove. You become someone whose calm is contagious, because it rests on ground you laid yourself.",
      "3": "Your messages turn into essays, and a simple question from a friend gets a lecture on the meaning of life. With the North Node in the third house, the skill you are here to build is plain, quick, two-way communication: the note that says what it means, the explanation a ten-year-old could follow. The ninth-house South Node leaves you well travelled in mind if not in miles, with a natural feel for belief, law and the big picture. Distance is your old refuge, and booking a flight comes easier than fixing a misunderstanding across the road. Writing, teaching the basics, driving the same streets until you know every shop: all of it grounds you. Your ideas gain force once they are shaped for the people you talk to every day.",
      "4": "Asked how you are, you answer with a work update, and it takes a close friend to notice you never mentioned how you feel. The North Node in your fourth house turns you towards the private self: your roots, your ancestry, the emotional weather you inherited from your parents. The tenth-house South Node made you the responsible one early, the child who seemed older than their years and the adult who is admired rather than known. Old family material resurfaces throughout your life, often around a parent's ageing or a return to the town you grew up in. Crying in front of someone, asking for comfort, letting a room stay messy for a week: these carry more weight for you than any award. The second half of life often brings the belonging you went without in the first.",
      "5": "You describe a crush as \"interesting\" and a holiday as \"useful for recharging\", as though pleasure needed a sensible excuse. The North Node in your fifth house asks for delight taken straight: the game played to win, the love letter sent, the outfit worn purely because it makes you happy. From the eleventh-house South Node you carry a wide network, a knack for seeing the bigger social pattern and a cool head that friends rely on. That same coolness keeps you on the edge of the dance floor, rating the evening instead of having it. Each time you risk looking silly for something you love, you gain a warmth that no amount of fitting in ever gave you. People remember you for your spark once you stop rationing it.",
      "6": "You wait for the right mood before starting anything, and the mood arrives most reliably ten minutes before a deadline. With the North Node in your sixth house, your life improves through craft: learning a job so thoroughly that your hands know it, becoming the colleague whose work never needs checking. The twelfth-house South Node gives you a deep reservoir of empathy and an instinct for what is left unsaid, along with a pull towards martyrdom and waiting to be rescued. You have probably spent whole spells believing that something mystical would sort everything out on its own. Workplaces, pets and a body that responds to care all teach you that devotion shows in the detail. Your compassion becomes something people can lean on once it arrives on time.",
      "7": "You walk half a step ahead of whoever you are with, and you win the argument while losing the evening. The North Node in your seventh house brings your lessons through other people: partners, clients, rivals, anyone who meets you as an equal and will not follow. From the first-house South Node you carry courage, a strong sense of who you are and the ability to start from nothing. Those strengths are already yours, which is why they no longer stretch you. Contracts, business partnerships and marriages arrive at the turning points of your life and change its direction. The version of you worth becoming holds a strong self and a fair compromise in the same hand.",
      "8": "You insist on splitting the bill to the penny and would rather go without than borrow, even from someone who loves you. With the North Node in the eighth house, your growth runs through what you cannot own outright: joint money, other people's trust, desire, and the crises that remake a life. The second-house South Node gives you steady nerves, practical sense and a talent for building comfort from very little. Its weakness is a stubborn self-sufficiency that treats every merger as a threat. Your biggest turning points arrive through events you could not stop, a redundancy, a loss, a sudden intimacy, and each one leaves you more powerful than before. Psychology, finance and healing work often draw you, because you understand from the inside how people rebuild.",
      "9": "You can argue both sides of anything so well that friends are rarely sure which one you believe. The North Node in your ninth house asks you to land somewhere: to hold a conviction, teach it, publish it and stand by it when challenged. The third-house South Node leaves you quick-witted, well informed and at ease with siblings, neighbours and all the small traffic of daily life. It also keeps forty tabs open on your screen and a reflex for checking one more source before committing. Faith, in whatever form suits you, grows from lived experience far more than from further reading. Late study, a move abroad or a teaching role often arrives when you least expect it and gives your life its larger shape.",
      "10": "You let a colleague present the idea you had, then feel a quiet sting when the room praises them. With the North Node in the tenth house, you are here to be seen doing something that matters and to accept the authority that comes with it. The fourth-house South Node gives you emotional intelligence, deep loyalty to your family and an instinct for making any space feel safe. It also carries a habit of hiding behind the household, or waiting until everyone at home is settled before you begin. Old voices from childhood, warning you not to get above yourself, can sound louder than your own ambition. Over the years you grow into an elder figure others look up to, one who leads with the warmth you learned at home.",
      "11": "You check who has seen your story, and a group project that credits everyone equally leaves you faintly deflated. The North Node in your eleventh house points you towards the future and the network: friends from every walk of life, collaborators, and ideas bigger than any single ego, yours included. From the fifth-house South Node you carry charisma, creative confidence and a big heart that loves being loved. Its snag is taking things personally, so a friend's busy week reads as rejection. Your hopes and long-term plans grow clearer every time you invest in people who will still be around in twenty years. A life anchored in good friendships and shared goals turns out far freer than the stage ever was.",
      "12": "Grief sends you straight to the cupboards, reorganising tins when what you need is a long cry. The North Node in your twelfth house leads you into what cannot be fixed: loss, mystery, forgiveness, and the part of you that knows things without evidence. The sixth-house South Node leaves you capable, precise and quick to spot a flaw, whether in a spreadsheet or in your own body at two in the morning. Criticism, of yourself first, is the old habit that keeps you tight. Charities, hospitals, music and quiet places of worship often become part of your story, sometimes in ways you never planned. Your deepest ease arrives when you stop managing your inner life and let it speak."
    }],
    ["@content.PATTERNS.*.desc", {
      "grandTrine": "Some things in your life have always worked: a talent you never trained, a way with people, a luck that seems to follow you around. A Grand Trine links three planets in a closed loop of easy harmony, usually within one element, and it hands you a gift so natural you barely notice you have it. Friends marvel at what you do effortlessly while you shrug it off. The catch is comfort, since energy that flows in a circle has no reason to leave it, and you can coast for years on ability you never put to work. Tougher aspects elsewhere in your chart supply the friction a trine lacks, and they are what set it moving. Once you aim this ease at something demanding, it becomes the source of your best achievements.",
      "tSquare": "Pressure is a familiar companion, and you often do your best work with the clock running down and something at stake. In a T-Square, two planets pull against each other while both press on a third, the apex, and that planet shows where the strain collects and where you are driven to act. You feel the tension as restlessness, a push to fix, prove or resolve something that never quite settles. It gives you tremendous drive and a stubborn refusal to give up. It also produces cycles of overreaction, when all the force pours into the apex and you burn out. The empty point opposite the apex describes the missing ingredient, and your life steadies as that quality grows in you. Your hardest-won achievements come straight out of this shape.",
      "grandCross": "Your life has rarely offered one simple problem at a time; demands arrive from four directions at once. A Grand Cross locks four planets into two oppositions and four squares, so every move you make in one area tugs on another. You know the feeling of fixing your finances just as your relationship needs attention and your health calls in its debts. People describe you as unshakeable, and they are right, because you have learned to stand in the middle of competing pulls without falling over. The cost is fatigue and a sense of being stuck, since the forces cancel each other as often as they propel you. Stamina is what this pattern builds: over time you become someone who can carry a great deal and still move forward.",
      "yod": "You have long felt that you are here for something specific, even when you cannot name it, and ordinary paths never quite fit. A Yod joins two planets in a supportive sextile that both point, awkwardly, at a third, the apex, and that planet carries a sense of calling mixed with discomfort. Life keeps asking you to adjust: a career that swerves, a move you did not plan, a role you never applied for that suits you uncannily well. The strain shows up as feeling out of step with everyone, or as nervous tension whenever you resist the turn. Tradition calls this the Finger of God, and people with it often find their purpose late and suddenly. When the apex finds its outlet, the odd twists of your story begin to make sense.",
      "stellium": "A large share of your chart sits in one place, and people meet that area of life in you before anything else. Three or more planets gathered in a single sign or house give you focus and depth there: you know that subject inside out, you return to it again and again, and it shapes your choices more than any other theme. Friends see you as the career one, the family one or the artist, depending on where the cluster falls. The intensity is a strength, producing expertise and a strong personal signature. It also creates blind spots, since the rest of life can feel pale or neglected by comparison. You feel most whole when that concentrated energy has a worthy channel and the emptier parts of your chart get some of your attention too."
    }],
    ["nodeAxes.*.trap", {
      "aries": "The comfort zone looks lovely from outside: a calm household, a partner who never has to argue, friends who call you the easiest person they know. Inside it, you spend twenty minutes composing a message so it cannot offend, and you go along with the film, the restaurant and the holiday you would never have chosen. Resentment builds quietly, then leaks out as sarcasm or a sudden cold withdrawal that baffles everyone. You drift into relationships where your role is to reflect the other person, and they grow while you wait. Fairness becomes a way to postpone every choice indefinitely. The longer this lasts, the more your energy drains away, until even getting out of bed feels like someone else's decision.",
      "taurus": "When life goes quiet for too long, you start poking at it: reading a partner's pause as a secret, turning a small disagreement into a showdown at midnight. Calm makes you uneasy, so you find the wound in things that are fine. You get pulled into other people's debts, affairs and emergencies, becoming the confidant who knows everything and owns nothing. Power struggles feel more alive than contentment, and you stay in bonds that run on jealousy or intensity. Spending other people's money, or letting them spend yours, keeps you tied up in knots. Afterwards you are exhausted, with the sense of having lived through a storm you partly summoned.",
      "gemini": "Certainty is the comfortable armchair here: you know what you think, you know what everyone else ought to think, and you are ready to explain it at length over dinner. You finish other people's sentences, usually with a larger point than the one they were making. Plans stay grand and vague, a year abroad, a book, a new philosophy of life, while the tax return and the promised phone call wait. When bored, you leave, for another country, another course or another belief system. Advice flows from you far more readily than enquiry. Eventually friends stop telling you things, and you mistake their silence for agreement.",
      "cancer": "You retreat into the office, figuratively or literally, the moment something tender is asked of you. When a friend cries, you offer a plan; when your own chest tightens, you answer three more emails. Titles, targets and the respect of people you barely like feel safer than the messy warmth of people who love you. You parent everyone, including your own parents, and then feel oddly alone at your own birthday dinner. Holidays are scheduled carefully and then worked through. Over time the armour thickens, and those close to you learn to admire you from a slight distance instead of reaching for you.",
      "leo": "You are brilliant at the party from the corner, making wry comments about everyone else's performance. Detachment feels like freedom, and you call it being rational when it is a way of never risking your heart. You pour energy into a cause, a network or a clever theory, and your own dreams stay filed under later. Compliments make you deflect with a joke or a mention of the team. Romance stays at the level of intriguing friendship, and you break it off when feelings get too warm. Life becomes interesting rather than joyful, and you can look back on a whole year without one moment when you felt lit up.",
      "virgo": "You float, and it feels like peace until the post piles up behind the door. The days blur into one another with no structure, and you let the sofa, the phone or a glass of wine absorb the evenings. Someone in trouble always seems to find you, and you give far more than you have, then resent them for taking it. You wait for a sign, a rescuer or a stroke of fate to sort out what a single phone call could fix. Vague aches and low moods become the backdrop of life, with no clear cause and no clear end. The longer you drift, the more helpless you feel, even though your capacity is enormous.",
      "libra": "You are already out of the door while everyone else is still discussing the plan. Going solo feels clean, so you reach for independence whenever a relationship asks you to wait, bend or explain yourself. Arguments become contests, and you would rather be right than close. You start things with gusto, then quit when they need somebody else's input to continue. Impatience makes you blunt in ways you only notice afterwards, when the other person has gone quiet. The result is a life full of beginnings and victories with oddly few witnesses, and a loneliness you describe as liking your own company.",
      "scorpio": "You settle into a routine so snug that nothing can reach you: the same meals, the same route, the same polite distance with the person you share a bed with. Change arrives and you dig in your heels, holding on to a job, a house or a relationship long after it stopped feeding you. Buying something comforting is easier than feeling something uncomfortable. Money becomes a fortress, and you keep a private tally of what is yours. When a conversation turns deep, you change the subject or reach for another biscuit. Life stays pleasant, predictable and oddly flat, as though you were watching it through a window.",
      "sagittarius": "Your phone is where you hide: one more article, one more message thread, one more podcast about something you will never do. You know a little about everything and commit to nothing, keeping options open until they close on their own. In conversation you mirror whoever is in front of you, so different friends hold different versions of your opinions. Small errands swallow whole weeks, and you feel busy without ever feeling fulfilled. Gossip gives you a quick rush of connection that leaves you slightly grubby afterwards. Beneath the chatter sits a restlessness, a sense that the real journey is happening somewhere else without you.",
      "capricorn": "The nest is warm, and you know every corner of it. You turn down the opportunity in another city because your family would miss you, and you tell yourself it was a free choice. Moods run the day: a sharp word from someone at work can send you home to hide under a blanket. You look after everyone's feelings with great skill, and nobody quite takes you seriously as the one in charge. Nostalgia pulls hard, and old photographs feel more real than the future. Years go by in which you are loved and needed, yet something in you wonders what you could have built.",
      "aquarius": "Every room becomes a stage, and you notice at once when the attention drifts to someone else. A friend's news turns into a story about you within two sentences, less out of vanity than habit. You take a delayed reply as a verdict on your worth and spend the evening replaying it. Criticism feels like an attack on your whole self, so you defend rather than listen. Romance offers the reliable adoration you crave, and you can cycle through affairs that feel thrilling and leave little behind. Beneath the glow sits a tiring need to be special, and a fear of what you are without the applause.",
      "pisces": "The to-do list is your comfort blanket, and you feel safest with a task in your hand and a flaw to correct. You rewrite an email five times, notice the typo on the restaurant menu, and lie awake running through what could still go wrong tomorrow. Helping becomes a way of controlling, and you hover over other people's work until they give up and let you do it. Your body carries the strain as tight shoulders, a restless stomach and sleep that never quite refreshes. Pleasure has to be justified by productivity first. In the end, a life of careful management leaves very little room for grace."
    }],
    ["nodeAxes.*.medicine", {
      "aries": "Anger, surprisingly, is often what brings you home: a flash of it, felt fully, tells you where you stand. You come back to yourself in moments of physical effort, the last stretch of a run, the lift that is slightly too heavy, the sea on a cold morning. Emergencies help too, since you act before you have time to consult anyone and discover you were right. A new beginning, a job started from scratch or a city where nobody knows you, strips away the habit of performing agreeableness. Being called selfish once, and surviving it, frees something in you. What returns each time is a clear sense of want, and the people worth keeping welcome it.",
      "taurus": "The body is the fastest route back for you: a hot bath, bread straight from the oven, bare feet on cool grass, the heavy tiredness after a day of physical work. Your own money in your own account, however modest, calms something that no reassurance can. Seasons help as well, and watching a garden move from bulbs to blossom teaches you that good things arrive slowly and stay. You settle when someone steady and uncomplicated shows up, a friend who is who they seem. Music, touch and good food ground your intensity into sensual pleasure. Once you feel your feet again, the drama in other lives loses its grip and your own life feels rich enough.",
      "gemini": "What pulls you back is the moment someone surprises you: a fact that overturns your theory, a teenager who explains something better than you could, a stranger on a train with an entirely different life. You come alive in exchange, the conversation that goes somewhere neither of you expected. Getting lost in a neighbourhood you thought you knew, reading a local paper, overhearing a funny exchange in a café: all of it restores your curiosity. Being corrected, gracefully and in public, humbles you in a way that feels unexpectedly light. A sibling or old school friend often knows how to puncture your grandeur with a single joke. After that, questions come more easily than sermons.",
      "cancer": "A child's hand slipping into yours, a grandmother's recipe, the smell of your childhood kitchen: small domestic moments undo you in the best way. Illness or exhaustion sometimes forces the return, when you have no choice but to be looked after and find it bearable, even sweet. Water calls you back too, the sea, a river walk, a long bath with the door locked. You find your way when someone asks how you feel and waits long enough for the real answer. Coming home, whether to a place, a person or a family ritual, reminds you that you belong without earning it. Tears, once they arrive, leave you lighter and more yourself than any accomplishment does.",
      "leo": "Being delighted by something brings you straight back: a song that makes you dance in the kitchen, a love affair that knocks the irony out of you. Children, pets and anyone who adores you without reservation melt the cool reserve you hide behind. Moments on a stage of any kind, a toast at a wedding, a performance, a piece of work with your name on it, awaken a pride that feels right rather than vain. You return when someone insists on celebrating you and you let them. Falling in love, with a person, an art form or a place, restores your warmth faster than any insight. Your heart, once it is open, knows the way on its own.",
      "virgo": "The satisfaction of a finished task pulls you back more reliably than any insight. You feel it when a drawer is sorted, a form sent off, a meal cooked from scratch on a weekday. Useful work steadies you, particularly work where your care for people turns into specific, measurable help: the shift covered, the report done properly, the dog walked. Your body responds quickly to regular hours, and after a week of steady sleep and plain food your mood lifts noticeably. Colleagues and clients who rely on you give your sensitivity a shape. Clarity returns in these ordinary moments, and with it the sense that you are the one steering.",
      "libra": "Someone who stands up to you calmly, without backing down or fighting back, stops you in your tracks and brings you home. You find the thread again through beauty: a concert, a well-designed room, a painting that slows your breathing. Partnerships that work, even briefly, show you how much stronger the two of you are than you alone. The relief of a compromise that suits you both surprises you every time. A gracious remark that defuses an argument earns you more than winning it ever did. In those moments you feel the pleasure of balance, and the fight you were ready for loses its point.",
      "scorpio": "Crisis often does it: a loss, a betrayal or an ending you never wanted cracks you open, and you discover you are far more resilient than you knew. You come alive in honest late-night conversations where nothing is off limits. Real intimacy, with someone who sees your shadows and stays, shakes you out of the old comfort and into something much richer. Psychology, a good therapist or a book about the hidden workings of the mind grips you with an appetite you never feel for small talk. Letting go of a possession, a grudge or a routine brings unexpected relief. Afterwards you feel lighter, more powerful and strangely at peace.",
      "sagittarius": "Wide horizons pull you back: a mountain view, an unfamiliar airport at dawn, a night sky far from city lights. You recognise your path in the moment a belief lands in your gut rather than your head, and you know it without needing a second source. Teachers, whether a professor, a guide or an elderly stranger with a story, appear at the right moment and speak to the part of you that wants meaning. Foreign languages and cultures humble and thrill you in equal measure. A single long book or a long walk quietens the chatter better than any break from screens. After such experiences you speak less and say more.",
      "capricorn": "Responsibility, handed to you unexpectedly, is what sets you back on course: the project nobody else will lead, the family decision that falls to you. You discover your spine in these moments and find it steadier than you feared. Older mentors, people who treat you as capable rather than fragile, bring out a seriousness that suits you. A long climb, literal or professional, gives you a quiet pride that no amount of reassurance can match. Seeing your name on something that lasts, a building, a business, a qualification, confirms that you can stand on your own. From there your tenderness becomes a strength others trust rather than a need they manage.",
      "aquarius": "Belonging to something larger than you brings instant relief: a choir, a protest, a volunteer crew, a group project where nobody is the star. You find your way back when a friend's success moves you more than your own would have. Ideas about the future, new technology, social change and odd, inventive people light up a part of you that ego never reached. Being one voice among many feels, to your surprise, like freedom. Friendships built on shared values outlast any passing adoration and hold you steady through hard years. In their company you stop performing and start contributing, and life grows spacious.",
      "pisces": "Moments when control is impossible bring you home: a storm, a hospital corridor, a piece of music so beautiful you forget your list. You come back in the sea, floating with your ears underwater and the world gone muffled. Art, prayer or a sleepy afternoon with nothing to show for it reveals a gentler intelligence in you than the anxious one. Kindness from a stranger, arriving unasked, reminds you that life does not depend entirely on your vigilance. Forgiving a mistake, yours or someone else's, loosens something in your chest you had not known was clenched. In these soft moments you trust the current, and it carries you."
    }],
    ["@content.PLANETS.*.desc", {
      "sun": "Your Sun is the part of you that has to shine for life to feel worth living. It shows what makes you feel most yourself, the work or role that lights you up, and the identity you keep growing into over the years.",
      "moon": "Your Moon is how you feel before you think: the mood you wake up with, the comfort food, the habits that calm you. It shows what you need to feel safe, what you learned about care as a child, and how you now look after others.",
      "mercury": "Your Mercury is how your mind works and how you talk. It shows whether you learn by reading, listening or doing, how you explain things to people, and the way your thoughts move from inside your head into words.",
      "venus": "Your Venus shows what you find beautiful and how you want to be loved. It colours your taste in people, clothes and rooms, how you spend money on pleasure, and what you refuse to live without.",
      "mars": "Your Mars is your engine: how you go after what you want, how you compete and how your anger comes out. It shows the kind of action that leaves you energised rather than drained, and what makes you push back.",
      "jupiter": "Your Jupiter is where life opens doors for you and where you grow by saying yes. It shows what gives you meaning and faith, where luck and generosity find you, and where you are inclined to overdo it.",
      "saturn": "Your Saturn is where you meet limits, fear and responsibility, often early and often alone. Progress there is slow and hard-won, but what you build through that effort lasts, and in time you become the authority on it.",
      "uranus": "Your Uranus is where you refuse to be ordinary and where life surprises you. Its sign is shared with your whole generation, while its house and aspects show the area where you break the rules, change suddenly and think like nobody else.",
      "neptune": "Your Neptune is where you dream, feel for everyone and long for something beyond the everyday. Its house shows where you idealise people or plans, and where you need to look with clear eyes so the dream does not become a fog.",
      "pluto": "Your Pluto is where life asks you to let go of control and come back changed. It shows where you meet power, obsession and loss, and where each ending you survive leaves you stronger and more truthful than before.",
      "northNode": "Your North Node (Rahu) sits where the Moon's path crosses the ecliptic heading north. It points to the unfamiliar direction you are growing towards in this life: awkward at first, and more fulfilling with every step you take.",
      "southNode": "Your South Node (Ketu) holds the talents and habits you already know by heart, as if carried over from before. It is your comfort zone, and leaning on it too heavily keeps you circling instead of growing.",
      "chiron": "Your Chiron marks an early, tender hurt that never fully closes. The same place becomes your deepest wisdom, because what you have lived through there lets you help others with a gentleness nobody taught you.",
      "lilith": "Your Black Moon Lilith (the mean lunar apogee) marks the parts of you that were pushed out: raw desire, anger, the refusal to obey. When you own them instead of hiding them, they turn into personal power.",
      "fortune": "Your Part of Fortune is calculated from your Sun, Moon and Ascendant. It shows where happiness and material ease come to you most naturally, the place where you feel lucky by being yourself.",
      "ceres": "Your Ceres, named for the goddess of the harvest, shows how you look after people and how you need to be looked after in return. It also shows how you grieve, let go and find your way back to nourishment after loss.",
      "pallas": "Your Pallas shows how your mind spots patterns and solves problems. It describes the way you fight for what is fair using strategy and clear thinking rather than force, and the kind of intelligence people come to you for.",
      "juno": "Your Juno shows what you need to feel an equal in a long-term commitment. It points to where loyalty, jealousy and power come up in your closest bond, and the kind of partner you are willing to promise yourself to.",
      "vesta": "Your Vesta shows what you devote yourself to completely. It points to the work or practice you guard with focus, where you need solitude to keep going, and how you keep your inner fire burning when life gets noisy.",
      "vertex": "Your Vertex, on the western side of your chart, lights up at fated meetings and turning points. When it is triggered, people and events arrive that feel beyond your control and change the direction of your life.",
      "asc": "Your Ascendant is the sign that was rising on the eastern horizon when you were born. It shapes your body, your first impression on people and the lens you meet life through, right down to the way you walk into a room.",
      "dsc": "Your Descendant sits opposite your Ascendant on the cusp of the 7th house. It describes the qualities you are drawn to in close partners, and the ones you meet head on in rivals, often traits you have yet to own yourself.",
      "ic": "Your IC (Imum Coeli) is the lowest point of your chart, opposite the Midheaven. It shows your home, family and ancestry, and the private self you return to when the door closes and nobody is watching.",
      "mc": "Your Midheaven is the highest point of your chart. It shows your vocation, your reputation and the legacy you build: the version of you the wider world recognises, relies on and remembers."
    }],
    ["@content.HOUSES.*.desc", {
      "1": "Your 1st house is you in motion: your body, your temperament and the way you start things. Planets here are highly visible, so people notice them in you straight away and they colour your whole personality.",
      "2": "Your 2nd house shows what you earn, what you own and what you are good at. It also describes your sense of your own worth, and the things you hold on to because they make you feel secure.",
      "3": "Your 3rd house is your everyday mind: how you learned at school, talk with siblings and neighbours, write messages and move around your local area. It shows how curiosity and conversation fill your ordinary days.",
      "4": "Your 4th house is your foundation: home, family, heritage and the emotional roots you grew from. It is one of the karmic houses, holding the family patterns you inherited and either repeat or change.",
      "5": "Your 5th house is where your heart comes alive: romance, play, children, hobbies and creative risks. It shows what you make purely for joy and how you like to be seen when you are enjoying yourself.",
      "6": "Your 6th house shows your daily life: work habits, routines, health, pets and the service you give. It describes how you improve things bit by bit and how your body responds to the rhythm you keep.",
      "7": "Your 7th house is about the people you commit to: partners, close collaborators and contracts. It shows what you look for in a partner, and what you project onto them instead of seeing in yourself.",
      "8": "Your 8th house is where you merge with others: sex, shared money, inheritance, psychology, death and rebirth. It is a karmic house of deep bonds, where trust and power change hands and you are changed by it.",
      "9": "Your 9th house is your far horizon: higher education, philosophy, faith, long journeys and teaching. It shows what widens your world and the beliefs you build to make sense of your life.",
      "10": "Your 10th house sits at the top of your chart: vocation, ambition, public image and your dealings with authority. Planets here are what the world sees of you first, at work and in public life.",
      "11": "Your 11th house holds your friends, networks and the causes you care about. It shows the groups you belong to, the people who share your hopes, and the future you are working towards together.",
      "12": "Your 12th house is the hidden part of your life: dreams, retreat, the unconscious, secret help and quiet enemies. It is the most karmic house, where what is unresolved from the past waits for you to meet it."
    }],
    ["@content.SIGNS.*.essence", {
      "aries": "Aries in you is the urge to begin and act before thinking. You prove you are alive by moving, starting things and taking the first step when others wait, and you lose interest the moment the fight is won.",
      "taurus": "Taurus in you is the builder who slows the spark into something solid. You want a body at ease, a home that lasts and resources you can count on, and you resist being rushed out of what already works.",
      "gemini": "Gemini in you is the messenger who names things, connects them and passes them on. Your mind always finds another angle, and you get restless the moment a conversation or a job stops teaching you something new.",
      "cancer": "Cancer in you is the protector who builds a shell where life can grow safely. You remember how things felt, look after people instinctively and need a home base, even when you hide your softness behind a guarded manner.",
      "leo": "Leo in you is the heart that radiates outward. You create for the pleasure of it, light up when someone sees you, and feel it keenly when your warmth goes unnoticed or unthanked.",
      "virgo": "Virgo in you is the craftsperson who refines, sorts and improves. You show love through useful, careful work, notice the small thing everyone else missed, and find it hard to switch off the inner editor.",
      "libra": "Libra in you discovers who you are through other people. You seek balance, beauty and a fair exchange, you can see every side of an argument, and you struggle to choose when someone will be let down.",
      "scorpio": "Scorpio in you goes beneath the surface to what is hidden and powerful. You want the truth, not the polite version, you trust slowly and completely, and you are changed by everything you uncover.",
      "sagittarius": "Sagittarius in you aims its arrow at the horizon. You need faith that life means something and room to travel and learn, and you feel trapped the moment a place or a person tries to fence you in.",
      "capricorn": "Capricorn in you is the architect who climbs. You build structures meant to outlast you, earn your authority through time and effort, and take on responsibility early, sometimes long before anyone asks you to.",
      "aquarius": "Aquarius in you steps back from the crowd to see the whole system. You imagine how things could work better for everyone, keep your independence close, and can feel more at ease with ideas than with feelings.",
      "pisces": "Pisces in you dissolves the boundaries between self and other, dream and reality. You feel what the room feels, sense that everything is connected, and need time alone to find where you end and others begin."
    }],
    ["@content.ASPECTS.*.desc", {
      "conjunction": "A conjunction (0°) fuses two parts of you into one. They act together with great force, so you rarely notice where one ends and the other begins, and you struggle to see them objectively.",
      "opposition": "An opposition (180°) puts two parts of you on either end of a seesaw. You swing between them, often meeting one side through other people, until you learn to hold both at once.",
      "trine": "A trine (120°) links two parts of you in natural harmony. The talent it gives you comes so easily that you barely notice it, and you can take it for granted instead of developing it.",
      "square": "A square (90°) sets two parts of you at odds, and the friction forces you to act. It feels uncomfortable, yet most of your drive and your hardest growth comes from this tension.",
      "sextile": "A sextile (60°) offers two parts of you a chance to work together. They cooperate well, but only once you make the effort to put them to use, so the gift grows with practice.",
      "quincunx": "A quincunx (150°) joins two parts of you that have nothing in common. You keep making small adjustments to fit them together, and it can feel like an itch you cannot quite scratch.",
      "semisextile": "A semi-sextile (30°) links two parts of you sitting in neighbouring signs. The connection is subtle, and it helps you grow only when you pay conscious attention to it.",
      "semisquare": "A semi-square (45°) creates a minor friction between two parts of you. It works as a low-grade irritation, the kind that keeps nagging until you finally do something about it.",
      "sesquiquadrate": "A sesquiquadrate (135°) is a minor stress between two parts of you. It stays quiet for long stretches, then flares up and pushes you into sudden adjustments you did not plan for.",
      "quintile": "A quintile (72°) links two parts of you through talent and style. It marks a signature gift that is recognisably yours, one that becomes sharper the more you practise it.",
      "parallel": "A parallel means two of your planets sit at the same declination, equally far north or south of the celestial equator. In you it works much like a conjunction: the two energies blend and strengthen each other.",
      "contraparallel": "A contra-parallel means two of your planets sit at equal declination on opposite sides of the celestial equator. In you it works much like an opposition, bringing awareness through contrast and the need to balance both sides.",
      "biquintile": "A bi-quintile (144°) is a subtle creative link between two parts of you. It often shows up as an unusual talent that others find surprising and you treat as normal."
    }],
    ["@content.NATURE", {
      "harmony": "This link supports you. When you use it deliberately rather than leaving it to chance, it becomes one of your greatest assets and a strength people rely on.",
      "tension": "This link is a growth edge for you. The friction pushes you to bring together two parts of yourself that do not agree, and that effort builds strength.",
      "fusion": "These two energies are inseparable in you, so they always act as one. Whether that feels like a gift or a struggle depends on the planets involved.",
      "adjust": "Neither side of this link understands the other, so you keep having to adjust. Life asks you for flexibility and constant fine-tuning, and you get better at it every year.",
      "creative": "This link marks a personal talent and a creative style that is yours alone. It grows sharper the more you use it and becomes a signature people recognise."
    }],
    ["@content.DIGNITY", {
      "domicile": "is in domicile, at home in this sign. Its qualities flow through you easily and powerfully, and this part of your life feels like familiar ground where you rarely have to force anything.",
      "exaltation": "is exalted, an honoured guest in this sign. In you it expresses at its most refined, and people notice this part of you as something particularly polished and admired.",
      "detriment": "is in detriment, in the sign opposite its home. You have to work harder to express it, and through that effort you often develop an unusual and lasting strength here.",
      "fall": "is in fall, opposite the sign of its exaltation. Its expression can feel awkward or self-conscious in you at first, and it grows steady once you develop it on purpose."
    }],
    ["@content.CRITICAL", {
      "anaretic": "At 29°, the anaretic degree. You feel urgency and a sense of completion here, as if the lessons of this sign culminate in you and mastery is required rather than optional; many astrologers treat it as a karmic degree.",
      "initial": "At 0°, the very start of the sign. You express it in a fresh, raw and pure way, a little untested, as if you are the one discovering what this sign can do.",
      "critical": "On a critical degree for its modality. This adds emphasis and intensity to the placement, so it shows up in your life more strongly and more often than an ordinary position would."
    }],
    ["fortune.signs", {
      "aries": "You feel luckiest in the first ten minutes of anything: the opening day of a new job, the moment you sign up for the race before you have trained for it. Your good fortune in Aries sits in movement, and life rewards you when you move first and explain later. You are the one who knocks on the door while everyone else is still drafting the email. Sitting in a waiting room, literal or otherwise, flattens you faster than hard work ever could. The catch is impatience: you abandon promising things the moment they stop feeling like a fresh fight. Courage starts the story for you, and a little stubbornness is what finishes it.",
      "taurus": "Ease finds you through your senses: warm bread on a Saturday morning, clean sheets, the weight of a well-made mug in your hand. With the Part of Fortune in Taurus, your luck grows at walking pace, and it rewards the savings account you quietly top up every month more than any gamble. You are the friend who knows which café does the proper butter and who notices when the light in a room is wrong. Rushing is where things go sour for you; pushed to decide quickly, you freeze or dig in. The shadow is comfort turning into inertia, staying in the same flat or job long after it stopped feeding you. When you build slowly on ground you trust, contentment arrives and stays.",
      "gemini": "Good things reach you through talk. With a Gemini Part of Fortune, the job offer comes from a chat at a party, the flat from a neighbour's offhand remark, the new friend from a shared joke at a bus stop. You are happiest with three tabs open, a book half read and a message thread buzzing beside you. Variety is not a luxury for you but the fuel that keeps your mood lifted. The difficulty is scatter: so many threads that none of them gets pulled all the way, and a restless flatness when life turns repetitive. The conversation that will not leave your head is usually the one worth following.",
      "cancer": "Contentment, for you, smells like a kitchen you know. A Cancer Part of Fortune puts your ease in belonging, in the Sunday meal you cook for too many people and the friend who texts to say she got home safely because you asked her to. Caring for others is where good things circle back to you, often through property, food, family or any work that makes people feel held. Your gut reading of a room is usually right before anyone has spoken. The shadow is retreating into your shell when you feel unsafe, sulking instead of saying what hurt. Once your home feels secure, everything else in your life seems to run more smoothly.",
      "leo": "You light up when someone says, \"Go on, show us.\" With the Part of Fortune in Leo, ease comes through creating, performing, hosting and loving out loud, and you are the one who turns a dull Tuesday into an occasion. Being seen feeds you, and there is nothing shameful in that. Your luck grows when you put your own stamp on the work rather than sanding it down to fit in. Children, romance, art and celebration are places where life feels simple and good to you. The harder side is how flat you go when the applause is missing, and how quickly a lukewarm response can feel like a verdict on your whole worth.",
      "virgo": "A tidy spreadsheet, a fixed tap, a friend's CV rewritten so it makes sense: these are your quiet highs. Your Part of Fortune in Virgo finds ease in being useful and in doing a small thing properly. Grand gestures leave you cold, while a good routine, a walk before work and a clear desk can lift your whole week. Skill, detail and service are where your prosperity grows, often slowly and without fanfare. The risk is turning that critical eye on yourself until nothing you make is ever finished enough to show. Competent and imperfect is still a useful contribution, and your good fortune is built on that.",
      "libra": "You can feel the temperature of a room drop when two people fall out, and you are usually the one who fixes it. With the Part of Fortune in Libra, happiness flows through partnership, beauty and a sense that things are fair. You do better with a collaborator than alone, and your diplomacy opens doors that pushing never could. A well-set table, a good playlist and easy company restore you quickly. The shadow is keeping the peace at your own expense, agreeing to the restaurant, the plan or the deal you did not want. Luck comes through contracts, alliances and people who value your grace, particularly once you state your own preference first.",
      "scorpio": "Small talk leaves you hungry. With a Scorpio Part of Fortune, you feel most alive at two in the morning in a conversation that gets honest, or deep in research that everyone else found too dark or too dull. Crises that send others running bring out a calm, focused version of you. Prosperity comes through shared resources, investments, healing work or anything that asks you to look beneath the surface. The difficulty is control: you hold on to a grudge, a secret or a failing situation long after it has stopped serving you. Your luck renews each time you release what is finished and trust whatever grows in its place.",
      "sagittarius": "You feel lucky with a passport in your pocket or on the first page of a book that rearranges your thinking. A Sagittarius Part of Fortune puts your ease in horizons: travel, study, philosophy and conversations about what life is for. Saying yes to the unplanned trip or the course in a subject you know nothing about brings the break you were waiting for. Teaching, publishing and friendships across cultures are all rich channels for your prosperity. The harder edge is restlessness, promising more than you deliver and leaving before the ordinary work begins. Your optimism is not naive; it is one of the real reasons your life keeps working out.",
      "capricorn": "Nothing satisfies you quite like ticking off the last item on a plan you drew up two years ago. With the Part of Fortune in Capricorn, joy comes from achievement you have properly earned, from watching something you built stand up on its own. Responsibility suits you, and people learn early that you are the one who turns up. Your recognition usually comes later than your peers', but it lasts far longer. The risk is treating rest as something you must earn, so that even your holidays become projects with targets. Contentment deepens when you stop downplaying your ambition and let yourself enjoy the view from each step you have climbed.",
      "aquarius": "You are happiest in the group chat that is planning something slightly odd and useful. An Aquarius Part of Fortune rewards you for being different, and for finding the people who are different in the same direction. Luck reaches you through friends of friends, networks, online communities and ideas that are a few years ahead of the mainstream. Technology, invention and social causes are fertile ground for your prosperity. The harder part is detachment: you care about humanity in general and can go cool and distant with the one person standing in front of you. The more fully you accept your own strangeness, the more easily good fortune seems to locate you.",
      "pisces": "The right song comes on and you are gone, somewhere softer than the room you are sitting in. A Pisces Part of Fortune finds peace in imagination, compassion and letting go: a swim in cold water, an afternoon drawing, a quiet hour sitting with someone who is grieving. Your intuition guides you better than any list of pros and cons, and it is often how luck finds you. Creative, spiritual and healing work can all bring prosperity. The difficulty is drift, when escape turns into avoidance and bills, deadlines and hard conversations pile up. Solitude restores you, and trusting the current of your life brings the right people at the right time."
    }],
    ["fortune.houses", {
      "1": "People warm to you before you have said much, and doors open because you walked through them with conviction. With the Part of Fortune in the first house, your luck lives in your own presence: your energy, your face, the way you carry yourself into a room. You do best acting on your own initiative, starting the thing yourself rather than waiting to be chosen. A morning run, a haircut that feels like you or a decision made on instinct can shift your whole week. The trap is shaping yourself around other people's expectations, which dims the quality that makes life go well for you. Your fortune grows every time you show up as yourself, unedited.",
      "2": "Checking your savings balance and seeing it grow gives you a calm that nothing else quite matches. With a second house Part of Fortune, happiness and resources are closely linked for you, and you often have a knack for earning, pricing and spotting value. Your talents are sellable, and knowing what you are good at is half the gift. Physical comforts such as a good coat, a proper mattress or a favourite meal help you feel grounded rather than indulgent. The snag comes when your sense of worth rises and falls with the number in the bank. Contentment settles when you trust that your value was never only financial.",
      "3": "You come home from the corner shop with a new piece of gossip, a recommendation and, somehow, a job lead. A third house Part of Fortune finds ease in talk, learning and the busy traffic of everyday life. Writing, teaching, networking and quick local trips all bring luck your way, and siblings or neighbours often open the unexpected door. Your mood lifts when your days hold variety and your mind has something to chew on. The catch is a nervous restlessness that keeps you skimming, sending messages instead of finishing anything. Sharing what you know is more than a skill for you; it is a source of prosperity.",
      "4": "Closing your own front door at the end of a long day feels like the best kind of luck. With the Part of Fortune in the fourth house, contentment is rooted at home: a secure base, close family ties, a table where the people you love gather. Property, family businesses and ancestral links are often fortunate areas for you. Life grows easier and richer as you get older, once the foundations are wholly yours. The trouble starts when you hide at home from a wider world that is also calling you, or stay loyal to family patterns that keep you small. Time spent making a nest you love repays you many times over.",
      "5": "Give you an afternoon with paint, a dance floor or a child who wants to build a den, and you remember what joy feels like. The fifth house Part of Fortune brings ease through creativity, romance and play. You prosper when you let yourself have fun, make things and show your heart without rehearsing it first. Hobbies, performance, love affairs and the occasional calculated gamble can all carry luck. When life gets too serious, your spark dims and everything starts to feel like a chore. The trap is chasing the thrill of new beginnings and losing interest once the hard middle part arrives. Following what delights you is how fortune keeps finding you.",
      "6": "A good week, for you, is one where the routine works: the early swim, the inbox cleared by lunch, the vegetables eaten before they go soft. In the sixth house, the Part of Fortune finds happiness in meaningful work and a body that feels well looked after. You often prosper through service, skilled labour or health-related fields, and colleagues or pets bring small, steady joys. Solving a practical problem for someone gives you a deeper satisfaction than applause. The pitfall is overwork, taking on everyone's tasks because you do them better and then running yourself down. Your luck builds quietly in the everyday details you get right.",
      "7": "Life gets easier the moment you have someone beside you, whether that is a spouse, a business partner or the friend who always drives while you navigate. A seventh house Part of Fortune shines through one-to-one relationships, and much of your luck arrives through other people. You are happiest sharing plans, meals and decisions with someone who complements you. Negotiation, counselling and client work can all be fruitful. Where it goes wrong is leaning so heavily on a partner that you lose track of your own opinion. The people you choose to stand beside you matter enormously, and letting yourself be supported is part of your luck.",
      "8": "You are the person friends call when the marriage ends or the diagnosis arrives, because you do not flinch. The Part of Fortune in the eighth house rewards you through depth, trust and shared resources. Investments, inheritance, a partner's income or work handling other people's money can all benefit you. Intimacy that goes past the polite surface brings you lasting satisfaction, and so does understanding what makes people tick. The cost is a fear of losing control, which makes you guarded where you most want closeness. Crises transform you for the better, and letting go is one of your most reliable sources of luck.",
      "9": "Your mood lifts the moment a plane leaves the runway or a lecture makes you see something new. With the Part of Fortune in the ninth house, prosperity comes through expansion: travel, higher education, foreign cultures, publishing and spiritual exploration. You are happiest learning something that makes your world feel bigger. Mentors and teachers often open significant doors, sometimes years before you understand why. A long conversation about belief in a stranger's kitchen abroad can stay with you for decades. The trouble is a habit of chasing the next horizon while the life in front of you waits unattended. Following a sense of meaning, rather than mere security, brings you the best results.",
      "10": "Seeing your name on a project, a title or a plaque by the door gives you a deep and lasting satisfaction. A tenth house Part of Fortune places your luck in career and public life. Authority figures often take a shine to you, and your reputation becomes an asset over time. You prosper by stepping into visible roles instead of working invisibly for someone else's credit. The pitfall is letting status define your worth, so that a setback at work feels like a collapse of self. Choosing a vocation that reflects who you are brings both success and contentment.",
      "11": "Half the good things in your life began with \"You should meet my friend.\" In the eleventh house, the Part of Fortune finds joy through friendship, community and shared dreams. You are the one who remembers everyone's birthday in the group chat and turns up to the fundraiser with extra hands. Groups, networks, clubs and campaigns bring you luck, and your hopes for the future carry momentum. Trouble comes when you hide in the crowd, putting the group's plans ahead of what you personally want. Many of your best breaks arrive through a friend of a friend or an organisation you belong to.",
      "12": "An empty church, a long walk with no phone, a quiet night shift when the ward settles: these are the places where you feel most at peace. The Part of Fortune in the twelfth house finds ease behind the scenes. Solitude, reflection, spiritual practice and quiet service restore you. You often prosper through work in hospitals, retreats, research or the arts, anywhere compassion matters more than credit. Help arrives from unseen quarters just when you need it most. The hard part is disappearing, giving so much in private that nobody knows what you need. Trusting your inner life, and giving it time, is the key to your contentment."
    }],
    ["vertex.signs", {
      "aries": "The people who change your life arrive at speed: a stranger who dares you to apply, a rival who makes you furious enough to finally act. A Vertex in Aries brings fated encounters that demand courage. Turning points feel like a match striking, sudden, bright and impossible to ignore. Someone walks in and you find yourself saying yes before you have thought it through, and years later you can trace everything back to that yes. These meetings push you to name what you want and fight for it instead of waiting politely. The hard part is the conflict they bring, since destiny for you often comes wearing the face of an argument.",
      "taurus": "Your turning points often arrive through something you can hold: a house you almost did not view, an inheritance, a job that paid enough. With the Vertex in Taurus, destiny works through value, stability and the body. Significant people show you what you treasure, and some of them shake your security so hard you have to rebuild it from the ground. The change is often slow, a gradual shift in what you think is worth keeping, until one day you realise your whole life has been rearranged. Resistance is your sticking point, clinging to the familiar when the encounter is asking you to move. What sustains you becomes clearer after each of these meetings.",
      "gemini": "A single overheard sentence on a train has redirected your life before, and it will again. A Gemini Vertex brings fateful meetings through words and ideas: a message from someone you barely know, a sibling's suggestion, a book lent at the right moment. Turning points often arrive as information, the news that changes your plans or the person whose way of thinking rewires yours. You notice these moments later, telling the story at a party and realising how small the spark was. The trap is noise: with so many conversations running, the important one is easy to miss. Destiny, for you, speaks quietly rather than shouting.",
      "cancer": "Some people you meet feel like family from the very first hour, as if you had already shared a kitchen table in another life. When the Vertex falls in Cancer, fated encounters touch home, family and emotional safety. Turning points often involve moving house, becoming a parent, caring for an ageing relative or healing an old family pattern. Someone arrives and you know where you belong, or realise you never did. These connections open your heart in ways that feel frighteningly exposed. The pitfall is clinging to the person who made you feel safe long after the chapter has closed, and mistaking familiarity for fate.",
      "leo": "Destiny finds you on some kind of stage: the open mic you nearly skipped, the wedding speech that got you noticed, the love affair that made you feel like the lead in your own film. A Vertex in Leo draws significant people who call out your creativity and your heart. Turning points often arrive when someone recognises your talent before you do and asks you to step into the light. Romance and children can both become the setting for these encounters. The catch is pride, refusing the invitation because you fear looking foolish. Each meeting pushes you to shine without apology and to love generously, even when it feels exposing.",
      "virgo": "Your life has changed course in unglamorous places: a temp job, a physiotherapy appointment, a colleague who showed you a better way to do the work. With the Vertex in Virgo, destiny arrives through work, health and service. Turning points feel humble at the time and only later reveal how profound they were, reshaping your daily habits and your sense of purpose. A mentor in a practical craft, or a health scare that forces you to slow down, often marks the start of a new chapter. It is easy to dismiss these moments because they seem too ordinary to matter. Over time you discover the quiet power of being useful.",
      "libra": "The partnerships that matter most in your life have arrived with an odd sense of inevitability, as if the introduction had been booked long ago. A Libra Vertex brings fated meetings through relationship, whether romantic, creative or professional. Turning points frequently involve commitment, separation or learning to share decisions with another person. These encounters hold up a mirror, and in it you see both your charm and your habit of saying whatever keeps the peace. The difficult part is losing your own shape while trying to be the perfect match. The right partner appears when you stop performing agreeableness and let yourself disagree.",
      "scorpio": "Nobody who enters your life through the Vertex in Scorpio leaves it unchanged, and neither do you. These encounters are intense from the first look: a magnetic pull, a power struggle, an intimacy that goes deeper than you planned. Turning points often involve loss, shared money, a secret revealed or a crisis that strips away something you thought you could not live without. You come out of these periods quieter and much stronger. The hard edge is obsession, holding on to a person or a wound because letting go feels like dying. Each time, you face what was hidden and find that you can be reborn.",
      "sagittarius": "The people who change everything for you are often met far from home, in a hostel, a seminar room or a queue at a foreign border. A Sagittarius Vertex brings destiny through travel, learning and belief. Life-changing people come from another culture, a university or a spiritual path, and a single conversation can widen your worldview at a stroke. Turning points arrive as invitations to go further than you planned. The downside is chasing meaning so hard that you mistake every exciting stranger for a guru. Your truths are meant to keep growing, and these people make sure they do.",
      "capricorn": "At the decisive moments of your life, an older, steadier person has appeared: a manager who took a chance on you, a teacher who told you to aim higher, a boss who said no when you needed to hear it. When the Vertex sits in Capricorn, fateful meetings involve authority, career and responsibility. Turning points arrive as serious commitments, tests of maturity or a sudden promotion into shoes that feel too big. You grow into them, often faster than you expected. The heavy side is duty, carrying other people's expectations so well that you forget your own. What you build after these meetings lasts, as long as you stay yourself inside it.",
      "aquarius": "Your life has a habit of changing overnight because of someone you met at a meet-up, a protest or an online forum. An Aquarius Vertex brings destiny through friendship, community and sudden insight. Significant people often arrive through groups, causes or unusual circumstances, and they seem slightly ahead of their time. Turning points feel like lightning, unexpected and liberating, and they usually break some routine you had outgrown. The difficult side is a coolness that keeps even fated people at arm's length until the chance has passed. Your own oddness turns out to be the thing that draws the right people to you.",
      "pisces": "You have met important people in the strangest ways: a stranger in a hospital waiting room, a voice at a retreat, someone who held your hand at a concert when you were crying. With the Vertex in Pisces, fated encounters carry a dreamy, almost otherworldly quality. Turning points often involve surrender, compassion or the moment you finally let go of control. These connections feel mysterious and sometimes confusing, and you rarely understand them until years later. Where it gets hard is idealising people, seeing a soulmate where there is only a lost soul. Intuition, not logic, is how you recognise grace when it arrives."
    }],
    ["vertex.houses", {
      "1": "Other people have a way of showing you who you are, often at moments when you had not asked. With the Vertex in the first house, key encounters reshape your identity, your appearance and the direction you carry yourself in. Someone sees a quality in you, a boldness or a talent you had overlooked, and after that you cannot unsee it either. Turning points often come as a new name, a new look or a decision to finally live your own way. Hiding behind a role or a partner only delays these meetings. Your destiny is tied to becoming more fully and visibly yourself, however uncomfortable that visibility feels at first.",
      "2": "A single meeting has changed your bank balance, and more importantly your sense of what you deserve. In the second house, the Vertex links fated encounters with money, possessions and self-worth. Someone arrives and offers a job at twice the pay, or takes something from you that you thought was secure. Turning points involve earning, losing or rethinking your resources, and each one shifts your values a little. The hardest discovery is that security built only on possessions feels fragile. Your sense of worth is often the real currency being traded, and each encounter shows you how to value yourself in full.",
      "3": "A neighbour's offhand comment, a teacher's red pen, a text from a sibling: small words have steered your life more than big events. A third house Vertex brings turning points through communication, study and your immediate surroundings. Writing, speaking and short journeys often become the setting for destiny, and the bus route or the local evening class can be where the right person turns up. Messages that arrive unexpectedly carry more weight than they first appear to. It is easy to miss them by assuming fate lives somewhere more glamorous than your own street. A single sentence, heard at the right time, can alter years of your life.",
      "4": "Moving house has been one of the great hinges of your life, and each new address has brought someone who mattered. With the Vertex in the fourth house, fated encounters centre on home, family and roots. A family event, a relative you had never met or a stranger who instantly feels like kin can be pivotal. Turning points involve ancestry, the private foundation of your life and old family secrets that come to light. The ache is carrying inherited patterns you did not choose. Home, after each of these turning points, means something clearer and more your own.",
      "5": "Falling in love has redirected your life more than once, and so has the moment you first made something and realised it was good. The Vertex in the fifth house brings destined romance and creative awakening. A love affair, the birth of a child or a creative collaboration marks a turning point. Encounters here are joyful, dramatic and wide open, the kind of meeting you describe to friends for years. Sometimes intensity gets confused with destiny, and you throw everything at a thrilling person who was only ever meant to be a chapter. Love and self-expression become part of your purpose rather than a distraction from it.",
      "6": "Your destiny has a way of walking in on an unremarkable Tuesday. In the sixth house, the Vertex brings fateful meetings through work, health and daily routine. A colleague at the next desk, a new manager, a doctor who listens or a yoga teacher can change your direction entirely. Turning points arrive as a new job, a change of shift or a health matter that reorders your priorities. You often only see how important these people were after they have left the workplace. The drawback is staying so busy with the routine that you miss the person trying to open a new door. Meaningful change, for you, begins in the most ordinary places.",
      "7": "The biggest turns in your life have come through another person rather than a solo decision. A seventh house Vertex points to fated partnerships, and marriage, business alliances and close one-to-one bonds arrive with an unmistakable sense of destiny. You meet someone and within weeks your address, career or plans have shifted around them. Through these relationships you discover who you are when someone else is watching closely. The harder side is giving your power away, letting the partner steer because the connection feels meant to be. You rarely find yourself by standing entirely alone, and you grow most when you stay recognisable to yourself inside the bond.",
      "8": "Some meetings in your life have begun with a pull so strong it frightened you. With the Vertex in the eighth house, destiny arrives through intimacy, crisis and transformation. A shared financial matter, a divorce settlement, an inheritance or a loss can change the whole shape of your life. Turning points involve sexuality, grief or deep psychological change, and they usually come without warning. You come through them with a resilience that surprises the people who knew you before. The dark side is trying to control what cannot be controlled, clinging to the person or the money. What you share with another person changes you at the root.",
      "9": "Some of your most important teachers have spoken a different language, literally or otherwise. The Vertex in the ninth house brings turning points through travel, education and philosophy. A year abroad, a lecturer who took you seriously, a book found in a second-hand shop or a spiritual encounter opens a new chapter. People from very different backgrounds play a pivotal role, pulling you beyond what you grew up believing. Each of these meetings leaves you with a larger map of the world. The snag is rushing off towards the next horizon before the lesson of the last one has landed. You seek meaning beyond the familiar, and destiny keeps meeting you on the road.",
      "10": "A phone call from someone senior, a chance meeting at a conference, a mentor who put your name forward: your career has turned on moments like these. In the tenth house, the Vertex links fated encounters with vocation and public standing. The right boss or influential contact arrives at just the right moment to redirect your professional path. Turning points involve promotions, public recognition or a calling you cannot ignore. The weight comes with it, since visibility brings scrutiny and a reputation that has to be carried. These experiences shape how the world sees you and your own sense of what you are here to contribute.",
      "11": "A friend dragging you along to a meeting you did not want to attend has, more than once, changed everything. An eleventh house Vertex brings destiny through friends, groups and shared ideals. A community, a network or a campaign becomes the stage for the meetings that matter most. Turning points often involve changing social circles, leaving one crowd and finding your real people in another. Losing yourself in the collective, taking on its causes without checking they are yours, is the risk here. These encounters teach you where you fit in the wider world, and a shared purpose brings you the people you have been waiting to meet.",
      "12": "Some of the people who shaped you most were met in hidden places: a hospital corridor, a retreat, a support group, a relationship you kept private. With the Vertex in the twelfth house, fated encounters unfold quietly and often behind closed doors. Turning points involve solitude, endings or an inner revelation that nobody else sees happen. You come out of these periods changed, often before anyone around you notices. The hard part is secrecy, holding on to what needs to be brought into the light. These experiences teach you to trust the unseen, and what is decided in private shapes everything that follows in public."
    }],
    ["houses.*.gifts", {
      "1": "When this part of you is healthy, you walk into a room and arrive. You do not spend the first ten minutes apologising for your coat, your lateness or your opinion; you say hello and get on with it. Starting comes easily: you sign up for the class, send the first message, pick up the paintbrush before the doubt has finished speaking. People read you accurately, because what shows on your face matches what is going on underneath. Your body feels like somewhere you live rather than something you manage. Even on a bad day you carry a basic permission to exist, and others borrow it from you when they are nervous.",
      "2": "When your second house is healthy, you know what you are worth without needing a payslip to tell you. You can name your price, turn down a job that underpays, and treat yourself to the good bread without a lecture in your head. Money comes in through skills you have, and you look after it with calm common sense. Your possessions are chosen: the chair you sit in, the coat that lasts ten winters. Pleasure in food, touch, music and a warm bath restores you quickly. Underneath it all runs a steady sense that you are enough, which lets you build slowly and keep what you build.",
      "3": "A healthy third house makes your mind good company, both for you and for everyone around you. You pick up the gist of a conversation quickly, remember the useful detail, and explain things so that people understand. You are the one who knows which café does the best breakfast, who texts your sister on her birthday, who turns a dull commute into a podcast education. Writing a tricky email feels manageable rather than daunting. Curiosity keeps you young; at eighty you will still be asking the waiter where the fish came from. Your local world is full of small, friendly connections, and news travels through you easily and kindly.",
      "4": "With a strong fourth house you carry home inside you. You can unpack a suitcase in a hotel room and feel settled within the hour, because the foundation is internal. Your own place, however small, feels like yours: the mug you like, the lamp you switch on at dusk, the smell of your kitchen. You keep close ties with family or with the friends who became family, and you know who you would ring at three in the morning. When the rest of life shakes, you go home, close the door, and something in you reassembles. Others find that steadiness restful and often end up at your table.",
      "5": "When your fifth house is flourishing, joy is part of the week rather than a reward at the end of it. You sing in the car, doodle in the margins of meeting notes, and say yes to the karaoke. Making things comes easily, whether that is a cake, a song, a garden or a child's fancy dress costume finished at eleven at night. In romance you are generous and playful, the one who plans the surprise. Children, and the childlike parts of adults, respond to you. Being seen doing what you love feels good rather than frightening, and that warmth spills into every room you enter.",
      "6": "A balanced sixth house makes you competent. You know where the spare keys are, which colleague to ask about the printer, and how long the roast needs. Your days have a rhythm that holds you: the morning walk, the list on the fridge, the Sunday reset. You take pride in a job done properly, even when nobody will notice the neat seams. Your body talks to you early, a stiff neck or a heavy afternoon, and you listen before it has to shout. Colleagues trust you, animals settle near you, and small rituals keep you steady through large storms.",
      "7": "When your seventh house is healthy you can meet another person as an equal, neither shrinking nor taking over. You listen properly, hear what sits behind the words, and negotiate in a way that leaves both people feeling respected. You choose partners who bring out the best in you, and you do the same for them. A good argument does not frighten you, because you trust the relationship to survive honesty. In business too, you know how to make a deal fair. People often say they became more themselves in your company, and you feel that with the right partner beside you.",
      "8": "A resilient eighth house gives you steadiness in the places most people flinch from. You are the one who can sit with a friend in a hospital corridor, talk about money with a partner without a row, or hear a confession without judging. Secrets are safe with you. In intimacy you can let go and allow yourself to be changed by closeness. You handle shared finances, loans and inheritances with a clear head. Loss marks you, yet each ending leaves you wiser rather than harder, and you come through crisis with a quiet authority that others lean on.",
      "9": "An open ninth house keeps your world wide. You can land in a strange city, get thoroughly lost, and enjoy it. Ideas that challenge you make you feel more alive rather than threatened. Learning never stopped for you after school; there is always a course, a language app, a book on the history of something obscure. You can hold a belief firmly and still revise it when the evidence changes. Friends ring you for perspective because you connect things across cultures and disciplines. Underneath runs an optimism that life means something, and that faith carries you through bad years without making you naive.",
      "10": "When your tenth house is thriving you know which direction you are facing. You set goals that mean something to you, and you reach them by steady effort rather than luck. People trust you with responsibility: you are the one asked to chair the meeting, run the project, speak for the group. Your reputation is earned, built over years of turning up and keeping your word. The work you do feels like an honest expression of who you are, not a costume. You handle authority fairly, and younger colleagues remember you as the person who took them seriously.",
      "11": "A healthy eleventh house surrounds you with people who share your hopes. You have the group chat that actually helps, the club, the campaign, the online community where you feel understood. You collaborate well, bringing your own odd talent to a shared goal and letting others do the same. Allies appear when you need them. You still believe the future can be better, and you do small, practical things towards it. Groups do not flatten you; they make room for exactly the part of you that felt strange elsewhere, and you are loved for it.",
      "12": "When your twelfth house is healthy, solitude feeds you. An afternoon alone with the curtains half drawn, a long walk with no phone, a dream you write down on waking: these restore you in a way nothing else can. Your intuition is reliable, and you often know before you are told. You can sit with someone in pain without rushing to fix it, and they feel held. Imagination runs deep in you, feeding art, music or prayer. You forgive more easily than most, and there is a peace in you that others notice without being able to name it."
    }],
    ["houses.*.challenges", {
      "1": "The strain shows in the gap between how you come across and how you feel. You catch your reflection in a shop window and adjust your face before you have noticed you are doing it. Sometimes you are so busy managing the impression that the real you never makes it into the conversation. At other times the opposite happens: you charge in, react first, and spend the drive home replaying what you said. A manner that once kept you safe can harden into a costume, and then people respond to the costume while you feel unseen. Being called \"intense\", \"cold\" or \"too much\" stings precisely because it lands on the surface, not on you.",
      "2": "Money and self-worth get knotted together in you, so a bad month at the bank can feel like a verdict on your whole character. You check your balance before booking the dentist, or avoid looking at it for weeks and then panic. One pattern is hoarding: keeping the things, the savings, the job, long after they stopped feeling good, because letting go feels dangerous. The other is spending to soothe, the parcel on the doorstep that fills a gap for an afternoon. Underpricing yourself is common, particularly for the talents that come easily. When someone praises your work, you hear it and still quietly round your value down.",
      "3": "Your mind can run faster than your life needs it to. You have eleven tabs open, three half-read books by the bed, and a message you drafted twice and never sent. Worry often arrives dressed as thinking, so you rehearse conversations in the shower that never happen as scripted. A childhood where you were talked over, teased by a brother or sister, or labelled the slow one or the chatty one still shapes how freely you speak. You either hold back what you know or say too much to be sure you are heard. Collecting information starts to replace deciding, and the decision keeps sliding to next week.",
      "4": "Home is where the old weather returns. You can be a capable adult all week and then, twenty minutes into a family visit, feel eleven again, sulking in the back of the car. Old roles cling: the peacemaker, the responsible one, the child who kept quiet so nobody would shout. Sometimes you move house repeatedly, hoping the next place will finally feel right, and discover the restlessness came with you in the removal van. Loyalty to family patterns outlives their usefulness, so you repeat a parent's silence or temper without choosing to. The private self nobody sees at work carries more tiredness than you let on.",
      "5": "Here the strain shows as a heart that is either locked away or out on loan. You love to create yet freeze the moment anyone is watching, so the novel stays in a drawer and the guitar stays in its case. Or you need the applause too much, and a quiet reception to your work flattens you for days. Romance can become a game you play to feel alive, with the drama more addictive than the person. At the other extreme, you are so responsible that fun feels like something other people have time for. Your playful self then leaks out sideways, in overspending, flirting or a sudden reckless weekend.",
      "6": "Your body often knows you are stressed before you do. The jaw tightens, sleep thins out, digestion complains, and only then do you admit the week has been too much. Leaving a task half done is hard for you, so you stay late tidying the spreadsheet while your own needs wait in the car park. Being useful can turn into being used: you are the colleague who always says yes and then resents it at home. Perfectionism slows you down more than it improves the work. When routine collapses entirely, you feel oddly lost, eating at strange hours and scrolling past midnight.",
      "7": "Close partnership pulls you off centre. You adapt so quickly to what the other person wants that a few months in, you cannot remember what you liked for dinner before you met. Or you hold everyone at a careful distance and call it independence. The same argument turns up wearing different faces, the partner who never listens, the colleague who takes the credit, and your own part in it is hard to see. Qualities you admire or resent in others often belong to you. Leaving is painful, so you stay in arrangements long after the warmth has gone, hoping the old version will come back.",
      "8": "Trust is expensive for you. You read a partner's messages for tone, sense a shift in mood from across the room, and brace before anyone has done anything. Control feels safer than dependence, so you keep a private account, a hidden exit, a part of yourself behind glass. Or you merge too fast and then feel swallowed. Money tangled with a partner or family, a debt, a will, a shared mortgage, becomes the place where every unspoken feeling gets fought out. Grief stays in you longer than you admit, and an old loss surfaces years later on an ordinary afternoon in the supermarket.",
      "9": "The strain here comes from chasing meaning without letting it land. You book the next trip before unpacking from the last, and start another course while the previous certificate sits in a drawer. Restlessness can masquerade as growth. At the other extreme, you settle on a philosophy and defend it so hard that anyone who disagrees becomes a project to convert. You notice yourself preaching at dinner and cannot quite stop. When life refuses to fit your beliefs, a redundancy or an illness with no obvious lesson, the crisis of faith knocks you flat for longer than you expected.",
      "10": "Ambition can become a master rather than a servant. You check your email on holiday, measure your worth by your title, and feel a flicker of panic when a friend is promoted. Sometimes the career you are building belongs more to a parent's hopes than your own, and you only notice when success feels hollow. Fear of failing in public keeps you from trying at all. Then you watch less talented people take the roles you wanted and feel quietly furious. Overwork becomes a way of feeling worthy, and rest starts to look like falling behind.",
      "11": "Belonging is where the ache sits. You stand at the edge of a party feeling like the one who never got the invitation, even when you did. You either bend yourself to fit a group and lose your own voice, or keep friends at arm's length so nobody can leave you out. Sometimes you sign up for every cause and burn out, answering committee emails at midnight. Other times you drift between circles, well liked everywhere and at home nowhere. Hopes turn into private fantasies you never share, so the future you want stays unbuilt.",
      "12": "You absorb other people's moods like a sponge, then wonder why an ordinary day has left you drained. Hidden fears run quietly in the background, and you sometimes sabotage good things just before they arrive, missing the interview or picking the fight on the eve of the holiday. Escape is tempting: another episode, another glass, another hour of scrolling to avoid the silence. You can retreat so far that friends stop calling. Or you avoid being alone at all, keeping the radio on in every room, and so never meet the parts of yourself that need gentle attention."
    }],
    ["houses.*.ruler", {
      "1": "Your sense of self does not stay in the first house; it travels to wherever the ruler of your rising sign lives, and that house is where you become most fully yourself. The place where you feel most alive and least self-conscious is usually that area of life. If the ruler sits among work and reputation, you discover who you are by doing a job in public. If it sits in the home, you come into focus around your own table. When that area is going well, you feel like yourself everywhere else too. When it stalls, you can feel strangely vague about who you are, even among people who know you well.",
      "2": "The ruler of your second house points to where your money and sense of worth are earned. The house it occupies often shows the kind of activity that pays you best, not only in cash but in self-respect. If it sits in the area of communication, you earn through words, calls and ideas. If it sits in partnership, your finances rise and fall with the people you team up with. When that part of life is flourishing, your income steadies almost as a side effect. When it is neglected, money problems appear that no budget spreadsheet fully fixes, because the real issue lives in that other house.",
      "3": "Your thinking wants to go to work wherever the ruler of your third house lands. Its house shows the subject your mind keeps drifting towards and the setting where your words have the most effect. If it sits in the area of money, your ideas earn their keep through writing, selling or teaching. If it sits in the area of depth and shared resources, your curiosity digs into psychology, research and everything people keep quiet. Feeding that other part of life sharpens your conversation and eases your worry. When it goes unfed, your mind turns restless and busy without getting anywhere.",
      "4": "The ruler of your fourth house shows where your roots reach out into the rest of your life. The house it lands in describes what makes you feel at home, which is not always a building. If it sits near career, family and work run together, through a family business or a job that feeds your need for belonging. If it sits in the house of distant places, home can lie far from where you were born, or turn out to be a philosophy rather than an address. Tending that area steadies you more than redecorating ever will, and neglecting it leaves you feeling faintly homeless.",
      "5": "Wherever the ruler of your fifth house lands, your joy wants to find a home. The house it occupies shows which part of life lights you up and gives your creative energy a channel. If it sits in the area of money, a hobby can become income, and pleasure and earning feed each other. If it sits in the hidden twelfth, your best creative work happens in private, in the notebook nobody reads or the painting made at midnight. When that area has room, fun returns without effort. Starved of it, even your holidays start to feel like obligations.",
      "6": "The ruler of your sixth house shows where your daily work and habits connect to the rest of your life. Its house reveals what kind of work suits you, and what your routines are for. If it sits in the area of creativity, you work best when the job has room for play, colour or performance. If it sits in the house of travel and learning, your working life leans towards teaching, other cultures or a field shaped by belief. With that area fed, the daily grind feels purposeful. Cut off from it, even a good job feels like a treadmill.",
      "7": "The ruler of your seventh house shows the road partners tend to walk in on. Its house describes where you meet significant people and what shared life with them revolves around. If it sits in the area of work, you meet partners through your job, and your relationships often involve building something together. If it sits in the fourth, partnership circles around home, family and making a nest. That area explains why certain people arrive in your life when they do. While it is active, relationships come towards you; while it is quiet, you can wait a long time.",
      "8": "The ruler of your eighth house shows where shared resources and deep change enter your life. Its house tells you which area gets transformed when you let someone close or when life takes something away. If it sits in the area of personal money, your finances are bound up with a partner's or with what you inherit. If it sits in the house of belief, crisis changes your philosophy of life profoundly. The link between the two houses explains why upheaval in one part of your life so often echoes through another. It also shows where you find renewal after an ending.",
      "9": "The ruler of your ninth house reveals where your search for meaning takes shape in real life. Its house shows the setting in which your beliefs grow and the channel through which you share what you have learned. If it sits in the third, you teach, write or study close to home, and wisdom turns up in ordinary conversation. If it sits in the seventh, a partner from another culture or faith opens your world. Whenever that area of life is active, your horizons expand. Without it, your views narrow and life feels smaller than it should.",
      "10": "The ruler of your Midheaven shows where your vocation is lived out, day to day. Its house describes the kind of work that fits you and the arena in which your reputation grows. If it sits in the sixth, your calling runs through daily craft, service and skill. If it sits in the third, words, teaching or media feature strongly. If it sits in the twelfth, your best work happens behind the scenes, in hospitals, studios or quiet offices. When your ambitions line up with that area, recognition follows more easily. Pulled away from it, a career can feel like climbing the wrong ladder.",
      "11": "The ruler of your eleventh house links friendship and hope to another part of your life. Its house shows where your allies are found and where your dreams for the future want to take root. If it sits in the tenth, friends become colleagues and your network carries your career. If it sits in the fifth, friendship grows through shared play, sport or creative projects. That link explains why certain friendships blossom in particular settings and wither in others. A lively season in that area widens your social world, and a stall there leaves you feeling oddly alone.",
      "12": "The ruler of your twelfth house shows where hidden material surfaces in your life. Its house is the place your fears, intuitions and old sorrows find their way into the open. If it sits in the first, you carry strong intuition alongside flashes of self-doubt that others can see. If it sits in the seventh, partners stir up old wounds, and relationships become a path of healing. That area is where you catch the unconscious at work. Things that go strangely wrong there are usually the twelfth house speaking, and the same place is where your quiet recovery begins."
    }],
    ["houses.*.karmic", {
      "1": "Underneath the manner you show the world lies an older decision, taken before you had words, about what it would take to be safe here. You learned to be charming, or invisible, or first through every door, and that reflex still fires when you meet a stranger. The soul story of this house is about the body you arrived in and the stance you took on day one. You carry a sense of having come in with a task already underway, which makes you impatient with slow beginnings. Across your life, the old survival posture slowly loosens. What remains is a presence you choose: the same face, now worn freely instead of held up like a shield.",
      "2": "At the soul level your second house holds an old relationship with scarcity and plenty. You arrived with some talents that feel oddly familiar, as if you had practised them before, and with fears about survival bigger than your circumstances explain. You notice it when a small bill brings a disproportionate chill, or when you keep a drawer of things you will never use, just in case. The deeper story is about learning that your worth was never for sale. As that settles, you stop bargaining with life for security and begin to trust the resources you carry inside you, which nobody can ever repossess.",
      "3": "The soul story of your third house lives in the voice inside your head. Much of what that voice says was learned early: family phrases, a teacher's remark, a sibling's nickname you never quite shook off. You catch yourself thinking \"I'm hopeless with numbers\" or \"I always put my foot in it\" and realise the sentence is not even yours. Words carry unusual weight for you, and a single conversation can change the course of a year. The deeper work is to hear those old scripts clearly and write new ones. As you do, you speak with a voice that sounds like your own.",
      "4": "Your fourth house holds what came down the family line before you were born: a grandmother's thrift, a migration, a grief nobody named, a talent that skipped a generation and landed in you. You feel it when an ordinary family habit carries an emotional charge out of all proportion. This is one of the deepest karmic places in your chart, and you often feel responsible for more than your own life. Your work is to honour your ancestors fully while deciding, quietly, which patterns stop with you. When you break an old cycle here, the effect travels backwards and forwards, easing those before and after you.",
      "5": "Some talents arrive in you already half formed. You sit at a piano for the first time or pick up a brush and your hands seem to remember something. The soul story of your fifth house is about the creative spark you came to express and the part of you that wants to be seen shining. It also carries old shame about showing off, a feeling that visibility once cost you dearly. You notice it when praise makes you squirm. The deeper movement of your life here is towards playing and creating without first earning permission, and letting your light be enjoyed.",
      "6": "Your sixth house carries an old story about service. Part of you feels it must earn its place by being useful, as though rest were something that has to be deserved. You notice it when you apologise for taking a sick day or clean the kitchen before letting yourself sit down. At the soul level this echoes long patterns of servitude or martyrdom. Across your life the task is to serve from fullness, with clear limits, so that helping others also feeds you. Once that shifts, your craft becomes a kind of devotion, and caring for your health becomes a form of self-respect.",
      "7": "Some people feel familiar the moment you meet them, as if a conversation resumed. Your seventh house holds these meetings, and they rarely come without purpose. The partners, and even the opponents, who matter most to you mirror unfinished business, showing you parts of yourself you have not yet claimed. You notice it when you fall for someone's confidence and later realise it was your own you were missing. The soul work is to recognise what you project and take it back. Then relationships stop feeling like fate happening to you and become choices you make with open eyes.",
      "8": "Your eighth house holds old debts of power, trust and loss, and you often feel their weight long before you understand them. Certain encounters carry a fated charge: the lover who changes everything, the stranger who appears during a crisis, the inheritance that arrives with strings. You know what it is to be taken apart and put back together. An old fear of being betrayed, or of betraying, colours how much you let yourself need anyone. The soul work is releasing control. Each time you do, something truer grows back, and you come to understand death and renewal from the inside.",
      "9": "You carry convictions that feel older than your education. Some ideas land in you as instantly true, a temple, a scripture, a line of poetry, as if you were remembering rather than learning. The soul story of your ninth house is about the spiritual paths and philosophies you seem to have walked before. They give you a natural wisdom, or a rigid certainty you have to loosen, and often both. Teachers appear in your life when you need them. The deeper movement is towards seeking truth humbly and passing on what you know without imposing it on anyone else.",
      "10": "Your tenth house holds the contribution you came to make, the mark you feel compelled to leave. You sense it as an ache whenever you are in the wrong job, even a well-paid one. At the soul level this carries old patterns around authority: power once used harshly, or power once feared and avoided. You recognise it in how you react to bosses and how you behave once you become one. The deeper story is about taking up a role that serves something larger than status. When you find it, ambition softens into purpose, and your public life starts to feel like a vocation.",
      "11": "Some friends feel like family from the first evening, and you cannot remember a time before them. Your eleventh house holds these soul companions, along with the groups you seem to recognise instantly. It also carries old wounds of exclusion, a sense of once having been cast out, which shows up as a flinch when a group chat goes quiet. The deeper story is about offering your individuality to something larger than yourself without dissolving into it. As you do, you find your people, and the future you hope for becomes something you build together.",
      "12": "What you carry in your twelfth house often feels older than you. There are sorrows you cannot trace to anything in your life, dreams set in places you have never been, a compassion that runs deeper than your experience explains. This is the most karmic place in your chart, linked with unfinished soul business and with the collective grief you pick up without meaning to. You feel it in cathedrals, by the sea, at the funerals of near strangers. The deepest work is surrender and forgiveness, particularly towards yourself. As that happens, the old weight lightens, and what remains is a quiet faith."
    }],
    ["asteroids.ceres.aspects", {
      "fusion": "When Ceres sits right on top of another planet in your chart, caring and that planet's drive become one gesture in you. You feed people the way that planet speaks: with Mars you cook fast and fiercely, with Mercury you nurture through long phone calls and useful information, with Saturn through reliable structure. Being looked after in that language is what makes you feel held, and anything else slides past you unnoticed. Loss hits this spot hard; when a relationship or a home ends, the planet's whole function can go quiet for a while, as if the pilot light went out. You return to it again and again, because what was taken tends to come back in a changed form. Your care carries a signature that people remember years later.",
      "harmony": "Care moves through you with very little friction here, because Ceres and the other planet cooperate rather than compete. You know instinctively how to feed yourself when you are low: the right meal, the walk, the friend you ring without thinking. Other people notice it too, and you are often the one who restocks the fridge or remembers the birthday nobody else wrote down. This ease is real, though it makes you underrate how much you give, since it never feels like effort. You rarely ask for the same attention back and then feel oddly empty after a busy season of tending everyone. Once this flow runs towards yourself as freely as it runs outwards, it becomes one of the steadiest resources in your chart.",
      "tension": "Between Ceres and a planet it squares or opposes, your need to care and be cared for keeps bumping into something that wants to go its own way. You catch yourself hovering over someone who is ill, or tidying a friend's kitchen uninvited, because love feels safer when you are in charge of it. On other days the swing goes the opposite way and you neglect your own body entirely, skipping meals while you chase the planet's agenda. Old stories of being fed too little, or smothered too much, sit behind these patterns. That history gives you a hard-won understanding of what nourishment costs. Over time you learn to give care that leaves the other person freer, and to take it without apology.",
      "adjust": "A quincunx between Ceres and another planet keeps your caring instincts slightly out of step with what that planet wants, and you feel the mismatch in small daily ways. Your eating goes irregular when work heats up; you forget lunch, then overcompensate at midnight. You offer help in a form the other person did not quite ask for and have to recalibrate. None of this is dramatic, which is why it wears you down: tired digestion, broken sleep or a routine that never quite settles. Constant tweaking becomes your skill, and you end up unusually precise about what restores you, down to the time of day and the exact food. People come to you for that finely tuned kind of care.",
      "creative": "With a quintile between Ceres and another planet, nurturing becomes a craft in your hands rather than a duty. You invent ways of looking after people that nobody taught you: the playlist made for a friend in hospital, the recipe altered until it suits someone's odd diet, the ritual you build for a grieving household. That planet lends the style, and the originality is unmistakably yours. You find pleasure in solving the puzzle of what a particular person needs. The gift often stays private, used only for family, because you do not always recognise it as talent. Given room, it grows into work, teaching or art that feeds far more people than your own kitchen table."
    }],
    ["asteroids.pallas.aspects", {
      "fusion": "Pallas fused with another planet turns that planet into your thinking tool. You see patterns through it: with Venus you read the design of a room or a relationship at a glance, with Mars you map the strategy of a fight before it starts. People bring you tangled problems because you spot the missing piece while they are still describing the situation. Questions of fairness grip you personally, and you can lose sleep over an injustice at work that others shrugged off. The shadow is a habit of living in your head, treating feelings as puzzles to be solved rather than experiences to be had. Father figures, mentors or authority often loomed large in shaping this sharp, strategic mind.",
      "harmony": "Ideas turn into workable plans for you with very little strain, because Pallas and the other planet support each other. You look at a messy spreadsheet, a tangled family schedule or a failing project and see the neat solution almost immediately. Colleagues rely on you for the calm, clever fix, and you enjoy being useful in that way. Because it comes so easily, you dismiss it as common sense and forget that most people cannot do it. The risk is coasting, staying with comfortable problems rather than taking on the hard ones that would stretch you. When you do choose a demanding challenge, this easy intelligence shows its full weight.",
      "tension": "Your clear, strategic mind and the planet it squares or opposes pull against each other, and you feel it as a split between head and heart. You can argue a case brilliantly and still feel wrong inside, or follow a gut feeling and then pick it apart for days. Unfairness sets you alight; you are the one who writes the long email to management or refuses to let a family grievance drop. Sometimes that fight is noble and sometimes it is a way of avoiding softer feelings. The friction sharpens you, and over the years your judgement becomes unusually keen, tested in real conflicts rather than theory. You come to trust a wisdom that includes both your reasoning and your wants.",
      "adjust": "A quincunx between Pallas and another planet means your cleverness and that planet's needs rarely line up neatly, so you work by trial and error. You design the perfect plan, then find it ignores something you care about and rebuild it from scratch. Your notebooks are full of crossed-out strategies and second drafts. Frustration comes easily, particularly when others seem to reach solutions without the constant revising. Yet the process trains an adaptable intelligence that copes with messy, real conditions better than any tidy theory. You become the person who can rescue a project halfway through, because you are practised at changing course without losing the thread.",
      "creative": "A quintile links Pallas with another planet in a way that makes you inventive, almost playful, with problems. You see solutions sideways: the unusual layout that makes a small flat work, the negotiating move nobody expected, the clever pattern in a knitting chart or a piece of code. That planet colours the talent, and your own quirky logic drives it. You love being the one who finds the elegant answer, and you get bored when a task has only one obvious route. This gift thrives on freedom and withers under rigid instructions. Left to design things your own way, you produce work people remember for its wit and originality."
    }],
    ["asteroids.juno.aspects", {
      "fusion": "Juno fused with another planet makes that planet central to what you need in a committed bond. You seek its qualities in a partner, or bring them yourself, with unusual intensity: with Mercury you need someone you can talk to endlessly, with Pluto a bond that goes all the way down. Loyalty matters enormously to you, and a small betrayal can feel like the collapse of everything. You also give a great deal, often reorganising your life around the person you have chosen. The difficulty is power: who decides, who compromises, who holds the purse strings. When the bond is equal, you are a remarkably devoted and protective partner.",
      "harmony": "Commitment comes naturally to you in this contact, because Juno and the other planet support each other smoothly. Staying loyal feels less like a sacrifice and more like the obvious thing to do. You are good at the practical side of partnership: sharing chores, planning holidays together, remembering how your partner takes their tea. Friends often see your relationship as steady and envy the ease of it. The shadow is complacency, letting comfort replace careful attention until a partner feels taken for granted. You thrive when that ease becomes a foundation for deeper honesty rather than a reason to stop trying.",
      "tension": "Juno squared or opposed by another planet brings friction between your need for an equal, committed bond and a drive that refuses to be tamed. You catch yourself checking a partner's phone, or bristling when they spend a weekend with friends, and then feel ashamed of the jealousy. At other times you are the one pulling away, torn between freedom and the promise you made. Relationships teach you the same lesson in different forms until it lands. Power struggles over money, time or respect recur in more than one partnership. Each round builds maturity, and you end up knowing precisely what fair partnership looks like because you have fought for it.",
      "adjust": "A quincunx between Juno and another planet leaves your needs in partnership slightly at odds with what that planet wants, so commitment involves a stream of small compromises. You give up the Friday class to fit a partner's schedule, then quietly resent it. You adjust how you speak, dress or spend to keep the peace and lose track of which choices are yours. Nothing is ever badly wrong, yet something rarely feels quite settled either. The ongoing negotiation eventually turns you into a skilled partner who can renegotiate terms without drama. Relationships work best for you when adjustment runs both ways and gets said out loud.",
      "creative": "With a quintile between Juno and another planet, you approach commitment in an original way that suits you rather than convention. You design partnership as you go: separate bedrooms, a shared business, a long-distance marriage that works beautifully, a wedding nobody else would have planned. That planet shapes the style, and your own imagination sets the rules. You notice what makes a bond feel alive and you are willing to experiment. Family members sometimes find your arrangements puzzling, which stings. Yet the relationships you build carry a distinctive signature, and they last because they were made to fit the actual people inside them."
    }],
    ["asteroids.vesta.aspects", {
      "fusion": "Vesta fused with another planet makes that planet's area the place you give yourself completely. With the Moon it is home or family, with Mercury study or writing, with Mars a physical discipline: whatever it is, you disappear into it for hours and come out restored. People call you dedicated, sometimes obsessive. You need solitude to keep that flame burning, and you guard your working time fiercely. Intimacy takes on a sacred, private quality for you too, shared with very few. The risk is burnout, feeding the fire until nothing is left for the rest of your life. Paced well, this devotion becomes a lifelong source of meaning.",
      "harmony": "Focus comes easily to you through this contact, as Vesta and the other planet sustain each other. You settle into deep work the way other people settle into a hot bath, and an afternoon vanishes while you polish a design or practise scales. Devotion to your craft feels nourishing rather than draining. Colleagues admire your reliability, since you finish what you start without fanfare. Because you enjoy your own company so much, you drift away from friends without noticing the gap. Your commitment holds best when it includes a few people who keep the door open to you and pull you out now and then.",
      "tension": "Vesta squared or opposed by another planet sets your need for focused solitude against a drive that wants something else entirely. You shut the door to work and hear the family laughing outside; you join the party and think about the unfinished project. Partners complain that your devotion leaves little room for them, and part of you agrees. Other times you throw yourself into a relationship and lose the thread of your own work for months. Guilt follows you in both directions. Over time this conflict makes you deliberate, and you learn to protect sacred time without shutting out the people who matter.",
      "adjust": "A quincunx between Vesta and another planet keeps your focus and that planet's needs slightly out of line, and you feel it in your daily habits. You set up the perfect morning routine, then a new job or relationship disrupts it and you start again. Productivity comes in bursts followed by scattered weeks. The tiredness is real, because you keep rebuilding the conditions for concentration. Still, this adjustment teaches a flexibility that pure devotion lacks. Eventually you can find your flame in a crowded café, a hospital waiting room or a borrowed desk, and that portable focus becomes a strength.",
      "creative": "A quintile between Vesta and another planet gives you a particular talent for turning that planet's energy into a devoted, creative practice. You build rituals around your work: the same candle lit before writing, the same route walked before painting, the notebook kept for twenty years. Your concentration has an artistic quality, and the results carry a distinctive care. Others sense the devotion and find it calming to be near you while you work. You often keep this gift hidden, treating it as a private hobby rather than something worth sharing. Given an audience, it becomes a practice that inspires other people to find their own flame."
    }],
    ["nodeHouses.*.story", {
      "1": "Your North Node in the first house asks you to become someone who chooses for yourself, while the South Node in the seventh pulls you back towards pleasing others. You know the feeling of arriving at a restaurant and waiting to hear what your companion orders before picking. Reading a partner's mood, adapting your plans, smoothing things over: all of it is second nature, and it earns you affection. Yet something in you stays hungry, because the life you are living was shaped around other people's wishes. Growth arrives each time you state a preference first, start a project alone or say no without a lengthy explanation. Relationships improve rather than suffer, since a partner meets the actual you.",
      "2": "Growth for you runs through the second house, towards your own money, skills and sense of worth, and away from the eighth-house South Node. You are used to intensity: other people's crises, debts, secrets and power games pull you in, and you often end up managing a drama that was never yours. There is a strange comfort in that turbulence. The North Node asks for something slower: building savings, sharpening a skill that pays, enjoying a good loaf of bread and a quiet Sunday. Patience feels dull at first, even suspicious. Once your own ground firms up, intimacy stops swallowing you and becomes a pleasure you choose.",
      "3": "With your North Node in the third house and the South Node in the ninth, your growth lies in the ordinary conversation rather than the grand theory. You are at home with big ideas, travel and belief, and it is easy for you to feel you already know how life works. The path keeps humbling that certainty. A neighbour's offhand remark, a sibling's story or a short evening course teaches you more than another book of philosophy. Listening properly, asking questions and noticing detail become your real work. Your wisdom grows truer once it survives the local bus stop and the family group chat.",
      "4": "Home and inner security are where the North Node in your fourth house points, while the tenth-house South Node keeps pulling you towards the public stage. You know how to achieve, and you are comfortable being judged by your title, your results or your reputation. On a free weekend, though, you can feel strangely lost, as if you do not exist without a task. Growth lies in building a home that feeds you, tending family bonds and letting private feelings count as much as public wins. Cooking for people you love, planting a garden or staying put in one place matters more than the next promotion. Success deepens once it rests on a life where you belong.",
      "5": "Your fifth-house North Node leads you towards joy, romance and personal creativity, away from an eleventh-house South Node that prefers the safety of the group. You are skilled at supporting a cause, fitting into a team and keeping your own desires politely out of sight. At a party you are the one making sure everyone else is having fun. Growth asks you to take the stage: to sing, paint, flirt, make something with your name on it and risk looking foolish. Children and love affairs teach you in unexpected ways. Your contribution to friends and causes becomes far more alive once you stop hiding your own heart inside them.",
      "6": "Practical service, healthy routine and useful work are the direction of your sixth-house North Node, while the twelfth-house South Node draws you towards retreat and dreaming. You slip easily into imagination, spiritual escape or sleep when ordinary demands pile up. Bills go unopened, and the inbox becomes a source of dread. The path asks you to organise your days, care for your body and turn compassion into concrete help. Making the bed, walking at the same hour, doing one job properly: these small habits become your spiritual practice. Your sensitivity steadies once it has a daily structure to live inside.",
      "7": "Partnership is the growth edge of your seventh-house North Node, with the South Node in the first house holding you in familiar self-reliance. You know how to do everything alone, and you often decide before anyone else has finished speaking. It feels efficient, yet it leaves you isolated and slightly surprised when people stop offering help. Growth arrives through committed relationships, collaboration and taking another viewpoint as seriously as your own. Partners act as mirrors, and what they reflect can sting. Letting someone share the decision about the holiday, the flat or the plan becomes an act of courage for you, and your sense of self grows richer for it.",
      "8": "Letting others close is the work of an eighth-house North Node, which leads towards intimacy, shared resources and transformation, away from a second-house South Node devoted to personal security. You are good at building comfort and holding on: to money, possessions, habits and a fixed idea of what you deserve. Showing someone your bank statement or your grief can feel almost unbearable. The path asks you to share power and money wisely, allow closeness and let things end when they have run their course. Therapy, research or a frank late-night conversation about death opens doors for you. Life grows more meaningful the moment control loosens.",
      "9": "Meaning and a larger view of life are where your ninth-house North Node leads, while the third-house South Node keeps you busy with information and small talk. You collect facts, messages and errands easily, and your days fill up before you notice. Yet at the end of a full week you can struggle to say what any of it was for. Growth comes through study, travel and forming a clear philosophy you are willing to stand behind. A foreign city, a gifted teacher or a spiritual tradition can shift your life decisively. Once you commit to a direction, your scattered interests gather into a coherent whole.",
      "10": "Public contribution and career form the direction of your tenth-house North Node, with the fourth-house South Node holding you close to home and family. You know how to look after a household, and familiar roles like the dependable one or the family peacemaker feel safe. Stepping into public view can feel exposing, almost disloyal. Growth comes from setting ambitious goals, accepting authority and building a reputation that reflects your values. Applying for the senior role, signing your name to the proposal, speaking up at the meeting: each is a concrete step. Private life grows more secure, not less, when you have a purpose beyond it.",
      "11": "An eleventh-house North Node draws you towards friendship, community and shared ideals, away from a fifth-house South Node that loves the spotlight. You know how to be the centre of attention, and romance, creative recognition or personal drama have often filled your life. Being one voice among many can feel like disappearing. Growth comes through joining groups, working for causes bigger than you and valuing friends as highly as lovers. A community garden, a campaign or a circle of like-minded people widens your world in ways a love affair never could. Your creativity finds its truest outlet when it serves something collective.",
      "12": "Your growth turns inward with a twelfth-house North Node, towards surrender, spirituality and inner life, while the sixth-house South Node keeps you busy, useful and in control. You are skilled at analysis, lists and routine, and you tend to feel anxious the moment there is nothing to fix. Rest can feel almost like failure. Growth asks you to make room for solitude, dreams, compassion and the parts of life that cannot be measured. A silent retreat, a morning spent painting with no goal, or an honest look at a recurring dream teaches you more than another efficiency plan. Peace arrives as you trust what you cannot control."
    }],
    ["houses.*.empty", {
      "1": "An empty first house is common, and it says nothing about a faint personality. You still walk into a room with a recognisable manner, and your Ascendant sign describes it: the first impression, the way you greet a stranger, the pace you move at. With no planets crowding this house, that front door is less loaded, and people meet you without a flood of competing signals. Your sense of self gets worked out elsewhere, in the house where the planet ruling your Ascendant lives. If that ruler sits in the tenth, you discover who you are through work; in the fourth, through family. Following that thread shows where you become yourself.",
      "2": "No planets in your second house does not mean money is unimportant to you; it is a less dramatic theme. You earn, spend and save without the constant churn some people live with. The sign on the cusp describes your natural money style, whether careful and slow, impulsive and generous, or practical and planned. The planet ruling that sign points to where your income is generated, often somewhere surprising, like friendships or a hobby. Self-worth works the same way: you build it through that ruler's area of life. When finances wobble, it is there, not here, that you find the lever.",
      "3": "An empty third house says nothing about poor communication or a quiet mind. You still chat, text, learn and move around your neighbourhood like anyone else, and the cusp sign colours how you do it: brisk and factual, warm and chatty, or slow and careful. With no planets here, siblings and daily errands are less likely to become the stage for major life events. The ruler of the cusp shows where your curiosity lives, and which topics keep you reading late. If it falls in the eighth, you are drawn to hidden subjects; in the sixth, to practical know-how. Your mind is busy, just focused elsewhere.",
      "4": "When your fourth house holds no planets, home and family are less of a battleground or preoccupation for you. You still need a place to land at night, and the cusp sign describes that private need: a quiet flat, a noisy kitchen full of people, or a room of your own with a door that locks. Family history is present in your life even if it rarely makes headlines. The ruler of the cusp shows where you find belonging, which could be your workplace, a partnership or a circle of friends. Many people with this pattern build their sense of home through chosen bonds. Emotional ground is there for you, placed somewhere unexpected.",
      "5": "An empty fifth house says nothing about a lack of love, fun or creativity. You still flirt, play and make things, and the sign on the cusp describes your natural style: theatrical, witty, tender or crafted. Without planets here, romance and children are less likely to dominate your story or bring dramatic twists. The ruler of the cusp tells you where your heart comes alive most readily. With it in the ninth, travel and learning light you up; in the second, cooking, making or collecting. Joy shows up for you there first, and following that planet is the surest way to find more of it.",
      "6": "An unoccupied sixth house means daily work and health are a quieter arena for you rather than an absent one. You still have routines, a job to show up to and a body that needs care, and the cusp sign describes the rhythm that suits you best. Some weeks that is a strict timetable, other weeks a loose list scribbled on the back of an envelope. The ruler of the cusp shows where your practical effort goes, whether into home improvement, creative work or looking after someone. Habits form most easily when they connect to that area. Fewer planets here often means fewer battles with routine, not fewer duties.",
      "7": "Many long, happy marriages happen with an empty seventh house, so this placement says nothing about a life without partnership. You still want someone beside you, and the Descendant sign describes what draws you: the steady type, the brilliant talker, the one who makes you laugh. Without planets here, relationships are less likely to be a constant arena of drama. The ruler of the Descendant shows where you tend to meet partners and what shared life looks like. If it sits in the sixth, you meet people at work; in the ninth, abroad or while studying. Partnership still shapes your life, arriving through that door.",
      "8": "Crisis, intimacy and depth still arrive when your eighth house is empty, often through other areas of life. You grieve, merge finances with someone and face hard truths like anyone else; they are less likely to become your permanent address. The cusp sign shows your style of intimacy and how you meet loss, whether with quiet endurance, sharp analysis or open emotion. The ruler of the cusp shows where transformation usually begins for you. With it in the third, a single conversation can change everything; in the tenth, a career upheaval does the work. Deep change still visits, and you recognise it by that route.",
      "9": "Faith, curiosity and the hunger for meaning are fully present with an empty ninth house. You still wonder about the big questions and feel pulled by distant places, and the cusp sign describes your natural philosophy: sceptical, devout, adventurous or practical. Without planets here, long journeys and higher study are less likely to define you. The ruler of the cusp reveals where you seek meaning. If it falls in the sixth, you find it through daily work; in the seventh, through a partner who widens your world. Your beliefs take shape in that area, often more quietly than you expect.",
      "10": "Many charts have an empty tenth house, and it says very little about career success. You can still build an impressive reputation, and your Midheaven sign describes the public style people associate with you: reliable, inventive, caring or commanding. With no planets here, your career is less likely to be a single fixed identity from youth, and you often change direction more freely than others. The ruler of the Midheaven shows where your ambitions take shape day to day. In the third, your vocation runs through writing or teaching; in the twelfth, through behind-the-scenes or healing work. Your calling is real, and following that ruler reveals it.",
      "11": "Friendships can be plentiful even with no planets in your eleventh house. You still belong to groups, chats and communities, and the cusp sign describes how you connect with them: loyal and selective, sociable and wide, or useful behind the scenes. Without planets here, the crowd is less likely to swallow your personal identity. The ruler of the cusp shows where your friendships and future goals form. With it in the fifth, friends come through play and creativity; in the tenth, through work and shared ambition. Your hopes for the future grow in that same place, often alongside the people you meet there.",
      "12": "Your inner life can be rich even when the twelfth house holds no planets. You still need solitude, dream vividly and feel the pull of something larger, and the cusp sign describes how you retreat and recover, whether through sleep, music, nature or prayer. Without planets here, hidden patterns trouble you less, or at least less secretly. The ruler of the cusp shows where those patterns surface and where spiritual growth happens. In the seventh, a partner holds up the mirror; in the second, your relationship with money reveals what lies underneath. Quiet time matters for you, even when it rarely makes a fuss."
    }],
    ["planetSigns2.uranus.*.text", {
      "aries": "Uranus sat in Aries from 1927 to 1935 and again from 2010 to 2019, and you share its restless charge with everyone born in those years. In your own life it shows up as a physical allergy to being told what to do: the moment a rule arrives without a reason, you are already halfway round it. You start things on impulse, a new hobby bought in full on a Tuesday, a plan announced to friends before you have slept on it. That speed is a gift when a situation is stuck and someone has to move first. The cost is the trail of half-finished starts and the people who felt steamrollered by your sudden changes of direction. Breaking ground nobody has touched makes you feel fully alive, and waiting your turn makes you feel caged.",
      "taurus": "Born while Uranus moved through Taurus, from 1934 to 1942 or from 2018 to 2026, you carry a trait everyone your age shares: a sense of security that keeps being rewritten. For you it shows up as a quiet, stubborn loyalty to what you have, the same mug, the same route, the same bank, until one day you sell the lot and start again. Friends are startled by these overhauls, because the build-up happened silently. Money and possessions matter to you in unconventional ways; you would rather own a patch of garden you grew yourself than a smart car. The difficulty is how long you hold on to something that has stopped working, then how violently you let it go. Underneath it all you are after a way of living that feels steady and still belongs to you alone.",
      "gemini": "Uranus in Gemini marks people born from 1941 to 1949, and again from 2025 to 2033, and you share its quick, electric mind with them. Ideas arrive for you in flashes, in the shower or halfway through someone else's sentence, and you want to chase each one immediately. You learn by taking things apart: a new gadget, a new language, a new argument, poked at until it gives up its secret. Conversation with you jumps tracks, which friends find thrilling on a good night and exhausting on a tired one. The real struggle is focus, the six open tabs, the book abandoned at chapter three, the brilliant idea nobody hears about because you have already moved on. Wherever words, signals and information are changing fastest, you want to be in the thick of it.",
      "cancer": "Uranus passed through Cancer from 1948 to 1956 and returns from about 2033 to 2039, and like others born in those years you carry a restless relationship with home. Your family set-up looked a little unusual from the outside, or you made sure the one you built did. You love fiercely, yet you need a door you can close, a kitchen arranged your way, permission to leave for a weekend without explaining. A few days at your parents' can leave you oddly jumpy, as if the old walls are pressing in. The pull between wanting to belong and wanting out is the real tension here, and it can make you run hot and cold with the people closest to you. A home that feels chosen rather than inherited is the thing you keep building towards.",
      "leo": "Uranus crossed Leo from 1955 to 1962 and will return from about 2039 to 2046, so your hunger to stand out is one you share with people born alongside you. In daily life it looks like the outfit nobody else would risk, the song you write at midnight, the flat refusal to tone yourself down for a room. You light up when you are allowed to create something entirely your own, and you bristle the second anyone tries to direct your performance. Romance arrives for you like weather, sudden and dazzling, and it can leave just as fast. Recognition feels essential to you, so a quiet stretch with no audience can knock your confidence harder than you admit. You shine brightest when you are seen as you are, with no edits.",
      "virgo": "Your Uranus in Virgo, from 1961 to 1969, links you with a generation born alongside the space race and the spread of computers. Personally it gives you an itch to improve how things work: you rewrite the office spreadsheet, reorganise the shed, find the faster route everyone else ignored. Routines imposed by someone else feel like a cage, yet the ones you invent yourself you follow with devotion. You are often the person who tries the unusual diet, the new tool or the alternative treatment first, then reports back in forensic detail. Where it goes wrong is the constant tinkering, the sense that nothing is ever quite finished, and the nervous energy that shows up in your body when you cannot fix something. Clever, useful change is what you want to leave behind you.",
      "libra": "Uranus was in Libra from 1968 to 1975, and you share its restless view of love and partnership with everyone born in those years. You want closeness and you want air, and you tend to feel both needs at once, sometimes in the same evening. Your relationships rarely follow the expected script: an unusual partner, separate flats, a friendship that turned into something else, or an ending that came out of nowhere. Fairness matters to you almost physically, and you notice immediately when one person is doing all the giving. The tricky part is that you can leave before you are left, mistaking the urge for freedom for a sign that the bond is wrong. Two equals who each keep their own shape is your picture of love that works.",
      "scorpio": "The taboo breaking of 1974 to 1981, when Uranus moved through Scorpio, runs through you as it does through everyone born then. You cannot leave a secret alone: the family silence, the thing everyone at work pretends not to see, the reason behind the reason. Your emotional life has sudden drops in it, weeks of calm and then a night when everything cracks open and you rebuild from the floor up. You trust hidden power very little, and you can smell manipulation before a word is spoken. The cost is that you go looking for intensity and treat calm as a warning sign. Other people's avoided subjects are where you are most at home, and you often become the one who says them out loud.",
      "sagittarius": "Uranus crossed Sagittarius from 1981 to 1988, and briefly at the start of the twentieth century until 1904, and you share its restless search for meaning with people born around your time. You grew up with a wider world than your parents had, and you act like it: the gap year that became three, the degree abandoned for something learnt on the road, the belief you swapped overnight after one conversation. Being handed a creed feels intolerable to you, even a well-meant one. Your convictions change suddenly and completely, which keeps you honest and also leaves friends struggling to keep up. The pitfall is restlessness dressed up as philosophy, moving on whenever things get ordinary. Anywhere that lets you think freely and see further feels like home.",
      "capricorn": "Your Uranus in Capricorn, from 1904 to 1912 or from 1988 to 1996, ties you to a generation born as walls, governments and career ladders were being torn down and rebuilt. In your own life that shows up as ambition with a rebellious edge: you want to build something solid, but you want to build it your way. Job descriptions, hierarchies and \"how we have always done it\" make you quietly furious. You are the one who starts a side business at twenty-five, or who stays inside the institution and changes it from within. Trouble comes because you distrust authority even when you become it, and you can wear yourself out fighting structures you secretly want to belong to. Lasting work that breaks the old rules is what keeps you going.",
      "aquarius": "Uranus was at home in Aquarius from 1912 to 1919 and again from 1995 to 2003, and you share its networked, independent spirit with everyone born in those years. You think in systems and groups: group chats, online communities, friendships spread across cities and time zones. Your mind can be strikingly original, and you often see the fix to a shared problem before anyone else has noticed the problem. Even among friends you keep a little distance, the observer at the party enjoying it from slightly outside. That detachment protects you, and it can also leave people feeling you are with everyone and close to no one. Changing how the whole system works, not just your corner of it, is the ambition you carry quietly.",
      "pisces": "From 1919 to 1927 and again from 2003 to 2011, Uranus drifted through Pisces, and you share its dreamy, boundary-blurring streak with the people born around you. Your imagination runs on sudden flashes: an image, a melody, a feeling about someone that turns out to be right. You move easily between the real and the imagined, a game world, a playlist, a fictional character you feel closer to than some people. Suffering you see, on a screen or in a stranger, lands in you hard and fast. The weakness is overwhelm when too many possibilities arrive at once, so you escape into a feed or a daydream rather than choose. Given creative freedom and room to follow your intuition, you make something nobody else could have imagined."
    }],
    ["planetSigns2.neptune.*.text", {
      "aries": "Neptune entered Aries in 2025 and stays until about 2039, after a previous visit in the 1860s and 1870s, and you share its dream of courage with everyone born in these years. In your own life idealism wants to become action: you imagine something better and you want to be the one who goes out and fights for it. Heroes matter to you, real or invented, and you model yourself on them more than you let on. You feel other people's struggles in your body and respond by stepping in, standing up, starting a campaign in the playground. The trouble is that you can glamorise conflict or lose your sense of who you are inside the cause. Pioneering suits you best when your ideals stay tied to the ground.",
      "taurus": "Neptune moves into Taurus around 2038 to 2039 and stays until about 2052, having last been there from the 1870s to the late 1880s, and your dream is one you share with everyone born in that stretch. For you it centres on the physical world: the smell of rain on soil, bread you made yourself, a piece of music you play until you know every breath in it. You find something close to the sacred in simple things and slow days. Your idealism is gentle and steady rather than loud. The weak spot is money and comfort, which you can idealise or blur, drifting into spending or into a softness that avoids hard choices. Peace through simplicity, and a lasting bond with land and living things, is where your heart settles.",
      "gemini": "Neptune was in Gemini from the late 1880s until 1902, while the telephone, cinema and wireless spread, and you share its dreamy, restless mind with everyone born in those years. Your mind is poetic and porous; you pick up ideas as if from the air and repeat stories until they become part of you. Words and images feel faintly magical to you, and a good tale moves you more than a hard fact. You are the one who remembers the song, the rhyme, the line from a picture show decades later. The drawback is a looser grip on details, and a suggestibility that can let someone else's version of events become yours. Language, story and the imagination in ordinary talk are where you are most alive.",
      "cancer": "Neptune was in Cancer from about 1901 to 1915, and you share its romantic ideal of home and homeland with everyone born in those years, a dream the First World War soon broke. In your own life that shows up as an uncanny feel for the mood of a household: you walk into a kitchen and know who has quarrelled. You long for an ideal family and a place of perfect belonging, and you give generously to make it real. Old photographs, a grandmother's recipe, a song from childhood can undo you completely. The hard part is blurred boundaries with relatives and a nostalgia that makes the past seem gentler than it was. Offering refuge, and finding it, is what your whole life bends towards.",
      "leo": "Like everyone born while Neptune crossed Leo, from 1914 to 1929, you grew up alongside Hollywood, jazz and the glamour of the silver screen. For you it means a romantic heart and an imagination that thinks in scenes: the entrance, the grand gesture, the song played at the right moment. You put leaders and lovers on pedestals and adore them there, sometimes for years. Creativity feels like your native language, whether it comes out in dancing, dressing or telling a story at dinner. The pain comes when the person behind the image turns out to be ordinary, and the disillusionment can be sharp. You long to shine and to inspire, and you do it best with real people rather than the fantasy of them.",
      "virgo": "Neptune was in Virgo from 1928 to 1943, and you share its ideal of duty and quiet sacrifice with a generation born through the Depression and into the Second World War. In your own life it shows as a compassion that wants to be useful: you mend, tidy, nurse and make do, often without being asked. Care for you is practical, a meal left on a doorstep or a hem taken up overnight, and the healing professions often call you. The shadow is a vague anxiety about health and a sense that you must earn your place with endless effort. Perfectionism can dissolve your confidence, leaving you never quite satisfied with the job. Service that heals others without costing you yourself is the balance you spend years learning.",
      "libra": "Neptune was in Libra from about 1942 to 1957, and like others born around the end of the war and into the baby boom, you grew up with a dream of love, peace and equality. For you it shows up as a romantic view of partnership and a fine eye for beauty, the right painting on the wall, the table laid properly for guests. You believe people can get along, and you work hard to make it true, often as the peacemaker in your family or street. Injustice between people upsets you for days, and it has drawn you towards causes larger than yourself. The difficulty is disappointment when a real relationship fails to match the one you imagined. Harmony built with realism as well as hope turns out to be the kind that lasts for you.",
      "scorpio": "A hunger for hidden truth links you with everyone born while Neptune was in Scorpio, from about 1956 to 1970, a generation raised on the sexual revolution, psychedelics and a new openness about death and the psyche. Your intuition runs deep: you sense what someone is not telling you, and you are drawn to therapy, mystery and the parts of life other people avoid. Intimacy for you is close to spiritual, a merging rather than a meeting. Grief and love transform you far more than success does. The shadow is escapism and intensity for its own sake, the late night that goes too far, the relationship that thrills because it hurts. Once the illusions around power and closeness fall away, your gift for healing becomes very real.",
      "sagittarius": "Neptune crossed Sagittarius from 1970 to 1984, and you share its seeker's dream with a generation raised on long-haul travel, new-age spirituality and a widening menu of beliefs. You build your own faith from pieces: a practice from one tradition, a book from another, a teacher met on a beach somewhere. Organised religion leaves you cold, yet you long for something to believe in, and you inspire others when you talk about what you have found. You are the friend with the stamps in the passport and the half-finished philosophy course. The risk is chasing the next guru or big idea, each one promising the answer the last one did not deliver. Meaning that still holds when you come home is the real prize for you.",
      "capricorn": "Neptune moved through Capricorn from 1984 to 1998, and you share its uneasy dream about structure with a generation born as the Soviet Union fell and the job for life disappeared. You want success, but you want it to mean something, and a title alone leaves you strangely empty. You know the feeling of sitting in a meeting and sensing the whole institution is a performance nobody believes in. That disillusionment with authority can leave you unsure what you are working towards. At your best, though, you combine idealism with patience and build businesses, careers or communities grounded in shared values. You learn, sometimes painfully, that structures are only as solid as their foundations, and so you dig yours deep.",
      "aquarius": "Neptune was in Aquarius from 1998 to 2012, and like everyone born in those years, you arrived in a world of social media, smartphones and constant connection. You feel spiritually linked to causes and communities, including people you have never met in person. You sense what a group needs, the mood of a chat, the thing a campaign is missing, and you care about humanity as a whole with feeling. Online belonging can feel as real to you as a friend across the table. The difficulty is telling the two apart, and noticing when a following or a feed has replaced the closeness you wanted. A better collective is your dream, and friendships that are real as well as ideal make it possible.",
      "pisces": "Neptune was at home in Pisces from 2012 until 2026, its first visit since the 1860s, and you share its porous sensitivity with everyone born in those years. You arrived amid streaming, climate awareness and a heightened feeling for the pain of the world, and you feel other people's moods as if they were your own. Stories, art and music can move you to tears, and you slip easily into imagined worlds. You cry at the film, you worry about the stray animal, you notice the child sitting alone. The challenge is overwhelm: you escape into screens or daydreams when life gets too loud, and the line between fact and fiction can blur. Gentle, clear boundaries turn your empathy and imagination into gifts."
    }],
    ["planetSigns2.pluto.*.text", {
      "aries": "Pluto was last in Aries from 1822 to 1853 and returns only around 2066 to 2098, so nobody born between 1900 and 2045 carries it; if you do, you share it with a generation of raw beginnings. That earlier generation lived through revolutions across Europe and the rise of industrial power. For you it means a drive to overturn the old order single-handedly, and a survival instinct that switches on the instant you are threatened. You would rather start again from nothing than live on someone else's terms. The cost is a temper that burns bridges and a habit of treating every obstacle as an enemy. Claiming your own power, and starting over as often as it takes, is the fire that drives you.",
      "taurus": "Pluto was last in Taurus from about 1851 to 1884 and returns only in the 2090s, so nobody born between 1900 and 2045 carries it; if you do, you share it with a generation that saw industry reshape land, labour and wealth. In your own life it shows as a deep, stubborn instinct to hold on to what is yours: land, savings, the house you built. You gather power slowly and patiently, and you do not give it up without a fight. Security matters to you at gut level, and loss can feel like a threat to your survival. The real test comes when you have to let go of possessions or comfort, and learn you remain yourself without them. Lasting value, built by your own hands, is your life's quiet project.",
      "gemini": "Pluto was in Gemini from about 1884 to 1914, so you share it with people born in the first years of the 1900s, a generation that saw cars, flight, telephones and mass newspapers turn information into power. Your mind is penetrating and investigative, and you cannot rest until you understand how something works. A single conversation, a letter or a newspaper story can change the course of your life. Words carry enormous weight for you; you remember what was said, and by whom. The shadow is obsessive thinking, going over the same argument at night until it grows teeth. Saying the right thing at the right moment is your hidden power, and you learn to use it.",
      "cancer": "Two world wars, the Depression and the collapse of old family and national structures shaped everyone born while Pluto was in Cancer, from 1913 to 1939, and you share that inheritance. In your own life it shows up as a fierce, protective love: you would go without so your children or siblings could eat, and you remember every threat to your home. Your emotional bonds are powerful and long-lasting, sometimes to the point of possessiveness. Family history sits heavily in you, the things never discussed, the grief carried down from parents. Unresolved hurt from those years can make you guarded or hard to reach. Keeping your people safe comes first, and in time you transform the old patterns you inherited.",
      "leo": "Pluto was in Leo from about 1937 to 1958, overlapping the baby boom, and you share its drive for self-expression with everyone born in those years. Your generation grew up in post-war prosperity and turned personal ambition and rock music into cultural forces. In your own life it gives a magnetic presence and a deep need to leave a mark: the business with your name on it, the stage, the family story that centres on you. Your will is strong, and when you decide something, the room reorganises around you. Pride is the weak point, along with the struggle to share the spotlight or step aside for someone younger. Life tests your ego again and again, and each time it comes back wiser.",
      "virgo": "Pluto moved through Virgo from about 1956 to 1972, and you share its drive to improve things with a generation born as computing, automation and modern healthcare took off. You have a sharp analytical mind and very high standards; you spot the flaw in the plan, the error in the bill, the inefficiency everyone else tolerates. Work matters enormously to you, and many people born with this became reformers in offices, ecology or medicine. You can reorganise a failing system from the ground up. The hard edge is anxiety or control around health, food and routine, and a perfectionism that leaves you exhausted. Meticulous rebuilding, done with a softer hand towards yourself, is where your power lies.",
      "libra": "Pluto was in Libra from about 1971 to 1984, and you share it with a generation born as divorce became common and the rules of marriage and gender shifted. Relationships change you more than anything else: each serious partnership leaves you a different person. You are acutely aware of power between two people, who gives, who decides, who apologises first. Justice matters to you, and you often have a gift for mediation, law or reading both sides of an argument. The difficult side is intense partnerships where control and fairness get tangled, and a hunger to know how others see you. An honest balance of power, in love and in the wider world, is what you keep fighting for.",
      "scorpio": "Pluto was at home in Scorpio from about 1983 to 1995, its most intense placement, and you share it with a generation raised amid the AIDS crisis, financial deregulation and growing awareness of environmental and psychological damage. You have profound emotional depth, and you know what is hidden in a room long before it is said. Life for you moves in cycles of ending and renewal: jobs, friendships and whole identities burn down and you rise again. Your resilience is remarkable, even if you rarely show how much it cost. The darker pull is towards secrecy, control and extremes, the all-or-nothing loyalty and the grudge kept for years. Facing what others avoid is where your strength comes from.",
      "sagittarius": "Pluto was in Sagittarius from 1995 to 2008, and you share it with a generation raised on the global internet, cheap flights and the clashing belief systems that followed 2001. You have intense convictions and a love of big ideas, and you argue for them passionately at the dinner table or online. Freedom matters to you deeply, and you want to see the world for yourself rather than take anyone's word for it. Your beliefs are tested and remade, sometimes after one trip, one book or one conversation. The risk is extremism or sudden disillusionment, swinging from certainty to cynicism. Over time you build a perspective far larger than the one you were raised with.",
      "capricorn": "Pluto moved through Capricorn from 2008 to 2024, and you share it with a generation born after the global financial crisis, into eroding trust in banks, governments and corporations. You carry an early sense of responsibility: even as a child you notice when money is tight or when the adults are not in control. Serious ambition and strategic thinking come naturally, and you plan further ahead than people expect of someone your age. You watch authority closely and do not assume it deserves respect. The heavy side is a fear of failure and a need for control that can make you rigid or anxious. Dismantling what no longer works and rebuilding it properly is the job you were born for.",
      "aquarius": "Pluto entered Aquarius in 2023 to 2024 and stays until about 2044, and you share it with a generation born into artificial intelligence, decentralised networks and new forms of collective power. Its previous visit, from 1777 to 1798, was the age of the American and French revolutions. In your life it brings visionary thinking and a strong loyalty to your group: the friends, the network, the movement. You see how outdated systems could be overturned, and you would rather do it together than alone. Detachment or groupthink is the danger, when the collective's view drowns out your own. Radical change, with a say in the shape of the world, is what you grow up expecting.",
      "pisces": "Pluto enters Pisces around 2043 to 2044 and stays until the late 2060s, so only the youngest people born before 2045 have it; if you do, you share it with a generation whose power works through imagination and empathy. Its last visit, from 1797 to 1823, was the era of Romanticism. You have deep psychic sensitivity: you feel the grief of strangers, you dream vividly, and you know things you cannot explain. A capacity for healing lives in you, and people bring you their pain without quite knowing why. The vulnerability is escapism, dissolving into fantasy or other people's needs when reality gets too hard. Surrender, for you, becomes the doorway to renewal of belief and compassion."
    }],
    ["dominants.weak", {
      "sun": "With a quiet Sun, your sense of who you are took its time to arrive, and for years you described yourself through the people around you: someone's partner, someone's helper, the reliable one at work. Asked what you want for your birthday, your mind goes briefly blank. You are generous with attention and slow to claim the centre of a room, which makes you easy company and hard to see. Other people's plans fill the space your own purpose should occupy, and you notice the resentment before you notice the cause. Confidence grows in you through doing things that belong to nobody else. When it does, your warmth gains a spine, and people start asking for your opinion first.",
      "moon": "A quiet Moon means your feelings often reach you late, sometimes days after the event, surfacing as tiredness or a short temper over something small. You are the friend who says \"I'm fine\" and believes it at the time. Looking after others comes easily; letting anyone look after you feels awkward, even slightly embarrassing. You can get through a crisis with remarkable composure, and people lean on that steadiness. The cost is that your own needs go unspoken until they arrive all at once, leaving those close to you guessing. As you learn to catch the small signals, a heavy chest or a craving for familiar food, you discover a tenderness in yourself that was there all along.",
      "mercury": "With Mercury quiet in your chart, you think in pictures, sensations and hunches before you think in sentences. In a meeting you know the answer is wrong long before you can explain why, and by the time the words arrive the conversation has moved on. Forms, emails and small talk drain you more than they should. Yet your understanding runs deep, and once you have grasped something with your hands or your gut, you keep it for life. What stings is being underestimated by quicker talkers who say less than you know. Given time, a sketch or a practical demonstration, you explain things in a way that stays with people far longer than a clever phrase.",
      "venus": "A quiet Venus makes receiving the hardest part of love for you. Compliments slide off, gifts leave you faintly uncomfortable, and you would rather cook for ten people than be taken out for dinner yourself. Pleasure has to be earned in your mind, so the long bath, the new coat or the afternoon off gets postponed until everything else is done. You are loyal, undemanding and easy to please, qualities partners value highly. Underneath, a quiet doubt about your own worth makes you settle for less than you give. Once you let yourself be enjoyed, without apologising or paying it back immediately, your relationships gain the softness and mutual ease you have always offered others.",
      "mars": "When Mars is quiet, anger rarely shows on your face. You swallow the irritation in the queue, agree to the extra shift, and replay the argument you did not have on the drive home. Pushing for what you want feels crude, so you wait to be offered it, and sometimes the offer never comes. Your patience and restraint make you a calming presence in any tense room. Suppressed fire has to go somewhere, though, and it turns into fatigue, sarcasm or a sudden outburst that surprises everyone, including you. Each time you state a plain preference and let the room survive it, your energy returns, and the rest of your chart has an engine behind it.",
      "jupiter": "A quiet Jupiter makes you the realist in the group, the one who checks the small print and quietly assumes the good news will not last. You rarely buy the raffle ticket or apply for the job you are not quite qualified for. This caution protects you from plenty of bad bets, and people trust your sober judgement. The loss is subtler: opportunities pass because you did not expect to be chosen, and celebrations feel slightly undeserved. Joy reaches you in small, private doses rather than grand leaps. When you allow yourself one bold hope and act as though it could come true, luck starts showing up with surprising regularity.",
      "saturn": "With Saturn quiet, structure is something you borrow rather than something you carry. You work brilliantly to a deadline someone else sets, yet your own plans drift, the tax return waits until the last night, and the gym membership lapses by February. Rules feel arbitrary to you, and you would rather improvise than follow a system. That looseness makes you flexible, forgiving and refreshingly unburdened by other people's expectations. The price shows up over years rather than weeks: talent without scaffolding scatters, and you watch less gifted people overtake you through sheer persistence. A few plain routines, kept without drama, give your gifts the frame they have always needed to last.",
      "uranus": "Uranus sits quietly in your chart, which gives you a strong preference for the familiar: the same café, the same route to work, the phone you have had for years because it still works. Sudden change unsettles you more than it unsettles most people, and a cancelled plan can throw the whole day. You are dependable, consistent and blessedly free of the need to be different for its own sake. Trouble comes when life changes without permission, through a restructure, a move or a breakup, and you have had little practice at improvising. Small, deliberate experiments, a new recipe or an unfamiliar holiday, build the flexibility you lack. Over time surprise starts to feel like freedom rather than threat.",
      "neptune": "With Neptune quiet, you live firmly in the real world. You read the contract, spot the flaw in the romantic plan and struggle to switch off long enough to daydream. Vague spiritual talk leaves you cold, and you prefer evidence to faith. That clarity is valuable: you are hard to fool, rarely lost in illusion and good at rescuing others from theirs. Yet something in you goes hungry when every hour has to be useful. Rest feels like wasted time, and music, water or art get squeezed out of the week. Given unstructured hours to drift, you find an imagination richer than you suspected, and a peace that effort alone never delivered.",
      "pluto": "Pluto is low-key in your chart, making intensity something you would rather avoid. You change the subject when a conversation turns raw, leave the party before the confessions start, and prefer relationships that stay pleasant rather than probing. You are easy to be around and rarely drawn into power struggles or obsession. The underside of that ease is avoidance: difficult truths wait in the cupboard until a crisis forces the door open, and then the change feels enormous. Facing hard things in small, steady doses, one honest conversation at a time, gives you a different kind of strength. It is quieter than the dramatic transformations others describe, and it lasts."
    }],
    ["dominants.houses", {
      "1": "With the first house most emphasised, your life keeps circling back to who you are and how you show up. People notice you when you walk in, even on days you are trying to blend into the background. You would rather do it your own way than follow a script, and you feel most alive starting something on your own terms. Your appearance, energy and first impressions carry unusual weight, so a new haircut or a fresh start can lift your whole mood. On a bad day every setback feels like a verdict on your worth, and self-absorption creeps in. Growth comes as you become more fully yourself, and others find permission in watching you do it.",
      "2": "When the second house leads your chart, much of your life revolves around what you have, what you value and what you are worth. You know your bank balance to the pound and feel steadier with savings behind you. Quality objects, good food and physical comfort matter to you, and you can spot fine craftsmanship at a glance. You build slowly and keep what you build. Measuring yourself by possessions or income is the trap, along with clinging to security long after it has stopped serving you. Your deepest work is discovering that self-worth is something you carry rather than something you earn, and once you do, money tends to follow more easily.",
      "3": "A dominant third house makes your life a running conversation. You read the back of the cereal box, text three friends before breakfast and know the name of everyone on your street. Ideas, news and gossip move through you quickly, and you are often the person who introduces two people who needed to meet. Siblings, neighbours and short journeys shape your story more than you expect. A restless mind can skim the surface, and your talent for words sometimes talks around feelings instead of through them. Curiosity committed to one subject for long enough turns your voice into the thing people remember.",
      "4": "With the fourth house most emphasised, home is where your life is lived. You can walk into a room and know within seconds whether it feels right, and you rearrange the furniture whenever your inner world shifts. Family, ancestry and the kitchen table conversations of childhood shape you more than any career. You create belonging for others with ease, and your house often becomes the place where everyone gathers. Retreating into the familiar is the pull to watch, along with carrying old family patterns unexamined or feeling unmoored after every move. Your strength grows from secure roots, and once you have built them, you can go almost anywhere.",
      "5": "When the fifth house dominates, you need joy the way other people need sleep. You fall into love, hobbies and creative projects with your whole heart, and a week without play leaves you flat and irritable. Children, performance, games and romance light you up, and people are drawn to your knack for making ordinary evenings feel like occasions. You shine when you are making something that carries your own signature. Needing applause can take over, and so can the thrill of beginnings, leaving the long middle of things to wither. Your life is richest when you treat delight as essential rather than as a reward saved for later.",
      "6": "A dominant sixth house puts your days, your work and your body at the centre of life. You notice when the printer is jammed and fix it before anyone asks. Lists, routines and small improvements satisfy you enormously, and colleagues rely on you to know how things get done. Your health responds quickly to stress, sleep and diet, and you learn to read those signals well. Perfectionism is the snag, together with over-working and feeling useful only when busy. Routines that serve you rather than rule you make daily life a quiet craft, and your competence turns into service.",
      "7": "With the seventh house most emphasised, you discover yourself through other people. Your biggest turning points arrive through partners, business allies, close friends and sometimes open rivals. You instinctively consider the other person's view, and you are often the one who smooths the tension at the dinner table. Being single, or working alone, can feel oddly incomplete. Defining yourself by who you are with is the danger, as is giving more than you receive or projecting your own qualities onto a partner. Each close relationship works as a mirror, and the more honestly you look, the more clearly you meet yourself.",
      "8": "When the eighth house dominates, you are drawn to what sits beneath the surface. Small talk bores you; you would rather hear the real story at two in the morning. Intimacy, shared money, inheritance, secrets and loss all play outsized roles in your life, and crises have a way of changing you completely. People confide in you because they sense you will not flinch. Control and suspicion can creep in, and so can a hunger for intensity that makes calm feel empty. Your power lies in regeneration: you have come through endings that would flatten others, and you emerge from each one knowing yourself more truly.",
      "9": "A dominant ninth house makes your life a search for meaning. You buy the book after the museum visit, plan trips to places others have never heard of, and argue about philosophy long after everyone else has gone to bed. Travel, study, faith and foreign cultures stretch you in ways ordinary routine never can. You are a natural teacher, and your enthusiasm for big ideas is infectious. Restlessness and preaching are the pitfalls, and chasing the next horizon can mean never settling into the present one. Your growth comes from living your beliefs as fully as you speak them.",
      "10": "With the tenth house most emphasised, your direction in life matters enormously to you. You were probably asked what you wanted to be long before your friends were, and you have been working towards some version of an answer ever since. Reputation, achievement and visible contribution drive you, and you feel restless in roles that give you no chance to rise. People often see you as more senior or more capable than you feel. Tying your worth to your title is the trap, along with sacrificing private life for public standing or carrying a parent's ambitions as your own. Work that reflects who you are is what makes success feel earned and satisfying.",
      "11": "When the eleventh house leads, your life is shaped by the people you gather around you. Friends, networks, clubs and causes matter to you as much as family, and the right group can change the course of a year. You think about the future and what could be improved, often holding ideals that seem ahead of their time. You are the person who starts the group chat and remembers everyone's news. Losing yourself in the crowd is one hazard; feeling like an outsider even among your own people is another. Connected to a community that shares your hopes, you achieve far more than you ever could alone.",
      "12": "A dominant twelfth house gives you a rich, hidden inner life. You need time alone the way others need company, and after a crowded day you recover in silence, water or sleep. You pick up atmospheres, sense what goes unsaid and sometimes absorb other people's moods before realising they are not your own. Dreams, intuition, spirituality and quiet service speak to you. Escapism and self-sacrifice are the risks, along with a habit of disappearing when life becomes too loud. Your deepest growth happens behind the scenes, and what you bring back from those quiet places carries a compassion others feel without being able to name."
    }],
    ["retro", {
      "mercury": "Mercury retrograde at birth makes your mind circle back before it moves forward. You replay conversations in the shower, rewrite the email three times and remember what someone said last spring. At school you probably seemed slow, when in fact you were checking every step for yourself. Your thinking is original because it refuses to take ideas at face value. Fast exchanges are where it hurts: the perfect reply arrives an hour too late, and quicker talkers mistake your pause for uncertainty. Writing, research and reflection give your intelligence its full range, and over time your ideas turn out to be the ones that last.",
      "venus": "Venus retrograde at birth turns your love life and your taste inward. Your standards rarely match what your friends find attractive, and you often love the unfashionable, the old or the overlooked. Romance tends to arrive late, in unusual forms, or through people from your past who reappear years later with unfinished business. You value loyalty over courtship and meaning over display. Doubting your own worth is the old wound here, along with waiting for approval that never quite satisfies or reliving past relationships instead of choosing new ones. Valuing yourself first, from the inside, is what lets love meet you on your own distinctive terms, and it feels like recognition.",
      "mars": "Mars retrograde at birth sends your drive inward before it moves out. You stand at the edge of the pool for a long time, then dive without warning and swim further than anyone. Anger builds quietly, sometimes for months, and then surfaces all at once over something small. You prefer to compete with yourself rather than with others, and open confrontation leaves you shaky for hours afterwards. Your gift is strategic force: when you finally commit, you are almost impossible to stop. Regular physical outlets, a craft or a solo sport keep that pressure moving, and they help you assert what you want without refighting old battles.",
      "jupiter": "Jupiter retrograde at birth makes your faith something you build rather than inherit. You question the beliefs you grew up with, read widely and slowly assemble a philosophy tested against your own experience. Luck rarely arrives gift-wrapped; your opportunities come through inner growth and quiet preparation. Your generosity is private: the loan never mentioned, the advice given in a car park. You are often wiser than you let on. Where it falters is in doubting your own good fortune or holding back from sharing what you know. Once you trust the meaning you have earned, others find it more convincing than any borrowed doctrine.",
      "saturn": "Saturn retrograde at birth makes you your own strictest boss. External rules matter far less to you than the standards you set privately, and those standards can be punishing. You redo work nobody else would have questioned and judge yourself harshly for mistakes others forget in a day. Responsibility often arrived early, or an absent or inconsistent parent left you building your own inner structure. Mastery comes later than you wanted, yet when it comes it is solid and entirely earned. The real work is softening that inner critic enough to recognise how far you have already come, and to rest in it.",
      "uranus": "Uranus retrograde at birth makes your rebellion an inside job. You rarely look radical, yet your thinking departs from the crowd, and your breakthroughs arrive as sudden inner clicks rather than public gestures. You change your mind in the middle of the night and wake knowing something has shifted for good. Freedom matters to you more as a private state than a public statement. The outer planets spend around five months of each year retrograde, so many people born near you share this, and its personal flavour comes through Uranus's house and aspects. For you, awakening is something you live rather than announce.",
      "neptune": "Neptune retrograde at birth draws your imagination and spiritual life inward. Your dreams are vivid and your intuitions strong, but you keep them close, sharing them only with people you trust completely. You sense things before you can justify them and often find your hunches confirmed weeks later. Separating vision from wishful thinking is a lifelong practice, as is knowing when a beautiful idea is an escape. Neptune is retrograde for months each year, so this belongs to a whole generation, and Neptune's house and aspects say more about you personally. Your private inner world is a resource, and it deepens with every year you tend it.",
      "pluto": "Pluto retrograde at birth makes transformation a private process. Your biggest changes happen quietly, through long reflection, therapy or a crisis nobody else fully saw, and you emerge different without much announcement. Themes of power and control keep returning until you resolve them from the inside. You notice manipulation quickly because you have studied your own capacity for it. Pluto is retrograde for around half of every year, so many born near you share this, and Pluto's house tells your personal story more vividly. What remains true is that your deepest power grows unseen, long before anyone realises it has arrived.",
      "chiron": "Chiron retrograde at birth means your deepest wound is something you work through privately. You carry an old ache, often from childhood, that took years even to name, and you seldom mention it in company. Outside fixes rarely help; understanding arrives through reflection, long walks and the slow accumulation of self-knowledge. People sometimes see only your competence and miss the tenderness underneath. Isolation is the hazard, the belief that you must heal entirely alone. Once you have made peace with the wound, your insight into other people's pain becomes precise and gentle, and those who are struggling seek you out without quite knowing why.",
      "none": "Every planet was moving direct when you were born, so your energy flows outward with very little hesitation. You say what you think, act on what you want and take life largely at face value. Decisions come quickly, and you rarely spend nights second-guessing yesterday's conversation. That directness makes you refreshingly easy to read and quick to recover from setbacks. Because nothing in your chart forces you to pause, though, you can repeat the same mistake several times before noticing the pattern. Deliberate moments of review, a journal, a weekly walk, a trusted friend who tells you the truth, give your natural momentum a depth to match its speed.",
      "stationary": "A planet stationary at your birth was almost motionless, pausing as it turned between direct and retrograde. Its themes are concentrated in you rather than diluted, colouring the whole chart like a signature. Whatever that planet governs, you feel it intensely and express it unmistakably, whether that is love, drive, thought or discipline. Friends could name it as your defining trait within a minute of meeting you. Such concentrated energy is hard to switch off, and it can dominate situations that call for a lighter touch. Handled well, it becomes the steady centre from which the rest of your life takes direction."
    }],
    ["balance.*.strong", {
      "fire": "When fire dominates your chart, you run on enthusiasm and instinct. You book the trip before checking the dates, volunteer first and recover from setbacks faster than anyone you know. Your excitement is contagious; a room warms up when you arrive with an idea, and people follow you into plans they would never have started alone. You sense possibility long before the evidence arrives. Impatience and burnout are the price. Ordinary Tuesdays make you restless, half-finished projects pile up, and in the rush you can trample feelings you did not notice. Paced rather than spent all at once, your fire becomes a courage others can rely on.",
      "earth": "Plenty of earth makes you practical, patient and firmly rooted in the physical world. You know what is in the fridge, when the car needs its service and how much the holiday will cost. You build steadily, finish what you start and handle money with quiet good sense, and people trust you precisely because you deliver. Your body, food and surroundings matter to you, and an hour in the garden does more for you than any pep talk. Rigidity is the shadow side: security becomes a cage, healthy risks get refused, and anything that cannot be measured gets dismissed. Letting a little uncertainty in keeps your solid foundations alive.",
      "air": "An air-dominant chart gives you a quick, curious mind and an easy way with people. You can chat to anyone at a party, see the pattern in a messy situation and explain it in plain terms before others have finished reacting. Ideas excite you, and you keep a running list of books, podcasts and conversations to follow up. Under pressure you stay cool and objective, which makes you a natural mediator. Detachment is the catch. You explain your feelings instead of having them, and partners sometimes find you pleasant but slightly out of reach. With head and heart travelling together, your clarity becomes a kindness to those around you.",
      "water": "Strong water gives you emotional depth and a finely tuned sense of atmosphere. You walk into a room and know who has been arguing. Friends call you when they are struggling because you understand without needing everything explained, and music or a film can move you to tears on an ordinary evening. Your bonds run deep and your intuition is usually right. Overwhelm is the cost: you absorb other people's moods, carry old hurts into new situations and struggle to tell where your feelings end and someone else's begin. Clear boundaries and quiet time alone let your sensitivity become wisdom rather than exhaustion.",
      "cardinal": "A cardinal emphasis makes you an initiator. You see what needs doing and start it before the meeting has finished, and new beginnings, a fresh job or a house move, energise you rather than frighten you. People look to you to lead, and you rarely wait for permission. Challenges spur you on. The long middle of any project is where you struggle, once the excitement fades and the real work begins. You push others to keep your pace, grow impatient with slower colleagues and sometimes launch a new venture to escape a stale one. Staying through the middle turns your starts into lasting achievements.",
      "fixed": "A fixed emphasis gives you persistence, loyalty and remarkable staying power. You finish the thousand-piece puzzle, stay friends with people from primary school and keep going long after others have given up. Pressure steadies rather than rattles you, and colleagues rely on you precisely because you do not change with the weather. What you build tends to last. Stubbornness is the flip side. You hold positions past their usefulness, remember slights for years and stay in jobs or relationships out of habit rather than joy. Extend that loyalty to your own growth and your steadiness becomes a strength that can bend without breaking.",
      "mutable": "A mutable emphasis makes you adaptable, curious and quick on your feet. Plans change and you shrug, reroute and often enjoy the detour more than the original trip. You see several sides of any argument and help friends through transitions because you are unafraid of change yourself. Variety keeps you engaged, and routine drains you fast. Scattering is the hazard. You say yes to too much, change direction before anything has had time to root, and shape yourself so fully around whoever is nearby that your own preferences blur. A few anchors, one project, one practice, one promise kept, give your flexibility a centre to return to."
    }],
    ["balance.*.weak", {
      "fire": "A chart light on fire makes it harder to find the spark to begin. You are thoughtful, careful and reliable, yet you hover over the send button, wait for the right moment and wonder whether you deserve to take up space. Other people's loud enthusiasm can feel tiring, even slightly suspect. Your energy burns on a lower flame, which gives you staying power but little natural momentum. The cost is missed chances and a quiet doubt about your own courage. Fire still reaches you through a strong Sun or Mars and through planets in fire houses, and each small bold act builds a warmth others begin to notice.",
      "earth": "With little earth, the practical side of life feels like a foreign language. You have wonderful ideas, yet the receipts go missing, meals get forgotten and deadlines slip past while you are thinking about something more interesting. Your body sends reminders you ignore until they become loud. Life can feel ungrounded, as though security belongs to other people. Your gift is imagination unconstrained by what is supposedly realistic, and you see possibilities that sensible people miss. Grounding is a skill rather than a trait, and your earth planets and houses show where it comes most naturally, often through cooking, walking or working with your hands.",
      "air": "Low air makes it harder to step back from experience and look at it coolly. You feel things deeply or handle them practically, but putting them into words takes effort, and you replay a disagreement for days without quite being able to explain your side. Other viewpoints can seem baffling rather than interesting, and social events leave you drained. You are sincere and unpretentious, and your instincts are often sounder than clever arguments. Getting stuck inside a single perspective is the real limitation. Reading, conversation and planets in the third, seventh and eleventh houses all develop your air, and each step back gives you more room to breathe.",
      "water": "Little water in your chart makes feelings harder to name and harder to show. You are logical, capable and composed, the person people want in an emergency, yet emotional scenes leave you unsure what is expected. Partners sometimes say they cannot tell what you feel, and you are unsure yourself. Intuition feels unreliable, so you trust facts instead. This keeps you at a distance from people who want closeness, and from your own inner life. Emotional intelligence is fully available to you, often developed later through a close relationship, therapy or creative work, and when it arrives it carries a clarity more watery people rarely have.",
      "cardinal": "Few cardinal planets make starting things the hardest part of your life. Once something is moving you sustain it beautifully or adapt it cleverly, but the first step stalls: the job application sits half written, the difficult conversation waits for a better week. You tend to let circumstances decide for you, then wonder why change always seems to happen to you. Staying too long in situations you have outgrown is the result. Initiative is a muscle rather than a gift, and it grows through small, deliberate acts of courage. Each thing you begin before feeling ready proves that beginning imperfectly still counts.",
      "fixed": "With few fixed planets, staying with one thing long enough to see results is your real challenge. The new hobby is thrilling for three weeks, then the equipment gathers dust in the cupboard. Fresh options keep calling, and commitment can feel like a door closing. You are adaptable, quick and rarely stuck, which serves you well in a changing world. What it leaves behind is a trail of half-finished projects and a nagging sense that your talent has not yet added up to anything. Persistence through boredom is something you build deliberately, and once you see what sustained effort produces, you trust yourself with bigger commitments.",
      "mutable": "Few mutable planets make change feel threatening rather than exciting. You are decisive and steady, but when plans shift at the last minute your whole day tilts, and uncertainty sits in your stomach until it resolves. Other approaches can look wrong to you, and under stress you dig in harder. That consistency makes you dependable and clear. Life insists on change sooner or later, a new manager, a move or a loss, and you have had little practice bending. Flexibility grows through small, chosen experiments, and each time you adapt without falling apart, you discover more room inside yourself than you knew."
    }],
    ["shapes.*.text", {
      "bundle": "All ten planets fall within about a third of the zodiac, so your life energy runs through a narrow, concentrated channel. You know what matters to you and spend little time on anything else, which makes you focused, self-contained and formidably capable in your chosen field. Friends can name your passion in a word. The empty part of the chart is territory you meet through other people and circumstances, often through partners or colleagues who bring the missing ingredients. The risk is a narrow outlook, where anything outside your specialism feels irrelevant. Against that stands depth: you reach levels of mastery others rarely match.",
      "bowl": "Half your chart holds every planet, the other half none, and that split gives your life a strong sense of purpose and of something missing. You carry what you have with care, and you feel driven to fill the empty half through experience, service or a cause larger than yourself. Your choices often have a mission quality, a sense that you are here to contribute something specific. You notice gaps others overlook. Feeling perpetually incomplete is the burden that comes with it. The leading planet on the rim of the bowl shows how you move out into the world, and it often marks your most distinctive gift.",
      "bucket": "Nine planets gather in one half of the chart while a single planet, the handle, stands alone on the other side. That lone planet becomes the lever of your whole life: its sign, house and meaning describe where your energy pours out into the world. You tend to have one overriding drive, and everything else organises itself around it. Friends watch you return again and again to the same theme, whether a vocation, a relationship or a cause. Placing so much weight on a single outlet means that when it is blocked, you feel you have lost everything. Used well, the handle gives your focus remarkable force.",
      "locomotive": "Your planets fill about two thirds of the zodiac and leave an empty trine of at least 120°, and your life has the feel of a train gathering speed. You sense what is missing and bring a practical, relentless determination to supply it. Once you set a direction you keep going while others stop for breath. The leading planet, at the front edge of the procession, acts as your engine and shows where your momentum comes from. Driving yourself too hard, and measuring every day by progress, wears you down. When the engine runs well, you have a self-propelled energy that gets practical things done.",
      "seesaw": "Two groups of planets face each other across your chart, separated by empty space, so your life plays out between opposites. You weigh this against that, work against home, self against other, and can argue both sides of almost any question convincingly. Friends come to you for balanced advice because you see every angle. Indecision is the snag, or swinging from one extreme to the other before settling. Relationships often show you the half of yourself you are not currently living. Your gift is reconciliation: you find the bridge between positions that others assume can never meet.",
      "splash": "Spread evenly around the wheel, your planets touch many signs and houses, and your interests are as wide as the chart. You can talk about gardening, football and philosophy in one evening and mean every word. People from very different worlds feel at home with you, and you rarely find any area of life irrelevant. Versatility is your natural state. The risk is scattering your energy across so many fronts that nothing gets finished, and wondering why others seem more focused. Breadth, adaptability and variety make your life rich, and a few threads followed give your many interests a shape.",
      "splay": "Irregular clusters of planets, rather than any neat pattern, mark your chart, and you resist being categorised just as firmly. You follow your own interests, build a life around several strong centres of focus, and bristle when people try to file you under one label. Colleagues find you hard to predict, and friends find you impossible to be bored by. Your enthusiasms arrive on their own schedule, and you trust them. Your independence can look like inconsistency to others, and systems built for more uniform people chafe. Originality is your hallmark, along with the confidence to go your own way."
    }],
    ["hemis", {
      "above": "Most of your planets sit above the horizon, in houses 7 to 12, so your life is oriented outward towards the public, the social and the wider world. You are more visible than you realise: people remember you from one meeting and quote things you said years ago. Your development comes through engagement with others, your role in the community and what you contribute. Achievement matters to you, and time spent purely on yourself can feel strangely unproductive. Private life can wither, or other people's view of you can come to define it. Anchored in your inner truth, that visibility becomes influence.",
      "below": "Below the horizon, in houses 1 to 6, is where most of your planets sit, so your life is oriented inward towards the personal and the private. You grow through self-knowledge, family, skills and the texture of daily life before stepping into any public role. People often see you as more reserved than you feel, and you do your best work away from the spotlight, in the kitchen, the workshop or the small team. You underrate your own influence, and you hide when the world needs what you have built. Your strength is authenticity: what you finally offer has been fully lived first.",
      "east": "Most of your planets lie in the eastern half of the chart, around the Ascendant, and you prefer to shape your own circumstances. You set the pace, make the first move and feel most alive when the decision is yours. Waiting for other people to act frustrates you, and you would rather fix it yourself than delegate and hope. That self-determination makes you resourceful and hard to push around. Doing everything alone is the habit to watch, since it means missing the help and timing others could offer. Your life responds strongly to your own initiative, and when you act from conviction, doors open.",
      "west": "The western half of your chart, around the Descendant, holds most of your planets, and your life unfolds through other people. Partners, clients, collaborators and good timing bring your biggest opportunities, often through an introduction you did not plan. You read what others need quickly and adapt with grace. Alone you can feel oddly stalled, as if waiting for the right person to arrive. Accommodation can swallow you: you say yes to keep the peace and let others steer. Cooperation that keeps hold of your own direction makes relationships the engine of your success rather than a detour from it.",
      "balancedVertical": "Your planets are balanced above and below the horizon, so your life moves evenly between private and public worlds. You can give a presentation in the afternoon and be content alone with a book that evening, and neither side feels like a performance. Home and career both matter to you, and you notice quickly when one begins to crowd out the other. People see you as grounded yet engaged. At times you feel pulled in both directions at once, never quite sure where to put your full weight. Honouring both needs lets you bring inner depth to public life and outer confidence home.",
      "balancedHorizontal": "Your planets are balanced east and west, so self-direction and responsiveness to others sit together in you. You can lead a project or follow someone else's plan with equal ease, and you know instinctively when to push and when to wait. Partners find you independent without being aloof, and colleagues find you cooperative without being pliable. That versatility makes you a natural bridge between strong personalities. Uncertainty about whether to act alone or together can leave you hesitating at key moments. Trusting your own read of the situation lets you move between the two with skill."
    }],
    ["quadrants.*.text", {
      "1": "With planets concentrated in houses 1 to 3, your energy goes into building yourself first. You shaped your identity early, often independently, and much of what you believe about yourself was formed before you left school. Your body, your resources and your way of thinking and speaking get most of your attention, and you learn by doing things personally rather than watching others. You are self-reliant and quick to act. Self-absorption is the pitfall, along with seeing the world only through your own lens. Your development is instinctive and personal, and once your foundations are secure, you bring a strong, clear presence to everything else.",
      "2": "Planets gathered in houses 4 to 6 send your energy into home, creativity and daily craft. Your emotional roots run deep, and the family you grew up in shapes you in obvious and subtle ways. You express yourself through what you make, whether a meal, a garden, a piece of music or a well-run week. Children, play and useful work bring you satisfaction, and you notice the small details that make daily life good. Staying close to home can hold you back when a wider stage calls. You grow by giving who you are a tangible form, and people feel cared for in your presence.",
      "3": "With planets concentrated in houses 7 to 9, your energy flows into relationships and understanding. You learn about yourself mainly through others: partners, close friends, teachers and the people who challenge you most. Intimacy, shared resources and the search for meaning take up a great deal of your time and thought. You are drawn to travel, study and conversations that change your mind. Depending on others to define you is the danger, or losing your centre in someone else's world. Each relationship widens your view, and over time you become someone who understands many kinds of people.",
      "4": "A cluster of planets in houses 10 to 12 directs your energy towards the world beyond yourself. Career, reputation, community and the collective occupy much of your attention, and you feel a pressing need to contribute something that outlasts you. Causes, institutions and future generations are the scale you think on. Recognition matters to you, yet so does quiet service behind the scenes. Neglecting your personal life is the cost, or feeling that private happiness is somehow selfish. Your development is tied to what you give back, and the more meaningful your contribution, the more fulfilled you feel."
    }],
    ["progressions.moonSigns", {
      "aries": "Somewhere in this chapter of roughly two and a half years you catch yourself walking out of a meeting, or a kitchen, already decided. The progressed Moon in Aries puts your feelings in the driving seat and makes waiting feel almost physically uncomfortable. You start the project you shelved, book the solo trip or say the blunt thing at the dinner table that everyone else was thinking. Irritation arrives fast and leaves fast, and each flash of temper points at a need you have been ignoring for years. The hard part is that you can burn bridges in a hurry and then wonder why the road behind you looks so empty. What this season gives back is nerve: a clean, bodily sense that you are allowed to want things and go after them yourself.",
      "taurus": "After a louder stretch, the progressed Moon in Taurus lets you exhale for about two and a half years. You notice yourself lingering over a proper breakfast, checking the savings account with keen interest, or spending a whole Saturday in the garden without guilt. Comfort stops being a luxury and becomes the thing that keeps you steady, so the body, the home and the bank balance all get more of your attention. Your feelings slow down and settle, which makes you calmer company and far harder to rush. The risk is that familiar starts to pass for right, and you stay in the same chair, job or arrangement long after it has stopped feeding you. What you gain is a sure, quiet knowledge of what you value and the patience to build around it.",
      "gemini": "Your phone fills up with voice notes, open tabs and half-read articles once the progressed Moon moves into Gemini. For roughly two and a half years you feel lighter, chattier and hungry for information, signing up for a short course on a whim or taking the long way home to finish a conversation. Siblings, neighbours and the people on your street start to matter more than they did. You make sense of your feelings by talking them through or writing them down, often at midnight in a notebook by the bed. The catch is a buzzing, scattered mind that samples everything and settles on nothing, with nervous overthinking to match. This is a season of learning for its own sake, and the big decisions come later and come easier because of it.",
      "cancer": "The progressed Moon feels most at home in Cancer, and for about two and a half years your emotional life turns towards the people and places you belong to. You find yourself repainting the spare room, phoning your mother more often or cooking big Sunday dinners for whoever turns up. Home, family, ancestry and the simple need to feel safe move to the centre of everything. Childhood memories surface unexpectedly, triggered by a smell or an old song, and ask to be understood with adult eyes. Your skin gets thinner too, so a careless remark can sting for days and you retreat into your shell faster than usual. By the end you know how to mother yourself as tenderly as you have always mothered everyone else.",
      "leo": "With the progressed Moon in Leo, you want to be seen, and for roughly two and a half years you stop pretending otherwise. You pick up the paintbrush again, audition for something, fall headlong in love or spend long afternoons playing with children. Joy becomes a need rather than a reward, and your heart opens with a generosity that surprises the people around you. Recognition matters more than you like to admit. When nobody claps, when a message goes unanswered or a friend forgets the thing you were proud of, it bruises far more deeply than it used to. This chapter teaches you to step onto the stage without waiting for an invitation, and to enjoy things warmly without justifying them.",
      "virgo": "The progressed Moon in Virgo brings about two and a half years of wanting to fix, sort and improve. You clear out the cupboard under the stairs, overhaul your diet, colour-code the calendar or learn the practical skill you always meant to. Feeling useful becomes soothing, and a well-run day gives you more peace than any holiday. Health and daily routines take on emotional weight. The difficulty is a critic that turns inward, replaying the one mistake in an otherwise good week and insisting you should have done better. Once that sharp, capable eye turns towards systems rather than towards yourself, this becomes one of the most healing seasons of your life.",
      "libra": "When the progressed Moon enters Libra, relationships take centre stage for roughly two and a half years. You feel the pull towards partnership, and you meet someone, deepen a bond or sit across the table renegotiating one that has drifted out of balance. Loneliness bites harder than before, and so does the urge to keep the peace, which is why you swallow the complaint and say the restaurant choice is fine. Beauty soothes you in a very direct way: fresh flowers, a rearranged living room, a gallery visit on a grey afternoon. The real work is learning to cooperate without disappearing. By the close of this chapter you ask for fairness out loud, and people are glad you did.",
      "scorpio": "For about two and a half years the progressed Moon in Scorpio takes you into deep water. Feelings run hotter and stranger, and you lie awake turning over questions of trust, jealousy, power or money you share with someone else. What has been buried tends to surface: a family secret, a grief you never finished, a resentment you thought you had outgrown. You crave privacy and total honesty at once, which confuses the people who love you. Suspicion is the trap here, reading betrayal into silence and testing loyalty before anyone has failed you. Therapy, research and any work beneath the surface go unusually well now. You come out of this stretch more resilient and far less afraid of your own depths.",
      "sagittarius": "With the progressed Moon in Sagittarius your emotional world throws its windows open. For roughly two and a half years you crave space, meaning and adventure, so you book the flight, enrol in the course or stay up late arguing about philosophy with a stranger. Anything small or confining starts to feel like a cage, and you grow impatient with conversations that never leave the practical. Optimism comes back after heavier years, and you are far more willing to take a chance on yourself. Staying busy becomes a way of running from difficult feelings, moving on before anything catches up. Out of this season comes a philosophy of your own, one you have tested rather than inherited.",
      "capricorn": "The progressed Moon in Capricorn brings about two and a half years of serious, purposeful feeling. You take on more responsibility, chase a career goal with determination or become the one everyone relies on at work and at home. Emotions go underground while you get on with the job, and friends notice you answering 'fine' more often than usual. Some people find this stretch lonely or heavy, a long uphill walk without much applause. It is also strengthening, because you discover how much you can carry and you build structures that hold for years. The lesson is letting others see the effort behind your composure, and allowing yourself to rest before you are exhausted.",
      "aquarius": "When the progressed Moon moves into Aquarius you want freedom and a little distance. For roughly two and a half years you find new friends through a group, a cause or an online community, and your old social circle changes shape almost without you noticing. Old emotional patterns lose their grip, and you feel willing to live in ways that would once have seemed too odd. You catch yourself observing your own feelings from a slight height, as though watching a film about someone else. That detachment helps you see clearly, though it can leave partners and family feeling held at arm's length. This chapter lets you redesign how you live and choose, deliberately, who belongs around you.",
      "pisces": "The progressed Moon in Pisces completes the whole emotional cycle and brings a softer, more porous chapter of about two and a half years. Music moves you to tears in the supermarket, dreams feel vivid enough to remember at lunch, and you crave long baths, quiet walks and time alone with art or prayer. Old attachments dissolve quietly, and endings arrive without much drama, making space for whatever comes next. Your boundaries thin, so other people's moods soak straight into you. Exhaustion and escape are the danger, reaching for another glass, another episode, another hour of scrolling when what you need is rest. This is a season of forgiving and grieving, and beneath the surface something new is already taking shape."
    }],
    ["progressions.moonHouses", {
      "1": "As the progressed Moon crosses your first house, your feelings sit right on your face for two or three years. People read your mood before you have said a word, and you notice yourself reacting faster and more visibly than you used to. This is often a stretch of personal reinvention: the dramatic haircut, the new wardrobe, the running habit that sticks. Your own needs push to the front of the queue, sometimes to the surprise of people used to you putting yourself last. The shadow is taking everything personally, feeling every look across the room as a judgement on you. What you gain is the freedom to show up as you are, and the discovery that most people like that person better.",
      "2": "With the progressed Moon in your second house, your emotional security becomes tangled up with money, possessions and self-worth. For two or three years you check your balance more often, reorganise the budget or push for the pay rise you have been putting off. Spending turns into a way of soothing feelings, and the new jumper or kitchen gadget arrives on a bad day more often than on a good one. Underneath sits a bigger question about what you are worth and whether your life reflects it. The risk is confusing comfort with value and filling a gap that no purchase reaches. A small, steady emergency fund ends up calming your nerves more than any treat.",
      "3": "The progressed Moon moving through your third house fills your days with conversation and your head with ideas for two or three years. You start a course, write more, send long messages late at night and ring your brother or sister more often than you have in years. Short journeys, local errands and chats with neighbours carry surprising emotional weight. You understand your feelings best once you have put them into words, out loud or on paper. Restlessness is the cost, a jittery mind that jumps between five topics and struggles to switch off at bedtime. A regular walk around your own neighbourhood becomes an unexpected source of calm, and a surprising number of answers arrive on it.",
      "4": "When the progressed Moon reaches your fourth house, home and family become the emotional centre of your life for two or three years. You move, renovate, start a family or spend more evenings looking after a parent. Old family patterns come up for a second look, and you catch yourself using your father's exact phrase or your mother's tone of voice. Privacy starts to matter enormously, and a night in feels better than any party. The difficulty is getting pulled back into childhood roles the moment you walk through the family front door. Old photographs and questions you never thought to ask older relatives explain a great deal now, and the roots you put down in this stretch hold for a long time.",
      "5": "The progressed Moon in your fifth house brings two or three years of wanting joy, romance and play. You say yes to the dance class, the love affair or the messy creative project that has no obvious purpose. Children feature strongly, your own or other people's, and their unguarded delight rubs off on you. Hobbies harden into passions, and you take emotional risks you would once have talked yourself out of. The catch is chasing the next thrill because the ordinary week starts to feel dull by comparison. Laughter, flirtation and making things badly but happily are all fair uses of this time, and they show you who and what makes you feel most like yourself.",
      "6": "With the progressed Moon crossing your sixth house, daily routines, health and work demand your attention for two or three years. You change jobs, rewrite your schedule or book the appointment you have been putting off. Stress goes straight into your body, so a tense month shows up as a stiff neck or a restless stomach long before you admit you are overloaded. Feeling useful matters enormously, and a tidy inbox gives you a lift. Where it goes wrong is turning into the person who covers every shift and fixes every problem while running on empty. Pets, colleagues and the rhythm of an ordinary Tuesday matter more than you expect, and small changes to your habits add up to a day you enjoy.",
      "7": "As the progressed Moon moves through your seventh house, partnership becomes the main emotional arena for two or three years. You commit, marry, separate or sit down to renegotiate a relationship that has run on autopilot for too long. Business partners and close collaborators matter more as well. Other people act as mirrors now, and you recognise your own habits in the partner who withdraws or the friend who always needs rescuing. If you usually give more than you receive, this is the stretch when that pattern becomes impossible to ignore, and resentment makes it louder. Honest conversations over the kitchen table turn out to be the making of your closest bonds, whichever way they go.",
      "8": "The progressed Moon in your eighth house takes your feelings deeper for two or three years. Intimacy, trust, shared money, inheritance, debt or loss come into focus, and conversations you have avoided for years insist on happening. You find yourself sorting out a will, untangling joint finances or sitting with someone through a hard ending. Long-buried fears and desires surface, sometimes in dreams, sometimes in a sudden flood of feeling over something small. Under pressure you grip harder, trying to control people or outcomes because letting go feels like falling. Therapy, honest talk and the courage to be seen as you are make this one of the most transforming stretches of your life, and vulnerability starts to feel like strength.",
      "9": "With the progressed Moon in your ninth house you outgrow familiar horizons for two or three years. Travel, higher study, spiritual exploration, publishing or friendships across cultures feed you emotionally in a way ordinary life no longer does. You find yourself browsing flights at midnight, signing up for a degree or reading late into the night about ideas your family never discussed. Beliefs you held for decades shift as experience teaches you something new. Taken too far, this turns into restless preaching, falling in love with a new truth and pressing it on everyone at dinner. A mentor from a very different background, or one long journey, changes the way you see your whole life.",
      "10": "The progressed Moon crossing your tenth house brings career, reputation and public life into the emotional foreground for two or three years. You step into a more visible role, reach a professional milestone or feel a strong, sometimes uncomfortable, pressure to achieve. How the world sees you matters far more than it did, and one careless comment from a manager can shake your whole week. You also look again at your mother or another key parent figure as a model of how to live and work. It gets hard when you chase ambitions that belong to someone else's expectations rather than your own. By the end you know which parts of that inherited example you want to keep and which you are ready to leave behind.",
      "11": "As the progressed Moon moves through your eleventh house, friendships, groups and hopes for the future matter intensely for two or three years. You join a club, throw yourself into a cause or discover an online community that feels like a second home. Some old friendships fall away while new ones arrive through shared interests rather than shared history. Long-term goals come into sharper focus, and you catch yourself dreaming out loud about the life you want in ten years. Belonging has a cost too: you lose yourself in the group, going along with the crowd's mood to avoid feeling left out. Your social life changes shape considerably in this stretch, and that change is the point.",
      "12": "The progressed Moon in your twelfth house brings two or three quieter, more inward years. You need more sleep, more solitude and more time staring out of the window, and busy social diaries start to feel like noise. Old emotional material surfaces to be healed, often through dreams vivid enough to follow you into the morning. Endings arrive quietly as one cycle closes. Not all of that withdrawal is rest, and part of you uses it to disappear from people who care about you. Spiritual practice, creative work, time near water and quiet service to others all nourish you, and this gestation prepares the fresh start that follows when the Moon reaches your first house."
    }],
    ["progressions.sunSigns", {
      "aries": "The progressed Sun in Aries opens a chapter of roughly thirty years in which your identity grows bolder and more self-directed. Where you once waited for approval, you now act first and explain later, whether that means starting a business, taking up a competitive sport or stopping the apologies for your ambitions. Energy rises and so does impatience, and you notice yourself finishing other people's sentences or walking faster than everyone around you. You become someone who leads because nobody else is moving. Along the way you can bulldoze people who need a little more time than you do. Across these decades you learn that your own initiative is enough to begin, and you pace yourself for a long race rather than a sprint.",
      "taurus": "With the progressed Sun in Taurus, a chapter of about thirty years brings steadiness and consolidation. Your sense of self becomes rooted in what you can build, own and enjoy, and you grow noticeably more patient. Many people buy land or a home during this stretch, plant a garden they intend to watch mature or settle in a place that feels right. Your voice, your body and your appetite for pleasure all ask for attention, and good food and good fabric stop feeling like indulgences. Persistence and careful investment of time and money pay off handsomely. Stubbornness is the price, digging in your heels when life asks you to adapt, and staying loyal to a plan long after it has stopped serving you.",
      "gemini": "When the progressed Sun enters Gemini, your identity grows curious, flexible and communicative for around thirty years. You turn into the writer, teacher, connector or perpetual student, the person with three books on the go and a podcast recommendation for everyone. Variety feeds you, and holding several interests at once feels natural rather than scattered. Careers change more than once in this chapter, or you find a role that uses many skills at the same time. Siblings and peers take on new importance, and your social circle keeps widening. The shadow is staying on the surface, knowing a little about everything while your best ideas never get the time to take root.",
      "cancer": "The progressed Sun in Cancer turns your identity towards home, family and emotional belonging for roughly thirty years. You become the one who remembers birthdays, hosts the holidays and holds the family together when things fall apart, or you build a chosen family of your own. Caring for others and creating a safe base become central to who you are, and your instincts about people grow sharper and more reliable. You grow more protective, and you feel slights to the people you love as keenly as slights to yourself. Yet you give endlessly and refuse to be looked after in return, which wears you thin. Across this long chapter you learn to let yourself be held as well as holding everyone else.",
      "leo": "With the progressed Sun in Leo, a thirty year chapter of self-expression begins. You grow more willing to shine, create and take up space, and many people find their confidence here after years of holding back. Recognition, love and creative achievement become central to your sense of who you are. You take up performing, teaching or leading in some visible way, and children, your own or those you mentor, often play a part. There is a new warmth in how you walk into a room, and people turn towards it. The challenge is leading from the heart rather than from a need for applause, and making room for others to shine beside you rather than behind you.",
      "virgo": "The progressed Sun in Virgo brings a chapter of roughly thirty years devoted to mastery, service and refinement. Your identity grows through useful work and skill, and you become the person others ask when something needs doing properly. Health and daily routines take on lasting importance, and many people change their diet, working pattern or approach to wellbeing for good during these decades. You find deep pleasure in ordinary things done well: a neat repair, a clean spreadsheet, a loaf that rises just right. The risk is an inner critic that never switches off, measuring every achievement against an impossible standard. Once you value progress over perfection, your competence becomes a gift to a great many people.",
      "libra": "When the progressed Sun moves into Libra, relationships and fairness shape your identity for about thirty years. You become more diplomatic and more aware of other people's perspectives, the one who can see both sides of a family row. Partnership defines much of this chapter, in love or in work, and you learn the real craft of collaboration. Your taste grows more refined, and interests in design, law or mediation often appear. Fairness stops being an abstract principle and becomes a daily practice in how you split the bill or the chores. The deeper lesson is keeping your own centre while seeking harmony, rather than dissolving into whatever the people around you want.",
      "scorpio": "The progressed Sun in Scorpio opens an intense, transforming chapter of about thirty years. Your identity deepens as you face questions of power, intimacy, trust and change, and surface-level living stops satisfying you. Small talk at parties starts to feel like a waste of an evening. Psychology, research, healing or any work that uncovers what is hidden draws you in. These decades include profound endings and rebirths, and close relationships become either much deeper or plainly over. The shadow is control, holding secrets and grudges as insurance against being hurt again. You leave this chapter emotionally formidable, at ease with silence and strong feeling, and with very little patience for pretence.",
      "sagittarius": "With the progressed Sun in Sagittarius, your identity expands for roughly thirty years. You seek meaning, adventure and a bigger picture, and travel, study, teaching or spiritual exploration become central to who you are. Many people live abroad in this chapter, gain a late qualification or find a practice that anchors them. You grow more candid and more optimistic, and your sense of humour widens along with your sense of adventure. Living by your own philosophy starts to matter more than fitting anyone else's. Enthusiasm can outrun follow-through, and a certainty about your own truth leaves little room for anyone else's.",
      "capricorn": "The progressed Sun in Capricorn begins a thirty year chapter of ambition, responsibility and long-term achievement. Your identity becomes tied to what you build and the authority you earn, and you take on the roles other people rely on. You grow more disciplined and more realistic, planning further ahead than you ever did before. Status and structure matter more, and your relationship with time shifts, so you value what endures over what dazzles. This long stretch rewards patience and integrity handsomely. The trap is measuring your worth only by your output, working through weekends and letting warmth slip away while you climb, when success on your own terms needs both.",
      "aquarius": "When the progressed Sun enters Aquarius, your identity grows more independent and forward-thinking for about thirty years. You question conventions you once accepted, embrace unusual interests and find purpose in community, activism or social change. Technology, science or an unconventional lifestyle often becomes part of how you see yourself. Friendships grow more varied, and you care noticeably less about fitting in or pleasing the neighbours. This chapter frees you from roles that no longer fit, sometimes abruptly, and you feel lighter for it. The challenge is staying emotionally present with the people closest to you while your mind is busy with ideals and the future.",
      "pisces": "The progressed Sun in Pisces opens a chapter of roughly thirty years of sensitivity, imagination and spiritual depth. Your sense of self softens, and you are drawn to art, music, healing or caring roles in a way that surprises people who knew your earlier drive. Rigid goals matter less than meaning and connection, and a quiet retreat or a morning spent painting feels more worthwhile than a promotion. Old identities dissolve over these decades, sometimes gently, sometimes through loss. The difficulty is porous boundaries, absorbing everyone's pain and drifting when life needs a firm decision. What you learn is that softness and strength are not opposites, and that your intuition is a reliable guide."
    }],
    ["signs.*.love", {
      "aries": "You love the way you do everything else, with heat and no waiting around. When someone catches your eye you send the message first, suggest the date and turn up early, because hanging about to be chosen feels like slow torture. The chase is half the thrill, and a partner who argues back without sulking keeps you hooked far longer than one who agrees with everything. Affection from you is energetic: a spontaneous drive to the coast, a fierce defence of your person in front of others. Patience is the hard part, since interest can burn hot and then flicker once the pursuit is over. Being managed or smothered cools you almost overnight, while playful rivalry and room to breathe keep the fire going for years.",
      "taurus": "Love, for you, is something you can hold, taste and come home to. You fall slowly, watching whether someone turns up when they said they would, and only then do you let yourself settle in. Once you commit you are wonderfully loyal, the one who remembers how they take their tea and has the blanket ready on the sofa. Touch matters enormously, as do shared meals, Sunday rituals and plans that happen. Games and sudden changes of heart unsettle you more than you show, and your response is often a quiet withdrawal rather than a row. The shadow is possessiveness and a reluctance to leave a comfortable rut, even when the relationship has gone stale.",
      "gemini": "A quick mind is what undoes you first. You flirt through banter, voice notes and a running thread of jokes nobody else would understand, and the first sign you are smitten is that you cannot stop messaging. Love from you looks like conversation: the article you forward at midnight, the story you save up to tell them, the new café you want to try together. Variety keeps you awake, so a curious, sociable partner suits you far better than one who wants the same evening every week. Long silences read to you as distance, and you can drift towards whoever is more entertaining. Underneath the lightness you want someone who is still talking with you, and still making you laugh, decades from now.",
      "cancer": "You love by looking after people, and the care is often quiet and precise. You remember the name of their difficult colleague, cook their childhood favourite after a hard week and text to check they got home safely. Emotional safety matters more to you than fireworks, and you open up only once you trust that your softness will be handled gently. Family, whether blood or chosen, becomes part of the romance, and you picture a shared kitchen long before anyone mentions moving in. Criticism or coldness sends you into your shell, sometimes for days, and you can sulk rather than say what hurt. At your best you make a partner feel more at home with you than anywhere else on earth.",
      "leo": "You love generously and a little theatrically, and you see no reason to apologise for it. Birthdays become events, compliments are delivered in public, and the gift you choose has obviously been thought about for weeks. Once you give your heart, loyalty runs very deep, and you will champion your partner to anyone who listens. In return you need to be adored, chosen openly and told, not left to guess. Indifference wounds your pride far more than an argument does, and a partner who forgets to notice you can find the warmth switched off with surprising speed. Needing the relationship to reflect well on you is the trap, yet your warmth makes ordinary life with you feel like a celebration.",
      "virgo": "Your affection shows up in the details. You fix the sticking door, remember their allergy when booking the restaurant and sort the boring paperwork they have been avoiding for months. Trust grows gradually, and you rarely fall headlong, preferring to watch whether someone is kind in small, unglamorous moments. You want these efforts noticed, and you want to be loved without having to be perfect first. Carelessness, mess and broken promises dampen attraction faster than any lack of chemistry. The difficulty is a critical eye that turns both inward and outward, spotting the flaw in your partner and in yourself before either of you can relax. When you feel safe, your devotion is steady, practical and reassuring.",
      "libra": "You love with charm, courtesy and a fierce hunger for partnership. Romance matters to you in its old-fashioned forms: a well-set table, a handwritten card, the effort of dressing up for dinner on an ordinary Thursday. Fairness is the quiet centre of it all, and you notice immediately when one person is doing more of the giving. You want an equal who speaks kindly even in disagreement, since crudeness or constant bickering switches off your attraction faster than distance ever could. The risk is keeping the peace at the cost of your own wants, smiling through something that needed saying months ago. With the right person you create a relationship that feels graceful, balanced and lovely to be around.",
      "scorpio": "Nothing about the way you love is casual. Attraction lands like a jolt, often in the first conversation, and from then on you want to know everything: the real story, the old wound, the thing they have never told anyone. Loyalty is the price of entry, and you give it completely in return. You bond through shared secrets and late nights that go further than small talk ever could. Jealousy is your darker side, along with a habit of testing a partner while watching for the betrayal you half expect. When trust is broken you can close the door without warning and never reopen it. With the right person your love is transforming, the kind that changes both of you for good.",
      "sagittarius": "You love with humour, openness and a strong need for adventure. Often you fall for someone from a different background, or bond over a trip, a big idea or a long argument about what life is for. Affection from you sounds like laughter and looks like a weekend away booked on a whim. Freedom is not negotiable, and a partner who needs to know where you are every hour will find you edging towards the door. Commitment gets hard when the road still calls, and your bluntness can land harder than you meant. When you do settle, you want a fellow traveller, someone who keeps learning and still makes you laugh on the tenth long drive.",
      "capricorn": "You take love seriously, and you show it through what you do rather than what you say. Opening up takes time, and early on you can seem reserved while you quietly assess whether this person is worth building with. Your affection looks like reliability: driving them to the airport at dawn, helping with the tax return, making a five-year plan that includes them. You want a partner who is dependable, ambitious in their own right and respectful of your goals. Flakiness and emotional chaos push you behind a cool, capable front. Letting yourself be soft and playful, not only competent, is the real work, along with trusting that you are loved for more than what you provide.",
      "aquarius": "Friendship comes first in the way you love, and the best romances in your life probably started as long conversations with someone you liked. You are drawn to originality, to minds that surprise you and people who do not fit the usual mould. Space matters, and so does being accepted as you are, odd habits included. You want a partner who respects your independence and shares at least some of your ideals about how the world should be. Clinginess or pressure to follow the conventional script can make you detach without warning, sometimes before you understand why. The shadow is keeping feelings at arm's length and analysing love instead of letting yourself be moved by it.",
      "pisces": "You love romantically and with your whole heart. Quickly you see the best in someone, the person they could become, and you will give a great deal to help them get there. Compassion flows easily from you, so you are the partner who stays up listening at three in the morning and forgives more than most would. You want someone who understands your sensitivity and shares a sense of magic, whether through music, faith or long walks by the sea. Harshness and cynicism wound you badly. Idealising a partner is your blind spot, missing the warning signs and then feeling betrayed by a reality that was visible all along. Loving someone clearly, flaws included, becomes your lifelong art."
    }],
    ["signs.*.partner", {
      "aries": "You are drawn to people with a bit of fight in them: bold, decisive, quick to act and unafraid to say what they want. A partner who waits for permission bores you, and you secretly respect the one who argues back over dinner and then wins the point. What you need is someone who can match your pace without trying to crush you, so that disagreements stay clean and honest instead of turning into a contest. Reading a partner's directness as selfishness while missing your own is the classic trap. Relationships grow when both of you can charge ahead separately and still choose each other at the end of the day. Independence on both sides keeps the attraction alive long after the first sparks.",
      "taurus": "Calm, grounded people pull you in, the kind who seem unhurried and comfortable in their own skin. You notice the partner who cooks without fuss, handles money sensibly and has a steadiness that makes a crowded room feel quieter. Underneath, you need someone you can rely on completely, who turns up, keeps promises and enjoys simple pleasures alongside you. The risk is leaning on a partner for all your security, or clashing when both of you dig in and refuse to budge. Stubbornness looks far worse in them than in you, and you can miss the mirror. The best bonds in your life grow slowly and last, built on shared comforts and clear agreements.",
      "gemini": "Witty, curious and talkative people catch your attention, often ones who seem younger than their years. You are drawn to someone who can jump from gossip to philosophy in a single car journey and who always has something new to show you. Deep down you need a partner who is also a best friend, someone you never run out of things to say to. Mistaking their restlessness for disloyalty is the trap, as is calling them flighty when they need variety as much as you do. A relationship full of long silences starves you quickly. The partnerships that work in your life feel like an ongoing conversation, full of shared learning, jokes and plans that keep changing.",
      "cancer": "You are drawn to people who care, who remember birthdays, call their mother and make you a hot drink without being asked. Sometimes the pull goes the other way and you fall for someone who visibly needs looking after. What you need is a partner who is gentle with your feelings and wants to build a proper home, not just go on dates. Projecting neediness onto them while hiding your own is a familiar pattern, so that one of you always seems to be the fragile one. The openness you keep guarded often shows up in the people you choose. Relationships deepen when both of you can give and receive care, and when the shared home feels like shelter for two.",
      "leo": "Confident, expressive people light you up, the ones who walk into a party and change its temperature. You admire charisma and creative spark, and a partner who is proud to be seen with you matters more than you usually admit. You need someone who praises you generously and means it, and who is loyal when it counts. Trouble starts when you both want the spotlight and admiration sours into quiet resentment over who gets the applause. Some people with this sign strong keep choosing stars and then feel outshone. The strongest partnerships you form let both people shine, with play, warmth and praise flowing freely in both directions.",
      "virgo": "Capable, modest people appeal to you, the kind who fix things and never make a show of it. You are drawn to a partner who is precise, thoughtful and good with details, someone who reads the instructions and remembers what you said last Tuesday. What you need is a relationship where the daily load is shared fairly and nobody keeps a silent tally. Hearing a partner's precision as criticism is an old habit of yours, as is becoming the critic yourself when stress builds. Mess and unreliability wear away your attraction slowly but surely. The relationships that work for you run on clear communication, small kindnesses and permission for both of you to be gloriously imperfect.",
      "libra": "Refined, sociable and gracious people draw you in, particularly those who know how to make everyone at the table feel welcome. You notice good manners, a sense of style and a partner who handles conflict with tact rather than volume. True equality is non-negotiable for you: someone who meets you halfway without being asked. The risk is expecting the other person to keep the peace for both of you, or projecting indecision onto them while dodging your own choices. You can stay too long in a pleasant arrangement that has lost its honesty. Healthy partnership for you includes disagreement, spoken kindly and resolved fairly, so that the harmony between you is real rather than polished.",
      "scorpio": "Intense, private and quietly powerful people fascinate you, particularly those with an air of mystery you cannot quite read. You are drawn to someone who looks straight at you and seems to see far more than you have said. What you need is a partner who can go deep, share secrets and stay steady when hard truths come out. Power is where it gets complicated: you can project control or jealousy onto a partner while holding tight to your own, or test loyalty until it breaks. Relationships with you are rarely lukewarm. They become transforming when both of you are willing to be vulnerable, share power fairly and talk honestly about the feelings most people keep hidden.",
      "sagittarius": "Adventurous, open-minded people pull you in, often ones from another culture, country or way of thinking. You fall for the partner who has already lived abroad, reads philosophy on the train or suggests a road trip on a Tuesday night. What you need is someone who respects your independence and shares a larger sense of purpose, not just a postcode. Casting them as unreliable or preachy is easy when they are as restless as you are. Possessiveness in either direction kills the spark. Partnerships grow for you through travel, study and big conversations, with enough freedom on both sides that choosing each other still feels like a choice.",
      "capricorn": "Mature, responsible and well-established people appeal to you, and often you are drawn to someone older or already successful. You notice the partner who has a plan, keeps their word and handles a crisis without drama. The real need is someone to build with, sharing responsibility and long-term goals, from the mortgage to the family. It is easy to see them as controlling or cold while missing the authority you have not fully claimed yourself. Duty can crowd out tenderness, and a relationship can start to feel like a well-run business. The partnerships that last for you make deliberate room for warmth, play and affection alongside all the sensible arrangements.",
      "aquarius": "Unconventional, independent people intrigue you, the ones with unusual jobs, strong opinions and a refusal to follow the crowd. You are often drawn to a partner who feels like a friend first, and sometimes to someone a little emotionally distant. You need plenty of space, honest conversation and a shared commitment to growing, with neither of you squeezed into a conventional mould. Seeing a partner as aloof or unpredictable is tempting, though that coolness lives in you too. Your relationships can look unusual from the outside, and that suits you perfectly well. When it works, you have a partner who is also your most interesting friend and your fellow rebel.",
      "pisces": "Sensitive, artistic and dreamy people draw you in, sometimes ones who are hard to pin down. You fall for the musician, the healer, the person who cries at films and speaks about their inner life without embarrassment. What you need is someone who meets your compassion with their own and shares your sense of something larger than everyday life. The shadow is the rescue fantasy, casting a partner as someone to save or as the one who will save you. Blurry boundaries can leave you confused about where you end and they begin. Relationships heal and deepen for you when both people keep clear edges, share their dreams and see each other as they are."
    }],
    ["signs.*.home", {
      "aries": "Home life often started lively, loud or competitive for you, and you learned to stand up for yourself early, fighting for your place among siblings or at a crowded table. Independence came young, and you still hate asking for help around the house. As an adult you want a base that supports action: room to move, a garage or spare room full of projects, a door you can come and go through freely. You are the one who repaints the kitchen on a whim or starts knocking down a wall before the plans are finished. Restlessness is the catch, and tempers flare quickly under your own roof. Within your family you are often the one who leads, protects and gets things moving.",
      "taurus": "Comfort and stability sit at the heart of your sense of home, whether you grew up with them or longed for them. You probably remember the smells of childhood kitchens more vividly than most people do. Now you need a base that feels solid and beautiful: good bedding, a full fridge, a garden or at least a windowsill of plants. Routine is soothing, and time in nature settles you like nothing else. Change is hard, and a house move or upheaval at home can shake you more than you expect. Within the family you are the steady one, the person who keeps traditions going and hosts the long Sunday lunch.",
      "gemini": "Your early home was often busy and talkative, full of siblings, neighbours, books, screens and conversations happening in three rooms at once. Frequent moves are common, and home can feel more like a crossroads than a retreat. As an adult you want a space with plenty of reading material, a good internet connection and a kitchen table where friends drop in unannounced. You are the family messenger, the one who knows everybody's news and keeps the group chat alive. Settling is harder, since you get restless if every evening looks the same. A home works for you when it stays lively, sociable and easy to leave and return to.",
      "cancer": "Family, ancestry and emotional roots matter enormously to you, often more than you let on in public. Early home life was close, intense or emotionally complex, and those memories stay vivid for decades. You need a private sanctuary to recharge, a place where you can shut the door, cook something comforting and feel safe. You are the keeper of the photo albums, the one who remembers everyone's birthday and makes the house smell of dinner. Clinging to the past is your weak spot, along with feeling responsible for every relative's mood. Home can become the centre of your whole life, and when it feels secure, everything else feels possible.",
      "leo": "You want a home you can be proud of, a place for hospitality, colour and celebration. Early family life often revolved around a strong parent, or around the question of whether you were noticed and admired. Grown up, you love hosting: the birthday party with decorations, the dinner where everyone ends up singing. Children, creativity and play tend to fill your rooms. Pride gets in the way when you take family criticism too personally or need the household to orbit around you. At a deep level you need to feel special and loved within your own four walls, and when you do, your warmth makes the whole family glow.",
      "virgo": "Home feels best to you when it is orderly, clean and practical, with everything in its proper place. Early family life often emphasised duty, health or doing things properly, and you learned young to be useful. You find calm through tidying, organising the cupboard or planning the week's meals on a Sunday evening. You are the one in the family who sorts the paperwork, books the appointments and remembers who needs their medication. The difficulty is turning home into another workplace where you never quite sit down. Letting home be a place of rest as well as productivity is the deeper lesson, and when you manage it your care creates a restful household.",
      "libra": "Peace and beauty at home matter a great deal to you. Early family life often involved keeping the peace, smoothing over arguments or living with parents who cared a lot about appearances. These days you need a harmonious, attractive space to feel settled, with soft lighting, pleasing colours and furniture that goes together. You are the family diplomat, the one who mediates at Christmas and makes sure nobody feels left out. Conflict under your own roof unsettles you so much that you can avoid rows that need to happen. A home works for you when it is fair, calm and shared, a place where everyone feels welcome and nobody has to shout.",
      "scorpio": "Your early home often held intensity, secrets or significant change, and you learned young to read the emotional weather in a room. Guarding your private world became second nature, and you still dislike unannounced visitors. As an adult you need a home that feels safe, private and emotionally honest, a place where you can retreat and recover fully. You are the one in the family who knows what nobody says aloud and stays calm in a crisis when others fall apart. Holding onto family grudges, or keeping too much locked away, is the cost. When your home is wholly yours, it becomes a place of deep healing and renewal.",
      "sagittarius": "Early home life for you often included travel, cultural mixing or strong beliefs, such as growing up between two worlds or moving around a great deal. Home rarely feels like a fixed point, more like a base camp between adventures. In adult life you want space, full bookshelves, a map on the wall and an open door for friends from everywhere. You are the family philosopher, the one who brings back stories and new ideas from every trip. Staying put for too long can make you feel trapped, and relatives sometimes read that as not caring. Your inner foundation rests on faith, humour and a sense of meaning, which you carry with you wherever you live.",
      "capricorn": "Early home life for you was often marked by structure, responsibility or emotional reserve, and many people with this sign strong grew up fast. You were often the sensible child who looked after younger siblings or worried about money at the kitchen table. As an adult you want a home that feels solid, well-managed and secure, ideally one you own outright. You are the family's backbone, the person everyone calls when something needs sorting. Emotional openness takes practice when you learned early to keep feelings to yourself. Over the years your home becomes a lasting achievement, built with care for those who come after you.",
      "aquarius": "Your early home was often unconventional, with unusual parenting, frequent changes or a feeling of not quite belonging. Later you create a home that feels like a community hub or a living experiment, with friends passing through and odd gadgets on every shelf. Freedom within your own space is essential to your wellbeing, and you resist family traditions that feel forced. You are the one who questions how things have always been done. Emotional distance is the catch: you keep loved ones at arm's length while caring deeply underneath. Home works for you when it is a place where everyone can be themselves, including you.",
      "pisces": "Early home life for you was often fluid, spiritual or confusing, shaped by a sensitive, artistic or absent parent. You learned to sense unspoken feelings and to escape into imagination when things got hard. As an adult you need a peaceful, dreamy sanctuary, ideally near water or filled with art, music and soft light. You are the family's empath, the one who absorbs everyone's moods and forgives easily. Boundaries are the struggle, since relatives can drain you before you notice. Your inner foundation rests on faith and imagination, and a home that honours both feels like a true refuge from the noise of the world."
    }],
    ["signs.*.career", {
      "aries": "You work best when you are the one who gets to start things. Hand you a blank page, a new venture or a crisis nobody has claimed, and you are on the phone before the meeting has finished. Entrepreneurship, emergency services, sport, surgery, sales and any role that pays for initiative suit you, because they reward the speed you already have. People come to see you as the self-starter who moves things while everyone else is waiting for permission. Recognition arrives when you are first, or when you take the risk others stepped around. Your weak spot is the long middle of a project and the slow hierarchy above you: months of sign-off chains drain you faster than any amount of hard work. You need a role with a front line to stand on.",
      "taurus": "You build a working reputation by being the person whose work holds up. Colleagues bring you the job that has to be right the first time, and you deliver it without drama, as promised. Finance, property, food, design, horticulture, craft, music and work with the voice all suit you, because each lets you make something tangible that lasts. Progress for you comes in steady layers rather than leaps, and the flashy offer that asks you to uproot everything rarely tempts you. Recognition is slow to arrive and then very hard to shift. The trap is staying in a comfortable post long after it stopped growing you, telling yourself that security is the same as satisfaction. Your best work comes from pride in quality you can touch.",
      "gemini": "Your working life rarely fits on one line of a CV. Often you are doing two jobs at once, or a job plus a side project plus the newsletter you write at midnight, and you can change direction entirely more than once. Writing, teaching, media, marketing, sales, translation, technology and transport suit you because they run on words, movement and fast learning. People know you as the one who grasps a new brief in an afternoon and can explain it to anyone by the evening. Recognition comes through your voice, your ideas and your knack for connecting people who need each other. Trouble starts when variety turns into restlessness and you leave just before mastery pays off. Boredom, far more than difficulty, is what makes you hand in your notice.",
      "cancer": "A caring instinct comes with you into every workplace, and people notice it within a week. You are the one who remembers the new starter's name, keeps biscuits in the drawer and covers for a colleague having a hard month. Nursing, hospitality, early years education, social work, property, food, history and counselling all suit you because they let you look after people or preserve what matters. Teams with a family feeling bring out your loyal and surprisingly inventive side. Recognition comes when others feel held by you. The shadow is taking criticism of your work as criticism of you, and staying too long with an employer out of loyalty rather than fit. Where you feel safe, you build something that outlasts you.",
      "leo": "You want your work to carry your name, and you do your best when people can see you doing it. Presenting, leading a team, pitching to a room or putting on a show lights you up in a way no back office job ever will. Performing arts, entertainment, management, teaching, design and work with children suit you, along with anything you can call your own creation. Others read you as warm and authoritative, the person they follow into a new idea. Recognition matters to you, and it comes through personal style, generous leadership and work you are proud to sign. A role where your effort disappears into someone else's credit wounds you more than you admit. Given a stage and some trust, you make everyone around you shine too.",
      "virgo": "You are the colleague who spots the error on page forty that three other people signed off. Work built on skill, accuracy and useful service suits you: health care, research, editing, accounting, nutrition, IT, administration and the skilled trades. People come to rely on you as the quiet expert who knows how the system works and what needs fixing next. Recognition comes from competence, and from making things run so smoothly that everyone else can finally relax. Less happily, you take on the invisible tasks nobody else wants and then feel unseen for doing them. Perfectionism can also keep a finished piece of work on your desk for one more check. Your calling is improvement, done with care, in something that helps.",
      "libra": "You do well wherever people, beauty or fairness sit at the centre of the work. You are the one who smooths the tense client call, rewords the email so nobody takes offence and notices that the slide deck clashes. Law, mediation, design, fashion, the arts, human resources, diplomacy and client facing roles all suit you. People see you as polished, pleasant and fair, and they trust you to find the arrangement that works for everyone. Recognition comes through partnerships and collaboration rather than solo heroics. Under pressure, keeping everyone content can matter more to you than saying what you think, and decisions stall. Working alongside a good partner, you produce your most elegant and most confident work.",
      "scorpio": "Work that goes beneath the surface draws you, and shallow jobs feel unbearable. Give you a problem others avoid, a set of accounts that does not add up or a person in crisis, and you focus completely. Psychology, research, medicine, finance, crisis work, investigation and anything involving hidden resources suit you. Colleagues see you as private, intense and highly capable, the one they call when things turn serious. Recognition comes from handling what others cannot face, and from holding power responsibly when it lands in your hands. Office politics are harder: you read every undercurrent and can become guarded or controlling when trust is thin. At depth, your work transforms things.",
      "sagittarius": "You need your work to mean something larger than the task list. A job that stays inside four walls and one small question starts to feel like a cage within months. Teaching, publishing, law, tourism, higher education, religion, international business and coaching all suit you because they give you scope and a message to carry. People see you as knowledgeable and inspiring, the one who gets a tired team believing in the plan again. Recognition comes through big ideas, broad experience and your ability to rally others around a shared vision. Detail is your blind spot: deadlines slip and admin piles up while you are busy thinking about the next horizon. Given freedom and a purpose, you become a guide for others.",
      "capricorn": "Ambition sits comfortably in you, and you want a standing in the world that you have earned. You are the one who learns how the whole organisation works, takes the extra responsibility and is running the department five years later. Management, law, government, finance, engineering, architecture and running your own business all suit you. People see you as capable and serious, often older than your years. Recognition comes slowly and lasts, built on proven results and authority accumulated with patience. The difficulty is making work your whole identity, measuring every week by output and struggling to switch off on holiday. Built patiently, your career becomes a structure other people can rely on.",
      "aquarius": "Work that changes how things are done appeals to you far more than work that merely keeps them running. In your first month you are already proposing a new system and questioning the rule everyone else follows. Science, technology, social justice, community organising, astrology and unconventional entrepreneurship all suit you. Colleagues see you as original and forward thinking, sometimes a step too far ahead for the room. Recognition comes through ideas that reshape systems and through collaboration with groups who share your vision. A certain detachment can make you seem cool or contrary, and resistance to authority can cost you allies you need. Among like-minded people with a cause, your inventiveness becomes remarkably practical.",
      "pisces": "Your working life rarely follows a straight line, and the most important turns often come through a hunch rather than a plan. Creative, healing or spiritual work draws you, where something you feel can become something others feel too. The arts, film, music, health care, therapy, charity, marine work and spiritual guidance suit you. People see you as intuitive and compassionate, the one a distressed client asks for by name. Recognition follows a winding path, arriving through artistic vision, quiet service and your ability to move people. Structure is where you struggle: vague roles, blurred hours and absorbing everyone's stress leave you exhausted. Given meaning and some protected time, your sensitivity becomes your professional strength."
    }],
    ["signs.*.money", {
      "aries": "You earn best through your own initiative, and you would rather build income by your own efforts than wait for anyone to hand it over. A new side venture, a commission, a bold ask for a pay rise: money moves when you move. It leaves just as quickly, though, and the impulse purchase made at eleven at night is a familiar story. Budgets feel like a cage, so you ignore them until the account is alarmingly thin. Your sense of worth rises when you take a brave step and see a direct, visible result. Patience is the real stretch, since slow compound growth bores you. Once you let one decision run long enough to pay off, you discover how much your courage is worth.",
      "taurus": "Money and safety are closely linked for you, and you feel it in your body when the balance drops. You earn steadily, save well and would rather own one beautiful coat that lasts a decade than five cheap ones. Building resources comes easily, and you often have a quiet reserve that nobody else knows about. Comfort, quality and the pleasure of well made things matter to you. The risk is holding on too tightly, whether to possessions, a savings figure or a job that no longer fits, because letting go feels unsafe. Sensible changes can stall for months while you wait to feel certain. Your deepest worth rests on the steadiness you carry inside, and money follows it.",
      "gemini": "You rarely have one source of income for long. Money comes through communication, trade, ideas or several small streams at once, and it arrives and leaves in bursts. You can talk your way into a good deal and then forget which subscription you signed up to in March. Information feels as valuable to you as possessions, and you happily spend on books, courses and gadgets that promise to teach you something. Chasing every opportunity that catches your eye leaves little time for any of them to grow. Your mind is an asset, and your worth grows when you trust it enough to charge properly for it. Two or three well chosen threads serve you far better than ten.",
      "cancer": "Money is emotional for you, bound up with home, family and the feeling of being safe. You save for a rainy day, keep the birthday cards and the old family teapot, and feel uneasy without some cushion in the bank. Income often comes through care, food, property or a family business. Your spending rises and falls with your mood, and a bad week can end with a basket of comfort buys. You also give generously to the people you love, sometimes more than you can spare. Self-worth grows when you feel secure within and stop measuring your value by how much you provide for others. Once you feel at home in yourself, your finances steady too.",
      "leo": "You spend with your heart, and it shows. The generous round of drinks, the gift that is slightly too extravagant, the outfit that makes an entrance: money for you is a way of expressing warmth and style. Income comes through creativity, leadership or being visible, and you earn best when your name is on the work. Pride and money are closely linked, so a pay cut or a rejected invoice stings far beyond its actual size. The shadow is spending to be seen, keeping up appearances when the account is asking you to stop. Your worth grows when you value yourself from the inside, independent of applause or outward displays of status. Then your generosity becomes sustainable.",
      "virgo": "You are careful and methodical with money, and your spreadsheet often has more tabs than anyone else's. You research a purchase for weeks, compare reviews and still feel faintly guilty after buying it. Income comes through skill, service and detailed work, the kind that depends on your accuracy. Worth can feel tied to how useful you are, so you undercharge, offer extra hours for free and apologise when sending invoices. That quiet modesty keeps your earnings below what your expertise deserves. Worry about money can also run on long after the numbers are fine. You grow when you charge fairly for your care and accept that doing a thing well deserves proper payment.",
      "libra": "Beauty, company and shared experiences are where your money goes, and a well laid table or a lovely weekend away feels like money well used. Income often comes through partnerships, design or people facing work, and you earn more alongside the right collaborator. Fairness matters a great deal to you: splitting the bill evenly, paying people properly, keeping arrangements balanced. Trouble arises when you avoid a money conversation to keep the peace, agreeing to a fee that feels wrong because negotiating feels unkind. You can also judge your worth by other people's approval. Self-worth grows when you trust your own sense of what things are worth and say the number out loud.",
      "scorpio": "You are strategic and private about money, and very few people know what you earn or own. Income often comes through research, shared resources, investments or crisis work, and you are good at seeing value where others see only risk. Money carries emotional weight for you, bound up with power, control and never being left dependent on anyone. You keep a reserve and a plan B, and you notice immediately when someone is careless with joint finances. The shadow is holding on out of fear, gripping resources or secrets long after they could be shared. Self-worth grows when you trust your own resilience, knowing you have rebuilt before and could again.",
      "sagittarius": "You are generous and optimistic with money, sometimes more optimistic than the balance can support. You would rather spend on a flight, a course or a long lunch with friends than on things that sit in a cupboard. Income often comes through teaching, travel, publishing or international work. Money feels like freedom to you, fuel for the next adventure. Big plans get funded before the details are checked, and promises about repaying or saving drift. You also trust that luck will turn up, and it often does, which only reinforces the habit. Self-worth grows when you match your ideals with practical planning, so that your generosity stands on something solid.",
      "capricorn": "You are disciplined and long-sighted with money, often from a young age. You plan carefully, buy quality and build resources gradually, with a clear idea of where you want to be in ten years. Income comes through management, structure or hard-won expertise, and you rarely expect anything to be handed to you. Financial security feels like proof that you are handling life properly. Too often you equate your worth entirely with your achievements, working longer and saving harder while enjoyment waits for a later date that keeps moving. Spending on pleasure brings a flicker of guilt even when you can well afford it. You come into your own once you value yourself for who you are as well as for what you achieve.",
      "aquarius": "You approach money unconventionally, and your financial life rarely looks like anyone else's. Income comes through technology, groups, innovation or causes you believe in, and you happily skip the conventional ladder if it bores you. Spending can be erratic: nothing for months, then a sudden investment in a gadget, a project or a friend's start-up. Money matters to you mainly as a means of independence. Any system that feels imposed gets resisted, including the sensible ones, so savings and paperwork drift. Your worth grows when you recognise your originality as a dependable resource and build simple structures that still leave plenty of room for freedom.",
      "pisces": "You are generous and sometimes vague with money, and it slips away without clear limits. You lend to the friend in trouble, give to the cause that moved you, and only later realise the rent is due. Income often comes through art, healing, care or intuition, work where value is hard to put a price on. Checking your balance can feel so uncomfortable that you avoid it for weeks. Underneath sits a quiet belief that caring about money is somehow unspiritual, which leaves you undercharging and underprotected. Your worth grows when you value your sensitivity and gifts as assets. Simple, practical systems around your finances protect those gifts rather than dimming them."
    }],
    ["signs.*.growth", {
      "aries": "You grow by learning to pause. Your speed is a gift: you act while others are still discussing, and you get things started that would never have happened otherwise. What happens after the start is harder, when the novelty fades and the half-finished projects gather in a corner. Growth for you means taking one more breath before you reply, considering who else is affected, and staying with a task until it is done. Patience does not dampen your courage; it gives it staying power. When you manage both, people trust you with bigger and more lasting responsibilities, and your victories stop needing to be fought twice.",
      "taurus": "You grow by discovering that change can nourish you rather than threaten you. Your steadiness is valuable, and people lean on it, yet the same quality keeps you in a flat, a job or a friendship long past its season. You know the moment well: something has stopped fitting, and you decide to wait one more year. Growth begins with small, chosen changes, a new route, a new skill, a single honest conversation. Each one shows you that the ground holds. Over time you find that your security was never in the familiar surroundings at all, but inside you, and that you can carry it anywhere you go.",
      "gemini": "Depth is your growth edge. Your curiosity is a gift, and you can hold a lively conversation on almost anything after reading two articles. Then there is the browser with forty tabs open and none of them finished, the hobby dropped just as it was getting interesting. Real progress arrives when you stay with one question long enough to find its roots, even through the dull middle stretch. Choosing fewer commitments and following them through turns scattered talent into expertise. People start to trust you in a deeper way once they see you finish. Your quick mind becomes wisdom, and your words carry weight.",
      "cancer": "You grow by learning that caring for yourself matters as much as caring for everyone else. You are the one who notices who is upset at the dinner table and makes them a plate, while your own needs wait unspoken. Hoping someone will notice, then feeling hurt when they do not, is a pattern you know well. Maturity comes when you name your needs directly and trust that asking is not a burden. The past, too, is something you hold close, and it can teach you without keeping you in place. Your sensitivity is a strength, and it becomes emotional authority when you include yourself in its care.",
      "leo": "Your growth edge is learning to shine without needing constant confirmation. Your warmth is real and powerful, and a room brightens when you are in good form. The sore spot shows up in the silence after a presentation, or when someone else gets the praise, and you feel diminished far more than the moment deserves. You deepen when you share the stage, celebrate other people's wins without keeping score and hear honest feedback as useful rather than wounding. A little humility gives your natural radiance a sturdier foundation. Then the light you give out no longer depends on the applause coming back.",
      "virgo": "You grow by trusting that good enough is often good enough. Your discernment is valuable: you see the flaw, the gap and the better method before anyone else. Yet you point the same eye at yourself, rereading the email five times and lying awake over the one thing that went slightly wrong. Discernment paired with self-compassion is where you flourish, letting a task be finished rather than perfect. Letting go of constant fixing frees energy for rest, faith and plain enjoyment. Your worth reaches far beyond your output, and learning to feel that is your quiet revolution.",
      "libra": "You grow by learning that honesty can be a form of kindness. Your gift for harmony is real: you read a room instantly and know how to bring tense people together. You also know the restaurant chosen because nobody would decide, and the plan you agreed to while privately wishing for something else. Growth comes when you let others know what you want, even at the risk of disapproval. Choosing, clearly and without apology, turns diplomacy into integrity. Your relationships become more genuine and far more durable once people meet the real you rather than the most agreeable version.",
      "scorpio": "Trust is your growth edge. Your depth and perception are powerful, and you read people with unnerving accuracy. Alongside that runs the quiet testing: you hold back, watch how someone handles a small confidence, and keep a mental record of every slight. Things open up when you allow vulnerability without demanding proof first, and when you release old grudges that cost you more than the person who caused them. Letting some things stay light, a joke, a small mistake, a passing mood, is part of it too. Intimacy then starts to feel safe rather than dangerous, and your heart becomes noticeably lighter.",
      "sagittarius": "You grow by pairing vision with commitment. Your enthusiasm lifts people, and you are often the one who talks everyone into the trip, the project or the fresh start. Later the details arrive, and by then your attention has already moved to the next horizon. Maturity means staying the course, answering the boring email and keeping the promise you made on a high. Listening matters as much as teaching, since you can be so sure of the big picture that you miss what is said in the room. Often the wisdom you travel so far to find turns out to be in the people right in front of you.",
      "capricorn": "Softness is your growth edge. Your discipline and ambition are strengths, and you are usually the person who carries the heaviest load without being asked. Rest feels like slacking, help feels like weakness, and feelings get postponed until the work is done, which it never quite is. Growth comes when you let yourself stop, receive support and feel emotions fully instead of managing them. Success means far more when it is shared with people you have let close. Joy is no reward waiting at the summit; it is part of what makes the climb worthwhile at all.",
      "aquarius": "You grow by letting feelings in. Your vision and independence are gifts, and you can see where a whole community or system needs to go. Closer to home it is harder: when someone you love wants comfort rather than a solution, you can feel oddly out of reach, retreating into ideas. Closeness can seem like a threat to the freedom you guard so carefully. Warmth grows when you allow intimacy without fearing a loss of self, and when you care for the individual in front of you as well as the collective. Your ideals become real, and your relationships noticeably warmer.",
      "pisces": "You grow by building boundaries. Your compassion and imagination are gifts, and people instinctively bring you their troubles, sometimes before they have even said hello. You absorb it all, leaving a conversation carrying someone else's mood for the rest of the day. Strength comes when you protect your energy and learn where you end and others begin. Grounding your dreams in practical steps, a date, a budget, a first draft, lets them arrive in the world. You can then help people without drowning in their troubles, and your sensitivity becomes a lasting gift to everyone around you."
    }],
    ["solarReturn.asc", {
      "aries": "With Aries rising in your return chart, the year ahead moves at your pace, and your pace is fast. You wake up wanting to start things: the project you have talked about for two years, the running plan, the conversation you keep postponing. Patience runs thin, and you catch yourself finishing other people's sentences or leaving the queue rather than waiting. That impatience is also your engine, because in the next twelve months you act before doubt has time to vote. Bumps, burns and sharp words come from rushing, usually on days when you skipped breakfast and pushed through anyway. By your next birthday you have proof, in something begun and kept going, that courage is a habit you can build.",
      "taurus": "This year settles into a slower, steadier rhythm with Taurus rising in your return chart. You want things you can touch: a savings figure that grows each month, a garden bed, a sofa you finally sit on without guilt. Your body sets the agenda more than usual, asking for good food, proper sleep and time outdoors, and you notice quickly when it is ignored. Progress feels gradual, yet what you build over these twelve months is still standing years later. The catch is inertia, the evening you stay in the familiar job or the familiar argument because moving costs effort. Staying loyal to what feeds you, and letting the rest go, makes this one of your most prosperous years.",
      "gemini": "Gemini rising gives the year ahead a quick, chatty, crowded feel. Your phone fills with messages, your diary with short trips, and you find yourself with three books open and two courses half started. Curiosity carries you into conversations with neighbours, siblings and strangers on trains, and several of those chats turn into openings. You think fast and talk your way into rooms you would not have entered last year. The cost is scatter: the email you meant to send, the idea dropped the moment a shinier one arrived. When you pick two or three threads and follow them properly, the next twelve months teach you more than any single year in recent memory.",
      "cancer": "With Cancer on the Ascendant of your return, the year turns inward and homeward. You feel the pull of your kitchen, your people and the rooms where you can shut the door, and outside ambitions matter a little less for a while. Family matters take serious time: a parent who needs you, a move, a spare room turned into a nursery or a study. Your feelings sit closer to the surface, so an old song or a smell from childhood can undo you in the supermarket aisle. The hard part is guarding your softness so tightly that you retreat into sulks instead of saying what hurts. Making a safe base this year gives you something to stand on for the years that follow.",
      "leo": "Leo rising puts you in the spotlight this year, whether you asked for it or not. People notice when you walk in, remember what you said and come to you for warmth and a lift. Creative work, romance, children or a stage of some kind bring joy, and you find yourself dressing up for the pleasure of it. Confidence grows as you let yourself be seen, and a generous gesture from you lands further than you expect. Pride is the sore spot, so a missed compliment or an unanswered message stings more than it should. Pleasure is serious business in the next twelve months, because your own delight is what draws good things towards you.",
      "virgo": "With Virgo rising in your return chart, the year ahead has a practical, tidy, get it sorted feel. You clear the drawer, fix the spreadsheet, book the dental check and build the morning routine you have talked about for ages. Work and health take up much of your attention, and small daily adjustments add up to changes you feel in your body and your bank balance. You are more useful than ever, and people bring you their problems because you solve them. The shadow is the inner critic, which notices every flaw in your work and a few that are not there. Aimed at the task rather than at yourself, that sharp eye makes this a year of real, lasting improvement.",
      "libra": "Libra rising makes other people the centre of your year. A partner, a business ally, a client or a new love shapes the next twelve months, and you learn a great deal about yourself through them. Contracts, agreements and joint decisions come up often, and you find yourself negotiating everything from the rent to who hosts Christmas. You also want your surroundings to be beautiful, so you repaint, rearrange or spend more on art and clothes than usual. Keeping the peace comes easily, sometimes too easily, and you catch yourself agreeing to things you quietly resent. The real balance this year includes your own needs on the scale, spoken plainly and early.",
      "scorpio": "With Scorpio on the Ascendant of your return, the year ahead runs deep. Small talk bores you, and you want the real story from friends, lovers and colleagues, even when it is uncomfortable to hear. Trust, intimacy, shared money and power come to the surface: a joint account, a debt, an inheritance or a relationship that has to become honest or end. You read people more accurately than usual and keep more of your own business private. The difficulty is suspicion, the late night spent turning over a text message for hidden meaning. Something in your life finishes during these twelve months, and what replaces it is truer and more your own.",
      "sagittarius": "Sagittarius rising opens the year ahead like a window. You want room, distance and a bigger view, so plans appear for travel, study, a course, a pilgrimage or a move somewhere with more sky. New people bring new ideas, and you find yourself debating philosophy in a café or rewriting what you believe about work and faith. Optimism runs high, and you say yes before checking the calendar. The risk is overpromising, then spending the autumn racing to deliver three things you agreed to over one long dinner. With one eye on practical limits and curiosity steering the rest, you reach your next birthday with a world that is visibly larger.",
      "capricorn": "With Capricorn rising in your return chart, this is a serious year with real work in it. Career, responsibility and long range plans take the lead, and you are tested before you are rewarded. You take on the role nobody else wanted, stay late to get the structure right, and learn how much you can carry. Recognition comes slowly and is earned properly, which is why it lasts. Feelings get filed away for later, and the people who love you notice you are tired long before you admit it. The year rewards stamina over sprints, and what you build at a steady pace now becomes the foundation for the next several years.",
      "aquarius": "Aquarius rising brings an unconventional, restless and forward looking year. You break a routine that has run for years, change your hair, try a new technology or join a group you would once have mocked. Friends and communities matter more than usual, and a surprise call or a sudden change of plan redirects things more than once. You feel less willing to obey rules that make no sense and more willing to be the odd one out. The difficulty is detachment: in the rush to be free, the people closest to you feel held at arm's length. Warmth turns your experiments into discoveries, and this year shows you a version of yourself that fits far better.",
      "pisces": "With Pisces rising in your return chart, the year ahead is softer, slower and more intuitive. You feel the mood of a room the moment you enter it, and other people's sadness follows you home unless you shake it off. Music, art, water, prayer or quiet walks become essential rather than optional. Plans shift or dissolve, and the more tightly you grip them the faster they slip away. The shadow is fog: missed emails, vague promises and a habit of escaping into screens or a second glass of wine. Your imagination and your compassion are reliable guides this year, and with a few firm edges in place, something meaningful takes shape out of the haze."
    }],
    ["solarReturn.sunHouse", {
      "1": "With the return Sun in your first house, this year is about you. You feel more visible, more confident and more ready to say what you want out loud. A new haircut, a new wardrobe or a new start signals the change, and people respond to your initiative faster than they used to. Decisions you have deferred for years get made in a single afternoon. The risk is tunnel vision, where your plans crowd out a partner or friend who needed a little attention too. Over the next twelve months, showing up as yourself and acting on your own wishes sets your direction for years ahead.",
      "2": "The Sun lands in your second house this year, so money, possessions and self-worth take centre stage. You check your balance more often, renegotiate your rate, start a savings pot or sell the things you no longer use. Underneath the numbers sits a bigger question of what you are worth and what you value. Steady, practical effort pays off, and a skill you develop now becomes something people happily pay for. The difficulty is letting anxiety drive your spending, or refusing yourself small comforts out of fear. By your next birthday your finances and your values line up far more closely than they do today.",
      "3": "With the return Sun in your third house, the year ahead is full of words, trips and conversations. You write, teach, study, post or talk far more than usual, and the car or the train becomes a second office. Siblings, neighbours and your local area play a bigger part, and a chance chat at the school gate or the corner shop turns into an opening. Your mind runs quickly and learns with ease. The cost is busyness without direction, twenty half-finished threads and a head that never quite goes quiet. A course, a regular writing habit or a single clear message pursued over these twelve months pays you back for years.",
      "4": "The return Sun in your fourth house turns this year towards home, family and roots. You move, renovate, clear out a parent's loft or spend more evenings at the kitchen table than in the office. A parent or relative needs your attention, and old family patterns show themselves in how you argue and how you comfort. Outward success matters less for now, while private foundations matter more. The hard part is feeling that life has stalled while friends seem to be racing ahead. Time spent at home in the next twelve months is no detour, because it builds the ground you will stand on in more public years.",
      "5": "With the Sun in your fifth house this year, joy is the point. Romance, children, hobbies, performance and creative projects take centre stage, and you feel more playful than you have in a long while. You sign up for the dance class, finish the painting, flirt a little more boldly or spend Saturdays making things with a child. A creative risk taken now opens doors you did not know existed. The shadow is drama, needing applause for everything or chasing a thrill that costs more than it gives. In the next twelve months pleasure becomes part of your purpose, and you come out of the year feeling fully alive.",
      "6": "The Sun in your sixth house puts work, health and daily routine at the centre of the year ahead. You change jobs, take on new duties or overhaul the way your days run, from the alarm clock to the lunch you pack. Small habits bring large effects: a daily walk, an earlier bedtime, a better filing system. You find lasting satisfaction in being useful and in doing a job properly. Overwork is the danger, and it shows up as a stiff neck, poor sleep or a cold that will not shift. A pet or a simple ritual brings comfort, and the ordinary days of these twelve months are where your real change happens.",
      "7": "With the return Sun in your seventh house, partnerships dominate this year. A significant relationship begins, deepens, is formalised or is tested, and business partners and clients play a large role too. You learn who you are through other people, sometimes in tender cooperation and sometimes in a row over whose turn it is to compromise. Contracts deserve careful reading, and negotiations take up serious time. It becomes hard to know your own mind when someone you love holds a strong opinion. The next twelve months bring you an ally, someone who supports who you are becoming and listens when you say plainly what you need.",
      "8": "The Sun in your eighth house gives the year ahead depth, intensity and a sense of transformation. Intimacy, trust and shared money come into focus: a mortgage, a debt, taxes, an inheritance or a frank talk about who pays for what. An ending or a loss clears space for something new, even when it hurts at first. You see beneath the surface of people and situations and cannot unsee what you find. Control is the trap, gripping tighter when letting go is the only way through. Therapy, research, financial restructuring and honest conversations all pay off, and you finish this year stronger and far more honest with yourself.",
      "9": "With the Sun in your ninth house, this year is about growth and wider horizons. Travel, study, teaching, publishing, law or spiritual exploration features, and you feel hungry for meaning. You book the long haul flight, enrol on the course, or find yourself reading at midnight about a philosophy you had never heard of. A mentor appears just when you need one, and your beliefs shift as you meet new people and places. Restlessness grows whenever life feels small or routine. Over the next twelve months, following curiosity further than you have gone before gives you a fresh sense of what your life is for.",
      "10": "The return Sun in your tenth house makes career and public standing the headline of the year. Your work is noticed, for better and for worse, and a promotion, a new title or a public milestone is within reach. You set goals, step up in meetings and take responsibility for your reputation in a way that feels natural rather than forced. A boss, a parent or a senior figure plays a pivotal part. Ambition has a blind spot, though, and you climb hard without checking whether the ladder leans against the right wall. When the path is one you want, this year puts you somewhere visible and earned.",
      "11": "With the Sun in your eleventh house, friends, groups and future hopes define the year ahead. You join a club, a team, a campaign or an online community, and find people who share your ideals. Invitations arrive, and saying yes to the ones just outside your comfort zone brings your best opportunities. Your picture of the future sharpens, and you notice which friendships still fit and which have run their course. There is a pull towards blending into the group rather than bringing your own voice. The people and visions that inspire you repay every hour you give them, because during these twelve months friends hand you your most valuable leads.",
      "12": "The Sun in your twelfth house makes this a quieter, more inward year. Much of the real work happens behind closed doors or inside you: rest, reflection, therapy, prayer or a creative project nobody sees yet. You need more sleep and more solitude, and crowded weekends leave you drained for days. Old patterns and old griefs surface so they can finally be released. Feeling invisible is the hard part, particularly when others seem busy making their mark. Dreams and intuition speak loudly now, and what you prepare in private over the next twelve months emerges into the light after your next birthday."
    }],
    ["solarReturn.angular", {
      "sun": "With the Sun on an angle of your return chart, this year is personal and highly visible. Your identity, goals and choices are on show, and people know what you are doing even when you have not announced it. Which angle it sits on tells you where you shine: yourself and your image, your home and family, a key partnership, or your career and public role. You feel more purposeful and more certain about what matters to you. Scrutiny comes with the light, and criticism lands harder because you are so exposed. Over the next twelve months, acting from who you are makes this a defining year.",
      "moon": "An angular Moon in your return chart puts feelings, family and changing circumstances at the front of the year. Moods move like tides, and your energy depends heavily on how safe and cared for you feel at home. A move, a change in the household, a new baby or a parent's needs often feature, and the public sees your emotions more than you would like. You respond to people with unusual warmth and intuition. Instability is the cost, with plans that change weekly and reactions you regret by morning. Anchoring yourself in simple routines and trusted people carries you through a tender, rewarding year.",
      "mercury": "With Mercury on an angle of your return chart, the year ahead is busy with words, paperwork and movement. Emails, calls, forms, contracts and short trips pile up, and you find yourself explaining the same thing to five different people in a week. Decisions made in conversation carry more weight than usual, so a single chat or a signed document shifts your direction. Your mind is quick and you learn fast, whether it is a language, a system or a new role. Nerves fray under the constant input, and you lie awake replaying what you said. Clear communication becomes your strongest tool this year, and your words open useful doors.",
      "venus": "An angular Venus sweetens the year ahead. Affection comes easily, invitations arrive, and you find yourself smoothing over tensions that would once have become rows. Relationships, beauty, art or money bring noticeable blessings, from a new romance to a pay rise or a home that feels lovely to walk into. People like being around you, and you like being liked. Too much ease has its own price: overspending, overindulging or avoiding a necessary conflict to keep the mood pleasant. You enjoy the grace of these twelve months fully, and it strengthens the relationships and values that matter to you.",
      "mars": "Mars on an angle of your return chart gives you a driven, energetic and sometimes combative year. You want things done now, and you take the initiative at work, at home or in a relationship where you have waited long enough. Physical energy runs high, so training, building or clearing out the garage feels satisfying. Arguments flare faster than usual, and you snap at the slow driver or the colleague who stalls. Haste causes the cuts, bumps and overcommitments that end up slowing you down. Aimed at a clear goal, this fire makes the next twelve months among the most productive you have had.",
      "jupiter": "An angular Jupiter is one of the happiest signatures your return chart can show. Growth and opportunity arrive in the area the angle describes: a bigger role, a larger home, a widening circle or a relationship that expands your world. Generous people cross your path, and you feel more generous in turn, picking up the bill or saying yes to a friend's big idea. Luck seems to favour you when you act with confidence. Excess is the catch, taking on too much, spending freely or trusting that everything will work out. The expansion of these twelve months comes readily, and it lasts when your feet stay on the ground.",
      "saturn": "With Saturn on an angle of your return chart, the year ahead is serious, demanding and built on effort. Responsibility arrives in a concrete form: a promotion with more weight than glamour, a family duty, a mortgage, a deadline that will not move. You work harder than usual and notice every limit on your time, money and energy. Rewards come slowly, but what you build now serves you for years. Loneliness or heaviness creeps in on bleak evenings when nobody seems to see how much you are carrying. Steady commitment through these twelve months leaves you with foundations you are proud of.",
      "uranus": "An angular Uranus brings surprises, sudden change and a strong push for freedom into the year ahead. A job ends, a new one appears, you move on a whim, or someone unexpected walks into your life and rearranges it. You feel restless in any situation that fences you in and bored by routines you once liked. Your ideas are original, and people meet a more independent version of you. The downside is volatility, with decisions made in a flash and plans that shift the week before they happen. The doors that open overnight this year often lead where you need to go, and you are at your best when you let the plan bend.",
      "neptune": "With Neptune on an angle of your return chart, the year ahead feels dreamy, inspired and uncertain in equal measure. Music, art, spirituality and compassion rise, and you are moved by things that used to pass you by. Your intuition is strong, and you sense what others feel before they speak. Clarity is harder: contracts blur, plans drift, and saying no to someone who needs rescuing feels almost impossible. Confusion, fatigue or disappointment follow when you idealise a person or a project. Firm boundaries and a few reliable facts let the inspiration of these twelve months become something real.",
      "pluto": "An angular Pluto marks an intense, transformative year for you. Power dynamics come to the surface at work, at home or in love, and you see clearly who holds control and why. Something ends, sometimes painfully, and the ending strips away what was false. You feel a deep drive to change your life at the root rather than at the edges. Obsession and power struggles are the trap, gripping tighter when release is the real way forward. By your next birthday you are stronger, more authentic and far less willing to live half a life."
    }],
    ["solarReturn.moonHouse", {
      "1": "With the solar return Moon in your first house, this is a year when your feelings show on your face before you have decided to share them. Friends read your mood the moment you walk into a room, and you notice your own reactions faster too: the flush of irritation in a queue, the sudden tears at an advert. Your needs come to the front, so you rest when tired, eat when hungry and step outside when a room gets crowded. Pretending to be fine stops working, and that honesty is a gift. The harder part is feeling exposed, as if everyone can see what you meant to keep private. By your next birthday you know yourself better for having stopped hiding it.",
      "2": "Your solar return Moon sits in the second house, so this year your sense of safety is tied closely to money, belongings and what you feel you are worth. You check your bank balance more often than usual, and a good month leaves you calm in a way that surprises you. On a low day, a basket of small purchases feels like comfort, and the receipts tell the story of your moods. Income rises and dips, which unsettles you more than the actual numbers justify. Knowing what comes in, enjoying what you already own and valuing yourself apart from your earnings all steady you. By the end of the year you carry a firmer, quieter sense of your own worth.",
      "3": "With the solar return Moon in the third house, you work out how you feel by talking, texting and writing it down. You send long voice notes to a friend, replay conversations in your head on the bus, and fill pages of a notebook late at night. A sibling, cousin or neighbour becomes part of the year's emotional story, whether through a warm reunion or a quarrel that needs mending. Short journeys and a busy local life keep your spirits up. The trouble is a restless mind that scrolls and chatters to avoid sitting with a feeling. When you slow down enough to say what you mean, conversations this year heal more than you expected.",
      "4": "The solar return Moon in your fourth house puts home and family at the emotional centre of the year. You spend weekends rearranging rooms, feel a strong pull to be near parents or relatives, and sometimes move house or take someone in. Closing your own front door at night matters more than any invitation out. Family moods reach you quickly, and an old childhood feeling rises up over something as small as a comment at Sunday lunch. The difficulty is retreating so far into the nest that the wider world starts to feel like too much. Building comfort and privacy is the real work of this year, and it steadies everything else you do.",
      "5": "With the solar return Moon in the fifth house, your heart wants play, romance and something to create. You find yourself staying up late on a project purely because it delights you, or blushing over a new flirtation like a teenager. Children, whether your own or other people's, stir strong tenderness and occasionally strong frustration. Pleasure is not an indulgence this year, because it is what refills you. The shadow is taking every lukewarm response personally, since your feelings are so bound up with being enjoyed and admired. You say yes to the dance class, the date and the messy painting, and joy leads you somewhere you did not plan to go.",
      "6": "Your solar return Moon falls in the sixth house, linking your moods closely to work, health and the shape of your ordinary days. A cluttered desk or a skipped lunch sours your whole afternoon, while a tidy morning routine lifts you more than a big treat would. Stress lands in your body: a tight jaw, an unsettled stomach, poor sleep after a hard week. You want to feel useful, and a colleague's thanks means more to you than usual. The risk is working through exhaustion because being busy feels safer than feeling. When your days keep a steady rhythm of sleep, meals and reasonable hours, your emotional life settles too.",
      "7": "With the solar return Moon in the seventh house, your feelings this year run through the people closest to you. A partner's bad day becomes your bad day, and you notice every change in their tone over dinner. If you are single, the wish for a partnership grows sharper, and you feel the absence at weddings or on quiet Sunday evenings. Close friends and business partners carry similar emotional weight. Real intimacy and a sense of being met are what this year offers. Losing track of your own needs while tending everyone else's is the danger. Saying plainly what you want from a relationship becomes the year's quiet achievement.",
      "8": "The solar return Moon in the eighth house takes your emotional life into deep water. Intimacy, trust, shared money or a loss stirs feelings you usually keep locked away, and a single honest conversation at midnight changes how close you feel to someone. Old grief returns, sometimes over a song or a smell, asking to be finished rather than filed away. You want truth and closeness, and small talk leaves you cold. The shadow is suspicion, reading betrayal into silence or holding on tightly to control. When you let a safe person see what you are carrying, this year brings healing that goes right down to the roots.",
      "9": "With the solar return Moon in the ninth house, your spirits rise with every new horizon. A long journey, a course of study or a book that rearranges your view of life moves you more than you expected. The same streets and the same conversations leave you feeling cramped, and a flight search at eleven at night becomes a small emotional ritual. Someone from another culture or faith touches you deeply. The risk is restlessness, running towards the next adventure to avoid a feeling waiting at home. Meaning is what feeds you this year, and following it widens your heart as much as your mind.",
      "10": "The solar return Moon in your tenth house makes career and public life emotionally charged this year. Praise from a manager lifts you for days, and a critical email feels like a verdict on who you are. You are more visible, often stepping into a role that puts your name out front, and people notice your moods at work. Your ambitions carry feeling now, and you want a career that nourishes you rather than merely pays. Letting your reputation become your whole sense of worth is the trap. A private life where nobody expects you to perform is what keeps you whole through such a public year.",
      "11": "With the solar return Moon in the eleventh house, friendships and groups become the emotional heart of the year. You feel a sharp ache for belonging, and a group chat, a club or a shared cause gives you a sense of family. Friends turn up with support at the right moment, while one or two leave you drained and you finally notice it. Your hopes for the future stir strong feelings, and you catch yourself sketching plans late at night. Feeling lonely in a crowd, when a group does not see you, is the painful side. Choosing people who leave you lighter makes this a warm, hopeful year.",
      "12": "The solar return Moon in the twelfth house makes this a private, inward year for your feelings. You crave solitude, early nights and long walks alone, and a busy social diary leaves you strangely depleted. Old sadness surfaces without warning, on waking or in the quiet of a bath, and your dreams become vivid. Your intuition sharpens so much that you sense a friend's trouble before they say a word. The hard part is feeling invisible, or absorbing everyone's moods until you cannot tell which are yours. Quiet days are doing important work underneath, and you come out of this year lighter than you went in."
    }],
    ["solarReturn.moonSign", {
      "aries": "A solar return Moon in Aries gives your year a quick, fiery emotional pulse. You react fast, bristle at slow queues and feel restless whenever anyone tells you to wait. Your feelings come out straight and honest, which clears the air as often as it scorches it. A hard run, a boxing class or walking fast burns off frustration before it spills over. You start things on impulse, and some of those sudden beginnings turn out to be the best decisions of the year. The risk is burning a bridge in a moment of heat and regretting it by teatime. Courage is the feeling that carries you through.",
      "taurus": "With the solar return Moon in Taurus, your year has a steadier, slower emotional beat. You crave comfort, good bread, clean sheets and time outdoors, and these simple things settle you more than any grand plan. Sudden change feels unwelcome, and you dig in your heels when someone rushes you. Money and home comforts carry more emotional weight than usual, so a secure bank balance feels like a warm blanket. Others lean on your calm presence when life gets noisy. What holds you back is stubbornness, staying in a comfortable rut long after it has stopped serving you. Contentment grows from patience, and you finish the year feeling more rooted.",
      "gemini": "A solar return Moon in Gemini makes your emotional year light, curious and changeable. You sort out your feelings by talking, and your phone fills with long message threads and half-written notes. Variety keeps you buoyant, while a dull week makes you twitchy and irritable. Siblings, neighbours and chatty friends become good company for your moods. The trouble is how cleverly you talk yourself out of what you feel, explaining a hurt away before it has landed. You are funny, quick and easy to be around this year, and the moments you stop to name a feeling plainly are the ones that matter most.",
      "cancer": "With the solar return Moon in Cancer, your emotions run deep and tender this year. You want closeness, safety and a place where you belong, and you spend more evenings at home cooking for the people you love. Family matters enormously, and an old feeling about a parent or a childhood home rises up for healing. You are more nurturing than usual, and more easily hurt by a careless word. The difficulty is retreating into your shell and going quiet rather than saying you feel wounded. Letting yourself be looked after, as well as looking after others, gives this year its soft strength.",
      "leo": "A solar return Moon in Leo brings warmth, pride and a pressing need to be appreciated. You want to feel special, and a heartfelt compliment keeps you glowing all week. Creative projects, romance and time with children lift your mood, and you are happy to take the stage at a party or a work presentation. Your generosity is big this year, with gifts, praise and affection flowing freely. Sulking when your efforts go unnoticed, or turning a small slight into drama, is the pitfall. When you give recognition as freely as you want to receive it, your year shines.",
      "virgo": "With the solar return Moon in Virgo, your year's emotional tone is practical, thoughtful and busy. You feel best with a clear list, a tidy kitchen and the sense that you are helping. Sorting a cupboard or planning a week of meals calms you more than a night out ever could. Your health habits matter emotionally, and small improvements bring lasting satisfaction. Worry is the snag, creeping in at three in the morning and turning into harsh self-criticism over tiny mistakes. You are kind and useful to everyone around you this year, and you learn to offer yourself the same gentle patience.",
      "libra": "A solar return Moon in Libra makes harmony and connection emotionally central this year. You feel calmer in a beautiful room, with flowers on the table and pleasant company around you. Time with a partner or close friend matters more than usual, and a disagreement leaves you unsettled until it is smoothed over. You are fair, gracious and good at seeing both sides. The shadow is people pleasing, agreeing to plans you do not want and swallowing annoyance to keep the peace. Honest conflict, handled kindly, brings you a deeper balance than any polite silence, and your own needs take their place in the scales.",
      "scorpio": "With the solar return Moon in Scorpio, your feelings this year are intense and very private. You want depth, loyalty and truth, and small talk frustrates you. You pick up on hidden motives instantly and notice who went quiet when you walked in. A powerful release, a confession or a reconciliation becomes part of the year's story. You are fiercely protective of the people you trust. Holding a grudge long after it has stopped protecting you, and replaying an old hurt in the shower, keeps a wound open. You choose carefully who you let in, and those bonds grow deeper and more honest than before.",
      "sagittarius": "A solar return Moon in Sagittarius gives your year an optimistic, restless emotional tone. You need freedom, adventure and meaning, and even booking a trip lifts your spirits for weeks. Learning something new, a class or a big book, excites you like falling in love. Humour carries you through harder days, and your honesty makes you refreshing company. The catch is escaping difficult feelings by always looking to the next horizon, planning a getaway instead of having a hard conversation. Your year widens when adventure and feeling travel together, and you come home with a bigger heart.",
      "capricorn": "With the solar return Moon in Capricorn, your emotional tone this year is serious, controlled and self-contained. You hold feelings back to get the job done, and crossing items off a long list brings comfort. Achievement soothes you, and you keep working through evenings when others relax. People respect you for staying steady under pressure. The hard part is loneliness, carrying everything yourself because asking for help feels like weakness. Emotional maturity grows quietly, and by the end of the year you find a solid peace in your own competence, along with trusted people you let share the load.",
      "aquarius": "A solar return Moon in Aquarius brings a cool, independent emotional tone to your year. You need space, friendship and room to be exactly yourself, and clinginess makes you edge towards the door. You watch your feelings with curiosity rather than sinking into them, as though studying someone else's reactions. New communities, causes and ideas feel emotionally freeing. You surprise yourself with a sudden change of heart about something you thought was settled. Detachment is your weak spot, explaining a feeling rather than feeling it, which leaves loved ones out in the cold. Freedom is your comfort this year.",
      "pisces": "With the solar return Moon in Pisces, your year feels dreamy, tender and compassionate. Your intuition is sharp, and you absorb the moods of everyone around you, so a crowded shop leaves you oddly drained. Music, art, water and long sleeps restore you, and you cry more easily at films. You are the friend people confide in, and you feel their pain as though it were your own. Blurred boundaries are the trouble, rescuing others or drifting into escape when life feels harsh. You trust your gut this year, and checking the facts before you act lets that intuition serve you beautifully."
    }],
    ["progressions.planets", {
      "sun": "When your progressed Sun makes an aspect to a natal planet, that planet's theme moves to the centre of your identity for a year or two. You feel it as a slow shift in what you care about, the moment you realise a job, relationship or ambition has become part of who you are. Important life decisions cluster here: committing, leaving, or beginning something that shapes the next decade. People around you notice that you seem more certain of yourself. Growth rarely feels comfortable, though, and old roles pinch for a while before you let them go. By the end of the aspect you recognise yourself more clearly than before.",
      "moon": "A progressed Moon aspect to a natal planet colours your emotional life for a few weeks to a few months. That planet's theme shows up in your daily moods: what you crave at the end of the day, what makes you tearful, who you want to call. You feel restless in a way you cannot quite explain, and then a small event makes the reason obvious. These aspects come and go regularly, so each one works like a chapter heading for what your feelings are processing now. The harder side is treating a passing mood as if it were permanent. Noticing the pattern gives you a gentle map of your inner weather.",
      "mercury": "When your progressed Mercury aspects a natal planet, your thinking around that planet's theme begins to change. You start a course, write something that matters to you, or catch yourself arguing the opposite of a view you held for years. Conversations take on new weight, and you choose your words more deliberately. A book or a single remark from a friend opens a door in your mind. The awkward part is the stretch of confusion, when the old way of thinking no longer fits and the new one has not yet settled. Over the following months you come to speak and reason in a way that feels more your own.",
      "venus": "A progressed Venus aspect marks a meaningful chapter in love, friendship, taste and money. What you value shifts slowly: you redecorate, change your style, or find that a particular friendship means more than it did. Sometimes a new attraction arrives, and sometimes an existing relationship warms after a cool spell. Your sense of self-worth grows, and you stop settling for less than you deserve. The pitfall is indulgence, overspending or reaching for someone because you feel lonely. This period teaches you, gently and over time, what you find beautiful and whom you want close.",
      "mars": "When your progressed Mars aspects a natal planet, you feel a rise in drive, courage and sometimes conflict around that planet's theme. You finally act on something you have talked about for years: you quit the job, start the business, or stand up to someone who has pushed you around. Energy comes more easily, and waiting feels unbearable. Tempers flare too, and you notice you are quicker to argue in traffic or at work. Pushing so hard that you burn out, or making enemies where allies were possible, is the danger. Handled with some care, this period gives you a new confidence in your own force.",
      "asc": "An aspect involving your progressed Ascendant shifts how you present yourself and meet the world. You change your hair, your clothes or the way you walk into a room, often without planning it. Personal circumstances shift as well: a move, a new role, a change in your daily surroundings. People begin to treat you differently, and strangers respond to a new kind of confidence or softness in you. Sometimes you feel caught between the old image and the new one, unsure which is you. Over time the outer you catches up with the person you have been becoming inside.",
      "mc": "An aspect involving your progressed Midheaven coincides with a change in career direction, public role or life goals. You feel a pull towards work that means more, or you find yourself promoted, retrained or visible in a new way. What you want to be known for becomes a pressing concern rather than a vague someday thought. Your reputation shifts, sometimes through a single decision others notice. The tricky part is letting go of an ambition you have outgrown, particularly one you worked hard to reach. As this period unfolds, your vocation reshapes itself around who you are now."
    }],
  ];
  for (const [path, data] of R) apply(path, data);
})();
